INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('28e6abf1d91043dc955b21bd914ce9f9', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Duffy Café', NULL, '{"email": "orders@duffypng.com", "phone": "675 325 85 28", "website": "https://duffypng.com/", "facebook": "https://www.facebook.com/duffypng/timeline"}', '<p>Speciality coffee house, French inspired bakery and cafe. Located on Gabaka Street, with two other outlets at Harbourside and Jackson’s International Airport. Full bakery including sweets, breads, pastries and cakes Full all day menu.</p>', NULL, '{"name": "Duffy Café", "type": "restaurant", "latitude": -9.45427, "longitude": 147.19459}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800084261_duffy-baguettes.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800089650_duffy01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800094113_duffy02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800099379_duffy03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800103786_duffy-baguettes.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800111432_duffy-bakery.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800115201_duffy-fuzzy-wuzzy-blend.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800123231_photo1jpg.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800126666_snickers-and-mars-thick.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733800131777_strawberry-cream-milkshake.jpg}', '2025-01-22 03:06:14.225177+00', '2025-01-22 03:06:14.225177+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('24a87376bc7849169fee5ac648a0c5b1', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Vision City Mega Mall & Paradise Cinemas', NULL, '{"phone": 6753028555, "website": "http://www.visioncitypng.com/"}', '<p>Vision City Mega Mall is the largest and most successful mall in the country today. With over 70 shops covering 4 floors, a one-stop-shop retail complex offering the best deals and the finest options in every category. It also provides products and services to suit every shopper’s needs.</p><p>Open daily from 9am until 10pm</p>', NULL, '{"name": "Vision City Mega Mall & Paradise Cinemas", "type": "adventure_activities", "latitude": -9.43815, "longitude": 147.181}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733649886658_VISION%20CITY%2001.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733649895220_VISION%20CITY%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733650348274_VISION%20CITY%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733650305226_VISION%20CITY%2003.jpg}', '2025-01-22 03:06:14.246155+00', '2025-01-22 03:06:14.246155+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('5603a099ca53484dbd7f1e881649c2f9', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Remembrance Park', NULL, '{}', '<p>Port Moresby Remembrance Park located off Ela Beach on Healy Rd, consists of a remembrance gate for 129 local WW1 casualties and also several WW2 memorials. Rememberance Day services are officially observed here</p>', NULL, '{"name": "Remembrance Park", "type": "adventure_activities", "latitude": -9.47964, "longitude": 147.16419}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733648253923_rememberance%20park.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733648263679_rememberance%20park.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733649756353_rememberance%20park04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733649769094_rememberance%20park02.jpg}', '2025-01-22 03:06:14.267182+00', '2025-01-22 03:06:14.267182+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('84ca83c0125f4380893675a86f45b18a', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Papua New Guinea Parliament House', NULL, '{"phone": 67574393146, "website": "https://www.parliament.gov.pg"}', '<p>The Parliament House in Port Moresby is one of the most iconic attractions in the capital. Designed to reflect the traditional architecture and murals of the local tribes, It is the People''s House or Parliament House of PNG, an impressive towering structure of a building at Waigani that hosts the past, present and future of Papua New Guinea. It embodies a forward thinking government while firmly holding on to the traditions of its people.</p><p>Stroll through the surrounding well kept gardens and escape the hustle of the city. The building was opened by His Royal Highness, Prince Charles in 1984, just 20 years after the Parliament was first created. What you need to know: Tours are available every week day and can be arranged on site. The grounds have a dress code so please dress appropriately. Among the restrictions are no cut jeans, dirty or torn clothes and thongs.</p>', NULL, '{"name": "Papua New Guinea Parliament House", "type": "adventure_activities", "latitude": -9.42789, "longitude": 147.19189}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733467104161_PARLIAMENT%20HOUSE.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466684818_PARLIAMENT%20HOUSE.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466696490_PARLIAMENT%20HOUSE02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466994934_PARLIAMENT%20HOUSE03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733467002776_PARLIAMENT%20HOUSE04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733467007472_PARLIAMENT%20HOUSE05.jpg}', '2025-01-22 03:06:14.289154+00', '2025-01-22 03:06:14.289154+00');
