INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('d68e2b60d83449bcba8e25a8b71ae125', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'National Museum & Art Gallery ', NULL, '{"email": "nationalmuseum@museumpng.gov.pg", "phone": "675 325 2405", "facebook": "https://www.facebook.com/www.museumpng.gov.pg"}', '<p>Port Moresby''s national museum &amp; gallery. Showcasing collections on archeology, anthropology, art &amp; warfare</p>', '', '{"name": "National Museum & Art Gallery", "type": "adventure_activities", "latitude": -9.42545, "longitude": 147.18983}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466156017_MUSEUM_ART_GALLERY_PNG02.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466181523_MUSEUM_ART_GALLERY_PNG03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466188969_MUSEUM_ART_GALLERY_PNG02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733466192672_MUSEUM_ART_GALLERY_PNG.jpg}', '2025-01-22 03:06:14.317224+00', '2025-01-22 03:06:14.317224+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e9a56e30dd4f4803ac4d94d76d944c84', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Royal Port Moresby Golf Club', NULL, '{"phone": "675 2078367", "website": "https://www.royalportmoresby.com"}', '<p>Nestled in the heart of Port Moresby, our championship golf course beckons enthusiasts and novices alike to experience the thrill of the game in a truly regal setting.</p>', NULL, '{"name": "Royal Port Moresby Golf Club", "type": "adventure_activities", "latitude": -9.42253, "longitude": 147.19231}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733467295859_ROYAL%20PM%20GOLF02.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733647965844_ROYAL%20PM%20GOLF03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733647978448_royal+golf+club+04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733647992039_royal%20golf%20club%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733648168975_ROYAL%20PM%20GOLF02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733648000816_ROYAL%20PM%20GOLF.jpg}', '2025-01-22 03:06:14.34122+00', '2025-01-22 03:06:14.34122+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('32324c9e73bb4d2b8286b6c81daab4be', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Port Moresby City Markets At National Art Gallery', NULL, '{"email": "mariem@pascoegroup.com", "phone": "675 7906 5091", "facebook": "https://www.facebook.com/pomcitymarkets"}', '<p>POM citys most popular craft market held every month on the grounds of the National Museum and Art Gallery Entry K2 with ample parking</p>', NULL, '{"name": "Port Moresby City Markets At National Art Gallery", "type": "adventure_activities", "latitude": -9.42545, "longitude": 147.18983}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733651404227_POM%20CITY%20MARKET%2002.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733651426198_POM%20CITY%20MARKET%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652258610_HI_MARKET02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652268812_HI_MARKET01.jpg}', '2025-01-22 03:06:14.362124+00', '2025-01-22 03:06:14.362124+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('7f955f9cddba4b2d8939ccd7bcf4a2dc', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Port Moresby City Markets Ela Beach Craft Market', NULL, '{"email": "mariem@pascoegroup.com", "phone": "675 7906 5091", "facebook": "https://www.facebook.com/pomcitymarkets"}', '<p>You might want to plan your trip to Port Moresby taking into consideration the country’s best market, Ela Beach Craft Market, which takes place on the last Saturday of every month. Traditional crafts from all over the country can be found here – the best there is – larger-than-life carvings, bilums, tribal adornments, baskets and more. But the highlight comes in the form of art. Art galleries are not common in PNG, so art lovers will relish the local art on display here, perhaps the sole place from where you can buy paintings from contemporary artists. This is a truly unique market where you can meet some of the nation’s most famous painters.</p>', NULL, '{"name": "Port Moresby City Markets Ela Beach Craft Market", "type": "adventure_activities", "latitude": -9.47938, "longitude": 147.15619}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652023894_POM+CITY+MARKET+012.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652031845_POM%20CITY%20MARKET%2009.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652059651_POM+CITY+MARKET+012.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652070749_POM%20CITY%20MARKET%2003.jpg}', '2025-01-22 03:06:14.383234+00', '2025-01-22 03:06:14.383234+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('c3b29366ee7c4b0b9d3b0953c6d913ac', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Port Moresby City Markets Harbourside Night Market', NULL, '{"email": "mariem@pascoegroup.com", "phone": "675 7906 5091", "facebook": "https://www.facebook.com/pomcitymarkets"}', '<p>Located at the harbourside precint in downtown Port Moresby. Market goers will find an aray of Papua New Guinean arts, crafts and fashin on sale. Enjoy live band entertainments, plenty of dining at the nearby restaurants while enjoing the beautiful views of the Fairfax Harbour</p>', NULL, '{"name": "Port Moresby City Markets Harbourside Night Market", "type": "adventure_activities", "latitude": -9.47681, "longitude": 147.14902}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733651960117_POM%20CITY%20HARBOURSIDE%20NIGHT%20MARKET%2002.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733651965184_POM%20CITY%20HARBOURSIDE%20NIGHT%20MARKET%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733651980450_POM+CITY+MARKET+011.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733651990428_POM%20CITY%20MARKET%2008.jpg}', '2025-01-22 03:06:14.405183+00', '2025-01-22 03:06:14.405183+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('da37dc08286d4c8081211e3eed465e9a', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Bougainville Pride Arts & Craft', NULL, '{"facebook": "https://www.facebook.com/profile.php?id=100078451532436"}', '<p>Bougainville Pride Arts &amp; Craft Located in Port Moresby, specializing in producing beautiful bespoke, hand woven cane goods, jewellery and pottery</p>', NULL, '{"name": "Bougainville Pride Arts & Craft", "type": "adventure_activities", "latitude": -9.44579, "longitude": 147.18162}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733650801396_POM%20CITY%20MARKET%2004.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733652216964_HI_MARKET03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733650825104_POM%20CITY%20MARKET%2004.jpg}', '2025-01-22 03:06:14.434229+00', '2025-01-22 03:06:14.434229+00');
