INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('0d2466a7d0da4c3caa7dea254c88155b', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Roku Beach', NULL, '{}', '<p>Roku Beach, located in the picturesque Roku area, is a coastal haven that promises a serene escape surrounded by natural beauty. Bathroom facilities and parking available. Enjoy a swim or bring a picnick to enjoy the scenery and sea breeze. Dining available at local restaurants or explore nearby hiking trails that offer breathtaking vistas and opportunities for bird watching and a chance to immerse yourself in the local culture.</p>', NULL, '{"name": "Roku Beach", "type": "adventure_activities", "latitude": -9.46358, "longitude": 147.0936}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733704539273_ROKU%20BEACH01.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733704543804_ROKU%20BEACH02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733704549879_ROKU%20BEACH.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733704556725_ROKU%20BEACH01.jpg}', '2025-01-22 03:06:14.455176+00', '2025-01-22 03:06:14.455176+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('100b508f53274fc48b1111349df4c088', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Machine Gun Beach', NULL, '{}', '<p>Machine Gun beach is one of the most picturesque swimming beaches popular with locals and tourists alike. Located in Madang, known as the Prettiest Town inthe Pacific. Located on the northern coast of Papua New Guinea.</p>', NULL, '{"name": "Machine Gun Beach", "type": "adventure_activities", "latitude": -5.22518, "longitude": 145.80684}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656269802_MACHINE+GUN+BEACH02.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655435104_MACHINE%20GUN%20BEACH.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656243097_MACHINE+GUN+BEACH02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656250818_MACHINE+GUN+BEACH03.jpg}', '2025-01-22 03:06:14.476154+00', '2025-01-22 03:06:14.476154+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('1539435a9df74ca88b88726eec1e443a', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Indigenous Kokoda Adventures', NULL, '{"email": "info@indigenouskokodaadventures.com", "phone": "675 7464 0056 or +675 7597 8842", "website": "https://indigenouskokodaadventures.com"}', '<p>Indigenous Kokoda Adventures is a registered official tour operator, under the PNG Investment Promotion Authority (IPA) Act and also licensed through the Kokoda Track Authority (KTA) to operate as a tour company on the Kokoda Track in Papua New Guinea.Try a custom made tour and treck through villages and trails, or an up close and personal connection with the people and cultural tour designed for small groups from 2 up to 8 people. Come join us on the Kokoda Track and experience the beauty and history of this incredibly unique place for yourself. We can’t wait to share it with you!</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657339483_kokoda02.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657277267_kokoda01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657292243_kokoda02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657025900_ika_logo_official.png}', '2025-01-22 03:06:14.498197+00', '2025-01-22 03:06:14.498197+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('1e5aff2845cb4ce1a24b9641697ff238', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Varirata National Park', NULL, '{"phone": "675 7467 8752", "facebook": "https://www.facebook.com/Varirata/"}', '<p>PNG''s first National Park known for its breathtaking views of Port Moresby and the Central coast. The park is popular for school excursions, bird-watching as it is home to 6 of the more than 40 bird of paradise species, weekend outings for city residents, and nature tours.</p>', NULL, '{"name": "Varirata National Park", "type": "adventure_activities", "latitude": -9.45375, "longitude": 147.35924}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655037437_VARIRATA+NATIONAL+PARK05.jpeg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655047752_VARIRATA%20NATIONAL%20PARK06.jpeg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655080380_VARIRATA%20NATIONAL%20PARK07.jpeg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655097477_VARIRATA+NATIONAL+PARK05.jpeg}', '2025-01-22 03:06:14.519214+00', '2025-01-22 03:06:14.519214+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('245f31e3d5cc492e9ff888f2412e10cd', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Davage Beach', NULL, '{}', '<p>Davage Beach located at the western end of Boera village which is about a 30 minute drive outside of our capital Port Moresby. With plenty of space and shade to go swimming or bring your own picnic and sit in the shade and enjoy the soothing ocean breezes. Explore the attractions surrounding Davage Beach, from nearby landmarks to hiking trails that allow you to immerse yourself in the area''s natural beauty and cultural heritage.</p>', NULL, '{"name": "Davage Beach", "type": "adventure_activities", "latitude": -9.38245, "longitude": 147.01146}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702589751_DAVAGE%20BEACH%2004.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702507303_DAVAGE%20BEACH%2001jpg.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702519018_DAVAGE%20BEACH%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702525925_DAVAGE%20BEACH%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702528500_DAVAGE%20BEACH%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702562824_DAVAGE%20BEACH%20PICNIC%20AREA.jpg}', '2025-01-22 03:06:14.541285+00', '2025-01-22 03:06:14.541285+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('2a769494891e42b39afbd236c7c7fb21', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Bomana War Cemetary', NULL, '{}', '<p>Bomana War Cemetery, the largest war cemetery in the Pacific is about 19 kilometres north of Port Moresby. The cemetery is located on the Sogeri Road not far from the Sir Hubert Murray Highway. Thousands of young Australian and Papua New Guinean soldiers are buried in this carefully tendered WWII cemetery, which is a sad reminder of the horrific campaigns in the region. It was started in 1942 by the Australian army and is the only Papua New Guinea cemetery to contain white marble stones and a Stone of Remembrance. It contains 3779 graves.</p>', NULL, '{"name": "Bomana War Cemetary", "type": "adventure_activities", "latitude": -9.39527, "longitude": 147.25112}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733701016192_BOMANA%20WAR%20MEMORIAL03.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733701020550_BOMANA%20WAR%20MEMORIAL.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733701025076_BOMANA%20WAR%20MEMORIAL02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733701036832_BOMANA%20WAR%20MEMORIAL03.jpg}', '2025-01-22 03:06:14.562276+00', '2025-01-22 03:06:14.562276+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('00000000000000000000000000000019', 'f', 'overlay', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Vanuatu', 'DO NOT change', '{}', NULL, 'AreaManagedEndpoint', NULL, NULL, NULL, NULL, '2025-01-22 03:06:17.309298+00', '2025-01-22 03:06:17.309298+00');
