INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('3e1cf5bb9850441099af38c1ac27d97d', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Ela Beach', NULL, '{}', '<p>Ela Beach, located in the vibrant city of Port Moresby, is a popular coastal destination known for its stunning beauty and inviting ambiance. Discover historical facts dotted along the beach, dine at one of the many restaurants enjoying its scenic setting, a range of activities, and nearby attractions, this beach presents a relaxing getaway where you can unwind, explore, and embrace the local culture.</p>', NULL, '{"name": "Ela Beach", "type": "adventure_activities", "latitude": -9.47899, "longitude": 147.15616}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733701750553_ELA%20BEACH.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733701755163_ELA%20BEACH02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702065441_ELA%20BEACH03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702072506_ELA%20BEACH04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702080915_ELA%20BEACH05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733702087687_ELA%20BEACH.jpg}', '2025-01-22 03:06:14.584218+00', '2025-01-22 03:06:14.584218+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('437fe876a4204466802e00c61ab3e77b', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'National Orchid Garden', NULL, '{}', '<p>Papua New Guinea''s National Orchid Garden is located on the same premises as the popular Adventure Park, opposite the Pacific Adventist University at 14-Mile on the outskirts of Port Moresby. The National Orchid Garden showcases hundreds of hybrid and pedigreed orchids - many of which are native to Papua New Guinea, it is the largest in the southern hemisphere. Entry allows you to access the aviary walkthrough.</p>', NULL, '{"name": "National Orchid Garden", "type": "adventure_activities", "latitude": -9.39321, "longitude": 147.27689}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655299228_NATIONAL%20ORCHID%20GARDEN.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655306028_NATIONAL%20ORCHID%20GARDEN02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655312644_NATIONAL+ORCHID+GARDEN03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655319330_NATIONAL+ORCHID+GARDEN04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655331685_NATIONAL%20ORCHID%20GARDEN.jpg}', '2025-01-22 03:06:14.604242+00', '2025-01-22 03:06:14.604242+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('a5d9e37965c249e6b0d7694cb722f627', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Adventure Park and National Orchid Garden', NULL, '{"phone": "675 7090 6819", "website": "https://papuanewguinea.travel/business/adventure-park/", "facebook": "https://www.facebook.com/adventureparkpapuanewguinea/"}', '<p>In the first 18 months of operation Adventure Park attracted 70,000 visitors, It is a safe family, friendly recreational park that offers all day fun for residents, tourists and school excursions. Port Moresby Adventure Park located at 14 Mile, features waterslides, picnic facilities, the southern hemisphere’s largest collection of orchids, and its own resident crocodile. It''s fun for all ages! one can go fishing from the shores or on a paddle boat in the middle of the lake or enjoy an eventful day from water slides to wildlife encounters that are on display. Entry to the park is free, with the on-site activities each attracting a small fee.</p>', NULL, '{"name": "Adventure Park and National Orchid Garden", "type": "adventure_activities", "latitude": -9.39397, "longitude": 147.2759}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655348680_PNG%20ADVENTURE%20PARK.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655354600_PNG%20ADVENTURE%20PARK03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655359949_PNG%20ADVENTURE%20PARK02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655370189_PNG+ADVENTURE+PARK04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733655378257_NATIONAL%20ORCHID%20GARDEN02.jpg}', '2025-01-22 03:06:14.626139+00', '2025-01-22 03:06:14.626139+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('a62807c3812743cf81d4e0142471b126', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'PRO Dive PNG', NULL, '{"email": "prodivepng2@gmail.com", "phone": "675 7194 9333", "website": "https://www.prodivepng.com/"}', '<p>PRO Dive is one of the oldest and the most prominent dive operators in Papua New Guinea. Running since 1995.</p>', NULL, '{"name": "PRO Dive PNG", "type": "adventure_activities", "latitude": -9.50714, "longitude": 147.28716}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657914166_diving.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657925279_diving01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657931019_diving02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657941518_diving04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657920353_diving.jpg}', '2025-01-22 03:06:14.646229+00', '2025-01-22 03:06:14.646229+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e734ccddc32a43f49ce73d7335585794', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Adventure Kokoda', NULL, '{"email": "https://www.kokodatreks.com/contact-us/", "phone": 1300783303, "website": "https://www.kokodatreks.com"}', '<p>Kokoda Treks, run by Major Charlie Lynn, built his company with former army colleagues including military historian, Lieutenant Colonel Rowan Tracey; decorated Vietnam Veteran, Major Chad Sherrin MM; PNG adventurer, Captain Reg Yates; and Navy Commodore Simon Hart CSC. Today they have 12 trek leaders who have been trained by our leadership group and are without peer as expedition leaders on the Trail due to their understanding of the military strategies and tactics related to each battle. Try one of their 8 or 10 day trecks designed for groups who want to experience the physical challenge of the Kokoda Trail across the original wartime route. Prices range from $3500 - $5000 with meals, accomodation and trek fees included.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656849544_ADVENTURE%20KOKODA05.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656317764_ADVENTURE%20KOKODA02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656821634_ADVENTURE%20KOKODA03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656827973_ADVENTURE%20KOKODA04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656834323_ADVENTURE%20KOKODA05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733656842976_ADVENTURE%20KOKODA%2001.png}', '2025-01-22 03:06:14.667258+00', '2025-01-22 03:06:14.667258+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e763ee32cce5466397752b4ad3da9beb', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Kokopo Beach East New England', NULL, '{}', '<p>Kokopo Beach: Kokopo Beach is a stunning beach located near the city center. It is a popular spot for swimming and snorkeling</p>', NULL, '{"name": "Kokopo Beach East New England", "type": "adventure_activities", "latitude": -4.34213, "longitude": 152.27469}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733658007852_kokopo%20beach%2001.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733657990690_diving05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733658018841_kokopo%20beach%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733658031505_kokopo%20beach%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733658045519_kokopo%20beach%2003.jpg}', '2025-01-22 03:06:14.6872+00', '2025-01-22 03:06:14.6872+00');
