INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('10e8867acb72410cae453e2a1164d4c8', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Darwin Museum Underground WWII Oil Storage Tunnels', NULL, '{"phone": "0408 795 434", "website": "http://ww2tunnelsdarwin.com.au/"}', 'Go back in time to Darwin''s Top Secret WW2 Oil Storage Tunnels an underground heritage museum like no other. The subterranean tunnels are one of Darwin''s best value tourist attractions.', NULL, '{"name": "Darwin Museum Underground WWII Oil Storage Tunnels", "type": "entertainment", "latitude": -12.46736958, "longitude": 130.845173}', NULL, NULL, NULL, '2025-01-22 03:06:15.092217+00', '2025-01-22 03:06:15.092217+00');
