INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('bf2999f706cb4bb782bb174f40fa87e0', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'RFDS Darwin Royal FLying Doctors Service Tourist Facility', NULL, '{"email": "rfdsdarwin@flyingdoctor.net", "phone": "08 89835700", "website": "http://www.rfdsdarwin.com.au/", "facebook": "http://facebook.com/flyingdoctorsant", "instagram": "https://au.linkedin.com/company/royalflyingdoctorservice"}', 'Interactive historical museum. Experience the history of the RFDS. Relive the true experience of patient Gene Hildebrand and see what it’s like to fly with an RFDS Pilot through our immersive VR experience. Come aboard our decommissioned RFDS Pilatus PC-12 aircraft ‘PAPA’. From the cockpit to the cargo hold, this fully equipped aircraft is an experience like no other. Watch a life-size hologram of RFDS Founder, John Flynn, as he tells his story of the birth and growth of the RFDS. Join our guided tour or go it alone as you learn the history of the RFDS through interactive touchscreen portals, storyboards and decommissioned equipment, including a real Traeger pedal radio.', NULL, '{"name": "RFDS Darwin Royal FLying Doctors Service", "type": "entertainment", "latitude": -12.47024105, "longitude": 130.8491302}', NULL, NULL, NULL, '2025-01-22 03:06:15.153254+00', '2025-01-22 03:06:15.153254+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('50fb7d6b38bb4a5a9c45176342bd463a', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Darwin Cenotaph War Memorial', NULL, '{"website": "https://www.awm.gov.au/"}', 'Bicenntenial Park', NULL, '{"name": "Darwin Cenotaph War Memorial", "type": "parks_and_nature", "latitude": -12.46644456, "longitude": 130.8400733}', NULL, NULL, NULL, '2025-01-22 03:06:15.197282+00', '2025-01-22 03:06:15.197282+00');
