INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('169578d9c25346acb708e4aa483f8d5e', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', '00Seven Jet Ski Adventures', NULL, '{"phone": "0427 007 000", "website": "https://www.00seven.com.au/", "facebook": "https://www.facebook.com/00sevenjetski/", "instagram": "https://www.instagram.com/00sevenjetski"}', 'Come and join us on our guided Jet-ski tour where you will not only pass by some of the most beautiful coastal locations around Darwin but get the chance to see some of our magnificent marine life, drift over our famous WW2 wrecks while our guide shares some history of what rests beneath our beautiful waters and even relax with the sand between your toes on a deserted sandbar. Get tickets from Crocosaurus Cove, Online or call 00Seven Jetski Adventures', NULL, '{"name": "00Seven Jet Ski Adventures", "type": "entertainment", "latitude": -12.46794525, "longitude": 130.8505177}', NULL, NULL, NULL, '2025-01-22 03:06:15.259158+00', '2025-01-22 03:06:15.259158+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('96ff43d677ba49c6bcae00bedfb76744', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Road Masters House Museum', NULL, '{"phone": "08 89812848", "website": "https://www.nationaltrust.org.au/places/the-roadmasters-house/"}', 'Roadmasters House was built to accommodate the staff of the North Australia Railway (NAR). The date of construction of the building is not known but was most likely in the 1920s or 1930s. It was built to accommodate staff of the North Australia Railway (NAR) and was known as Roadmasters house. The Roadmaster was the officer responsible for track maintenance. It was occupied by NAR staff until damaged by Cyclone Tracy in 1974. Roadmasters House Museum documents the work of engineers and surveyors in the Northern Territory. In 2022 the museum exhibition is celebrating the Overland Telegraph Line Sesquicentenery.', NULL, '{"name": "Road Masters House Museum", "type": "entertainment", "latitude": -12.46493379, "longitude": 130.8473273}', NULL, NULL, NULL, '2025-01-22 03:06:15.301203+00', '2025-01-22 03:06:15.301203+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('98b9ee69a6d84b52a2ac9d98e62da495', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Aquascene Fish Feeding Sanctuary', NULL, '{"phone": "(08) 8981 7837", "website": "https://www.aquascene.com.au/"}', 'Aquascene is a popular fish feeding sanctuary in the heart of Darwin. Visit the fish at high tide when hundreds of friendly local wild fish swim to the shallow shoreline in search of a gratuitous meal of fresh bread. Over the course of this enduring 70 plus year tradition, the fish have shed their normal shyness and are willingly hand-fed to the delight of thousands of fascinated locals and tourists every year. Check our website for tide times and tickets. Adult: $15.00, Child (3-15 years): $10.00, Seniors: $10.00, Concession Card Holders: $10.00, Families (2 Adults plus 2 or 3 Children aged between 3-15): $43.00', NULL, '{"name": "Aquascene Fish Feeding Sanctuary", "type": "entertainment", "latitude": -12.45925401, "longitude": 130.8321416}', NULL, NULL, NULL, '2025-01-22 03:06:15.32232+00', '2025-01-22 03:06:15.32232+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('b2cace4b59854dc783c5dcd0cf40d9e3', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Darwin Waterfront Precinct', NULL, '{"email": "darwinwaterfront@nt.gov.au", "phone": "08 89995155", "website": "https://www.waterfront.nt.gov.au/", "facebook": "https://www.facebook.com/darwinwaterfront/", "instagram": "https://www.instagram.com/darwin.waterfront/"}', 'Bayside development with restaurants & bars, plus a wave pool & sandy beach for swimming.', NULL, '{"name": "Darwin Waterfront Precinct", "type": "entertainment", "latitude": -12.46715824, "longitude": 130.8467408}', NULL, NULL, NULL, '2025-01-22 03:06:15.343285+00', '2025-01-22 03:06:15.343285+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('f9897270b2bd43aa909c4710273b664f', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Deckchair Cinema', NULL, '{"email": "info@deckchaircinema.com", "phone": "(08) 89414377", "website": "https://www.deckchaircinema.com/", "facebook": "https://www.facebook.com/deckchaircinema", "instagram": "https://www.instagram.com/deckchaircinemadeckchair_cinema/"}', 'Get ready for an unforgettable cinematic experience under the stars at Deckchair Cinema. Nestled on the edge of Darwin Harbour, our outdoor setting boasts panoramic sunset views over the harbour, framed by a lush tropical garden and remnant rainforest. Deckchair Cinema is an unique outdoor cinema that offers an unparalleled movie experience. As an independent cinema operated by the Darwin Film Society, we take pride in showcasing an exclusive selection of films that are usually not available to local audiences. Each night of the dry season, we showcase a diverse selection of films, ranging from beloved family favourites to captivating Australian and foreign flicks.', NULL, '{"name": "Deckchair Cinema", "type": "entertainment", "latitude": -12.46746668, "longitude": 130.8423534}', NULL, NULL, NULL, '2025-01-22 03:06:15.368194+00', '2025-01-22 03:06:15.368194+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('3cf4a8d087ee4e27ac9a1330aad28bc6', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Darwin Aboriginal Art Gallery', NULL, '{"phone": "0418 894 356", "website": "https://www.australia-aboriginal-art.com/"}', '​The world renowned Australian Aboriginal Fine Arts Gallery. It''s relative proximity to the Torres Strait Islands, Arnhem Land and Central Australia places it strategically at the head of the indigenous art scene in Australia. Its for this same reason that the Telstra National Torres Strait Islander and Aboriginal Art Award are also held in Darwin each year. The upstairs gallery on the corner of Mitchell and Knuckey st has provided museums, galleries and private collectors from 43 different countries around the globe access to authentic traditional and contemporary Australian indigenous art for over quarter of a century now. The gallery has been operating for 29 years and paid over $4 millon to indigenous Artists', NULL, '{"name": "Darwin Aboriginal Art Gallery", "type": "entertainment", "latitude": -12.46350518, "longitude": 130.8407548}', NULL, NULL, NULL, '2025-01-22 03:06:15.388202+00', '2025-01-22 03:06:15.388202+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('6554988619fb4f7086fc3ed1121e6545', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Mbantua Gallery', NULL, '{"phone": "08 89416611", "website": "http://www.mbantua.com.au/"}', 'You wil find our Darwin based Gallery situated at Shop 2, The Mall, Darwin. We feature a large selection of Utopia region Aboriginal Art as well as a great range of gifts and homewares with a focus towards representing Australian and Aboriginal design products.', NULL, '{"name": "Mbantua Gallery", "type": "entertainment", "latitude": -12.46390209, "longitude": 130.8431996}', NULL, NULL, NULL, '2025-01-22 03:06:15.408192+00', '2025-01-22 03:06:15.408192+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('daee5eaaca3c4f44820df97fea28efaa', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Mason Gallery', NULL, '{"phone": "08 89819622", "website": "http://masongallery.com.au/"}', 'Welcome to Mason Gallery, where our extensive selection of authentic, Australian Aboriginal art has been collected primarily from throughout the Central and Western Desert regions, Utopia Aboriginal Lands of the Eastern Desert, Arnhem Land and across the Top End.', NULL, '{"name": "Mason Gallery", "type": "entertainment", "latitude": -12.46260656, "longitude": 130.8431179}', NULL, NULL, NULL, '2025-01-22 03:06:15.429226+00', '2025-01-22 03:06:15.429226+00');
