INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('22e773ba9aa44e16946c57dac4aaba42', 'f', 'overlay', 't', 'user_0000000000002_0000PAIDUSER', '{abb89d39fb0e4712b0d4f706b9a4562d,d005f36bc76a45058ef63b981b5434e2,e63b39759988450295bba3a7ea5d2c7d}', 'Restaurant', NULL, '{}', ' ', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733443778586_we-have-a-great-selection.jpg', NULL, '2025-01-22 03:06:15.690198+00', '2025-01-22 03:06:15.690198+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('fa9bd29ae92e46f28e3a355da04ab1e9', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Nightcliff Market', NULL, '{"phone": "0414 368 773", "facebook": "https://www.facebook.com/profile.php?id=100057230029051"}', '<p>The Market was started in 1996 at the Nightcliff Shopping Village and is popular with families. There is live music every week and a shady playground in the middle. It consists of fifteen food stalls selling fresh, local fruit and vegetables, delicious fruit smoothies and juices, freshly ground coffee, crepes, asian soups and curries, burgers and seafood. There are up to sixty other stalls selling clothing, arts and crafts, leather goods including crocodile products, jewelery, tarot, massage and books to name a few. Open every Sunday 8:30am – 2pm.</p>', NULL, '{"name": "Nightcliff Market", "type": "shop", "latitude": -12.3876332, "longitude": 130.8505878}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166874096_nightcliff.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166877399_nightcliff.jpg}', '2025-01-22 03:06:15.606309+00', '2025-02-10 05:54:50.841+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('765f7daae6ca4029abe0293492ad1bea', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Rapid Creek Markets', NULL, '{"phone": "08 89484866", "website": "https://rapidcreekmarkets.com.au/", "facebook": "https://www.facebook.com/RapidCreekMarkets", "instagram": "https://www.instagram.com/explore/locations/3267/rapid-creek-markets/"}', '<p>Darwin''s Oldest Market! Be a part of Northern Territory tradition and visit Darwin’s oldest market! Located in the heart of the northern suburbs, about 10km from Darwin CBD, the Rapid Creek Markets are open from 7am – 2pm every Saturday and Sunday – rain, hail or shine. Transforming the Rapid Creek Business Village into a bustling slice of Asia, the market delivers a vibrant experience of bright colours, rich aromas and exciting sounds. With more than 100 market stalls and stores, there’s plenty for you to see, do and discover!</p>', NULL, '{"name": "Rapid Creek Markets", "type": "shop", "latitude": -12.386673, "longitude": 130.862444}', NULL, NULL, NULL, '2025-01-22 03:06:15.514346+00', '2025-02-10 05:55:01.214+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('f65151c93163404db8bd26b87654aad8', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Malak Marketplace', NULL, '{"instagram": "https://www.instagram.com/malakmarketplace/"}', '<p>Darwin''s only organic farmer &amp; food market. Malak Marketplace opens at Chambers Crescent Car Park, from 4pm until 9pm every Saturday April to October. Featuring a range of local, gourmet and organic producers. Many of the growers are selling direct to the public and are happy to have a chat about what’s in season and how best to cook their products. Growers include Notley House Harvest (gourmet local produce), Prayer Farm Pastured Eggs (free-range, local eggs), Eva Valley Meats (NT, local, ethical, grass-fed beef and buffalo), Hu Organics (Certified organic products).</p>', NULL, '{"name": "Malak Marketplace", "type": "shop", "latitude": -12.3964415, "longitude": 130.9029666}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166982510_malakmarketplace.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166979820_malakmarketplace.jpg}', '2025-01-22 03:06:15.575219+00', '2025-02-10 05:56:26.157+00');
