INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('095bb968d6b64b0aa72a59a69cb625d5', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Sightseeing and Tours', NULL, '{}', 'KOKODA Trek Adventure. The Kokoda Track is the most famous adventure track in Papua New Guinea and is renowned as the location of the World War II battle between Japanese and Australian forces in 1942.<p>&nbsp;</p>Test your fitness and speak to our sales team to find a recommended group you can join for your next adventure. <p>&nbsp;</p>Book a tour, Reservations:1800 007 697, or contact Front Desk: 675-303-2000, <p>&nbsp;</p>Email: reservations.holidayinnandsuitesportmoresby@ihg.com', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733453560028_IKA%20kokodaFW_cultural-17.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733453539064_ADVENTURE%20KOKODA%2001.png}', '2025-01-22 03:06:15.980185+00', '2025-01-22 03:06:15.980185+00');
