INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('ae778e847ec345d9979abeaf0531cd2c', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Business Centre', NULL, '{}', 'A full range of meeting areas featuring our Ballroom, A large room with pillars in between and a small mini bar. Seats up to 500 persons, can be divided into 3 smaller rooms. <p>&nbsp;</p>The Kumul Room another large room with natural lighting. Seats up to 250 persons<p>&nbsp;</p>The Board Room with natural light, seats up to 30 persons. <p>&nbsp;</p>Catering available, office supplies, scan/print/copy services and meeting registration service available. Wifi access throughout the hotel.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733461591676_HolInn013.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733461775233_HolInn020.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449432021_confrence01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449437187_confrence02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733461759677_HolInn019.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449450066_confrence03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733461821096_HolInn013.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733463727805_HolInn021.jpg}', '2025-01-22 03:06:16.071161+00', '2025-01-22 03:06:16.071161+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('b6c9d43dc10647ba8c87629872bc3788', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Secretarial Services', NULL, '{}', 'We can provide secretarial services for our guests should you need it. We also have office supplies and printing services for your convenience.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449750597_reservations.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449760786_office01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449767679_reservations.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733461917000_HolInn012.jpg}', '2025-01-22 03:06:16.09113+00', '2025-01-22 03:06:16.09113+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('cc230ae9dd374ecd8499572ec0f5f27c', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Banquet Services', NULL, '{}', 'Banquet Service available from either of our two in house dining rooms. The Gekko Bar or the Kopi Haus. All guests can enjoy a breakfast buffet.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456928929_banquet08.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733455230903_kopi_haus01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733455236123_banquet06.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733455259894_kopi_haus02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733455281213_kopi_haus03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733449004191_banquet03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456783916_kopi_haus011.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733448983900_banquet01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733455171101_banquet07.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456836939_kopi_haus010.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733457187675_banquet09.jpg}', '2025-01-22 03:06:16.111132+00', '2025-01-22 03:06:16.111132+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('5359748487e844a985486fff44e659f5', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Convenience Shop', NULL, '{}', '<p>Pick up your essentials at the in house convenience store.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733801019516_1-2-shopping-png-pic.jpeg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1733801010839_1-2-shopping-png-pic.jpeg}', '2025-01-22 03:06:16.132308+00', '2025-01-22 03:06:16.132308+00');
