INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('f462ea8cfffc4ff69b67484fb91fcb41', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Guest Laundry', NULL, '{}', 'Suites have an in room laundry with washer and drier for your convenience. Dry cleaning pickup or laundry valet are available for all our guests', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733463245935_bathroom02.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733447842598_laundry01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733463325318_bathroom02.jpg}', '2025-01-22 03:06:16.195385+00', '2025-01-22 03:06:16.195385+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('1b93e7c037d746b6b9f6afec48cd81f0', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Reservations', NULL, '{}', 'To make arrangements for a room reservation or any other booking please contact one of our friendly staff for assistance. <p>&nbsp;</p>Front desk: 675-303-2000<p>&nbsp;</p>Reservations: 675-303-2000', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733445765331_reservations.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733445775734_reservations.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733445783227_hotel-lobby03.jpg}', '2025-01-22 03:06:16.216246+00', '2025-01-22 03:06:16.216246+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('3ae6c7b4a15d47a9bb3a9d0369751c0e', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Luggage', NULL, '{}', 'If you need to store your luggage prior to check in or check out, please see our friendly staff at the front desk to assist you.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733446667306_luggage.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733446493928_luggage.jpg}', '2025-01-22 03:06:16.236232+00', '2025-01-22 03:06:16.236232+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('dd79c917c7f44c699dd34ad94102e137', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Lost Property', NULL, '{}', 'Should you need assistance regarding any lost property, please see one of our friendly staff to assist you or contact the front desk: 675-303-2000', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456568880_HolInn07.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733446621987_luggage.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456580644_HolInn03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733446140664_hotel-lobby03.jpg}', '2025-01-22 03:06:16.256163+00', '2025-01-22 03:06:16.256163+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('fd8974bd35e44f2999e9648ecc2db2ea', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Check In / Check Out', NULL, '{}', 'Check-in: 2:00 pm<p>&nbsp;</p>Check-out: 11:00 am. <p>&nbsp;</p>Late check-out available​. Minimum check-in age: 18 years old. <p>&nbsp;</p>Front desk: 675-303-2000, <p>&nbsp;</p>Reservations: 675-303-2000, <p>&nbsp;</p>Email: reservations.holidayinnandsuitesportmoresby@ihg.com', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733446713894_hotel-lobby03.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733446000283_hotel-lobby2.jpg}', '2025-01-22 03:06:16.278226+00', '2025-01-22 03:06:16.278226+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('0ca21f87056e415585851fca898e1e98', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Transport', NULL, '{}', 'Taxi Service is available. Please contact reception desk for assistance. Front desk: 675-303-2000', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733458741978_holiday-inn-port-moresby-02.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733457669281_HolInn05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733458774171_entrance.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733458685180_holiday-inn-port-moresby-02.jpg}', '2025-01-22 03:06:16.29924+00', '2025-01-22 03:06:16.29924+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('1e19ad427dbb457da3da9b433272a21d', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Hotel Parking', NULL, '{}', 'Enjoy the convenience of complimentary parking during your stay at Holiday Inn &amp; Suites, adding an extra layer of ease and comfort to your travel experience. Flat terrain between parking and entrance, Number of wheelchair accessible parking spaces: 30, Ramp Access to Property, Ramp access to leisure facilites, Ramp Access to Hotel Restaurant, Parking drop-off point adjacent to entrance.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733444752322_hotel-exterior.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733444996088_entrance.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733444989490_hotel-exterior.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733458705919_holiday-inn-port-moresby-02.jpg}', '2025-01-22 03:06:16.319158+00', '2025-01-22 03:06:16.319158+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('dbaa1fa046aa4a328bef03da05d8dd3a', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Free Shuttle Service', NULL, '{}', 'Book and stay at the Holiday Inn &amp; Suites Port Moresby and enjoy our free shuttle service to and from the airport. Please call our direct line on +675 303 2000 for shuttle pick up.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733444258963_holiday-inn-port-moresby-9602806506-4x3.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733444833962_holiday-inn-port-moresby-9602806506-4x3.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733458650249_holiday-inn-port-moresby-02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733444850379_entrance.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733462938258_HolInn017.jpg}', '2025-01-22 03:06:16.341249+00', '2025-01-22 03:06:16.341249+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('a1339444790a4a5391566fa0cbae9f7f', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Faya Haus', NULL, '{}', 'You''ll discover an inviting escape, where friendly Melanesian hospitality meets an exceptional dining experience. Borne from the Pidgin work for "fire", Faya Haus offers a celebration of culinary delights that are fused and evolve from heat and fire!. The centrepiece of our newly rebranded restaurant includes our wood-fired pizza oven and Argentinian grills, offering fresh flavours and a unique Papua New Guinean culinary journey.<p>&nbsp;</p>Our wood-fired oven brings an array of delicious pizzas to life, from BBQ favourites to Italian classics like Capricciosa and Calzone. At the Argentinian grills, premium cuts of meat sizzle over open flames, cooked to perfection. Each dish has been thoughtfully crafted, blending rich, authentic flavours with a modern twist.', NULL, '{"name": "Big Boi Burger", "type": "restaurant", "latitude": -9.43631, "longitude": 147.18016}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009352376_Screen%20Shot%202024-12-24%20at%202.02.20%20pm.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009416887_Screen%20Shot%202024-12-24%20at%202.03.15%20pm.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009426140_Screen%20Shot%202024-12-24%20at%202.02.49%20pm.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009465539_Screen%20Shot%202024-12-24%20at%202.03.01%20pm.png}', '2025-01-22 03:06:16.362229+00', '2025-01-22 03:06:16.362229+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('b4df4303f5f8493b881371b9fe3428fd', 't', 'none', 'f', 'user_0000000000002_0000PAIDUSER', '{}', 'Duffy Café', 'Cafe & Bakery', '{}', 'PNG''s first specialty coffee house, French inspired bakery and cafe. Located on Gabaka Street, with two other outlets at Harbourside and Jackson’s International Airport. Using only the highest quality ingredients to create their delicious and beautiful breads, pastries, cakes and sweets. <p>&nbsp;</p>Full all day menu with a selection of hot breakfasts, smoothie bowls, toasties, signature meals such as burgers and wraps, salads and a great selection for the kids.', NULL, '{"name": "Duffy Café", "type": "restaurant", "latitude": -9.4549377, "longitude": 147.1945873}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442474916_duffy-bakery.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442487960_duffy-baguettes.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442501653_duffy-fuzzy-wuzzy-blend.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442509594_photo1jpg.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442517827_snickers-and-mars-thick.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442877273_duffy01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442522536_strawberry-cream-milkshake.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442884716_duffy02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442892492_duffy03.jpg}', '2025-01-22 03:06:16.389238+00', '2025-01-22 03:06:16.389238+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('73d3ac90d81441938ab77bd1c743d170', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Swimming Pool', NULL, '{}', 'Enjoy a cooling swim with the family in our outdoor swimming pool which caters to the kids in their own shallow pool. Located next to the Gekko Bar with poolside food and drink service available. Enjoy a drink under a shady pool umbrella or relax on a pool lounge. Open from 7am - 9pm', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733448476845_pool01.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733448493677_pool02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733454277465_pool03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456694839_pool05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733456681043_pool04.jpg}', '2025-01-22 03:06:16.410228+00', '2025-01-22 03:06:16.410228+00');
