INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('297df774139c431f9dd0b00501ed5dab', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Gekko Bar', 'Relaxed outdoor dining', '{}', 'Conveniently located in the garden and adjacent to the swimming pool. <p>&nbsp;</p>Take advantage of the sunlight and fresh air for a casual drink or snack in a garden setting.<p>&nbsp;</p>The Gekko Bar menu is available for viewing. Open 7 days a week from 12:00pm to 11:00pm. Please dial 2977 for more information.', NULL, '{"name": "Asia Aromas", "type": "restaurant", "latitude": -9.47702, "longitude": 147.14824}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735008529444_1.%20Gekko.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735008486172_Beer%20Garden%20at%20the%20Junction%20Logo.jpeg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735008509708_2.%20Gekko.png}', '2025-01-22 03:06:16.577183+00', '2025-01-22 03:06:16.577183+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('3de02af6b3a647dcab9705db2f9c4a7f', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'Faya Haus Restaurant', 'Wood Fired Pizza', '{}', 'You''ll discover an inviting escape, where friendly Melanesian hospitality meets an exceptional dining experience. <p>&nbsp;</p>Borne from the Pidgin work for "fire", Faya Haus offers a celebration of culinary delights that are fused and evolve from heat and fire!. <p>&nbsp;</p>The centrepiece of our newly rebranded restaurant includes our wood-fired pizza oven and Argentinian grills, offering fresh flavours and a unique Papua New Guinean culinary journey.<p>&nbsp;</p>Our wood-fired oven brings an array of delicious pizzas to life, from BBQ favourites to Italian classics like Capricciosa and Calzone. At the Argentinian grills, premium cuts of meat sizzle over open flames, cooked to perfection. Each dish has been thoughtfully crafted, blending rich, authentic flavours with a modern twist.', NULL, '{"name": "Lucky Lucky Restaurant", "type": "restaurant", "latitude": -9.47676, "longitude": 147.15254}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733440656008_lucky_lucky_05_.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009713603_Screen%20Shot%202024-12-24%20at%202.07.42%20pm.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009719108_Screen%20Shot%202024-12-24%20at%202.02.49%20pm.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009727379_Screen%20Shot%202024-12-24%20at%202.03.01%20pm.png}', '2025-01-22 03:06:16.598239+00', '2025-01-22 03:06:16.598239+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e012b6d9fa0641888bd41b531dfe8f89', 't', 'none', 't', 'user_0000000000002_0000PAIDUSER', '{}', 'The Junction Bar', 'Live entertainment and big screen sport!', '{}', 'Join us for the Ultimate Trivia Night tonight – fun, friendly competition, and great prizes await! Whether you''re a trivia pro or just up for a challenge, you won''t want to miss this!', NULL, '{"name": "Spices Indian Restaurant", "type": "restaurant", "latitude": -9.4426, "longitude": 147.18004}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735009009197_6.%20Gekko.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735008978070_Beer%20Garden%20Band.jpeg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1735008993065_Beer%20Garden%20Food%20Truck.jpeg}', '2025-01-22 03:06:16.62625+00', '2025-01-22 03:06:16.62625+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('1ff58336f2f541d4a33f8fe6f2b1ea30', 't', 'none', 'f', 'user_0000000000002_0000PAIDUSER', '{}', 'Italian Gelato', NULL, '{}', 'Italian Gelato shop at the Vision City Mall. Bring the family and enjoy a dessert from the largest selection of flavours in town, no one will be dissapointed. Mix and match delicious gelato on freshly made crispy wafer cones.', NULL, '{"name": "Italian Gelato", "type": "restaurant", "latitude": -9.43797, "longitude": 147.18195}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441849643_italian-gelato-manufactures.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441858083_our-crunchy-waffle-cones.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442297456_italian-gelato%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441866147_italian-gelato.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441873968_italian-gelato%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733442282655_italian-gelato-02.jpg}', '2025-01-22 03:06:16.648386+00', '2025-01-22 03:06:16.648386+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('d3f5ced3f0044162a7f872093a0d5e40', 't', 'none', 'f', 'user_0000000000002_0000PAIDUSER', '{}', 'The Italian Restaurant', NULL, '{}', 'Enjoy the taste of Italian &amp; mediterranean classics and pizzas fresh from the oven. The ambient venue is the perfect place to dine either indoors or on the piazza. for family and friends outings and for special occasions. Vegan friendly. Reservations can be made with specific requests to ensure your dining experience is a memorable experience. Delivery, Takeout, Reservations, Outdoor Seating, Parking Available, Free off-street parking, Highchairs Available, Wheelchair Accessible, Serves Alcohol, Full Bar, Wine and Beer, American Express, Mastercard, Visa, Digital Payments, Accepts Credit Cards, Table Service, Family style, Non-smoking restaurants, Gift Cards Available', NULL, '{"name": "The Italian Restaurant", "type": "restaurant", "latitude": -9.44278, "longitude": 147.17975}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441787780_the-best-pizza-with-the.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441797573_amazing-crunchy-thin.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441804831_fresh-fire-oven-baked.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441812149_it-all-starts-with-a.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441820743_you-have-a-choice-of.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/BladeDiao/1733441828263_we-have-a-great-selection.jpg}', '2025-01-22 03:06:16.669246+00', '2025-01-22 03:06:16.669246+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('79db602593f74e2083ea1b4425697f6b', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Le Petit Chef', 'An enchanting fusion of gastronomy and storytelling.', NULL, 'Experience the enchanting fusion of gastronomy and storytelling at Hilton Darwin. Embark on a culinary journey like no other, where dining meets technology in a truly immersive experience. For the first time ever in Australia, step into the world of Le Petit Chef, the world''s tiniest chef, who breathes life into captivating stories through mesmerizing 3D Projection Mapping technology. Guests have the option to choose from the Grand Chef Menu, Classic Menu, Vegetarian Menu, and Kids Menu, ensuring there''s something delightful for every palate. Please note that prior reservation is essential for this exceptional dining experience, as walk-in guests cannot be accommodated.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734677659498_lepetitechef%2001.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734677753624_lepetitechef%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734677679287_LPC+02.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734677683797_LPC+03.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734677690914_LPC%2004.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734677691205_LPC%2005.png}', '2025-01-22 03:06:16.712168+00', '2025-01-22 03:06:16.712168+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('dee98b9fb28c47e782eb007bce5b9b0d', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Palm Court Bar & Lounge', 'Palm Court Bar & Lounge, a unique place in Darwin CBD.', NULL, 'The Palm Court Bar &amp; Lounge is a unique gathering place in Darwin CBD. By providing exemplary service, a stylish and premium selection of wine, champagne and cocktail and delightful bar snacks in a relaxed comfortable setting, the Palm Court Bar &amp; Lounge is the premier bar that ‘the locals’ go to in Darwin City.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678453549_pch%2001.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678470543_pch%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678483959_pch%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678659028_pch%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678671295_pch%2009.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678682138_pch%20011.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734678686394_pch%20010.jpg}', '2025-01-22 03:06:16.732169+00', '2025-01-22 03:06:16.732169+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('f7198f7dbc0c46d1b6f7611b2457c993', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'PepperBerry Restaurant', 'Dine at the award-winning restaurant, PepperBerry', NULL, 'For food enthusiasts looking for exceptional and sophisticated dining experiences, the award-winning restaurant, PepperBerry has a touch of class featuring modern Australian cuisine combined with bush spices where every ingredient has its place and purpose and is treated with the utmost care to highlight its purest flavours. Guests will be treated to the freshest, heartfelt flavoured cuisine that is exquisitely presented as a wholesome work of art because PepperBerry takes pride in its ingredients, flavours, presentation, and service.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679159777_pepperberry-04.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679165784_pepperberry-04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679177498_pepperberry-01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679178459_pepperberry-02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679182336_pepperberry-03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679193089_pepperberry-pork-belly.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679197178_pepperberry-scallops.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679201782_pepperberry-squid.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734679188776_pepperberry-chocolate-sin.jpg}', '2025-01-22 03:06:16.75326+00', '2025-01-22 03:06:16.75326+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_xw6yJcsgUphVBNZuMQPGYpx0', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Shuttle Bus', NULL, '{}', 'We offer convenient shuttle services to and from the airport, as well as popular local destinations. Schedules and pick-up points are designed to align with your itinerary, ensuring hassle-free transport throughout your stay.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', NULL, '{}', '2025-01-28 05:28:58.187+00', '2025-01-28 05:28:58.187+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('2cec0e5d14f94972ba3e862ffba2c222', 't', 'none', 'f', 'user_0000000000003_0000FREEUSER', '{}', 'Simply Foods', NULL, '{"phone": "(08) 8981 4765", "website": "https://simplyfoodsdarwin.weebly.com/"}', 'Welcome to Simplys. A fantastic spot for lunch right in the heart of Darwin! We have a wide range of foods; come and try our vegetarian salad range, our homemade wraps and sandwiches or our scrumptious veggie and vegan snacks and fresh juices and smoothies', NULL, '{"name": "Simply Foods", "type": "restaurant", "latitude": -12.4640127, "longitude": 130.8430015}', NULL, NULL, NULL, '2025-01-22 03:06:16.797249+00', '2025-01-22 03:06:16.797249+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('a0cfd620aa204daa892b1f13b9a71e87', 't', 'none', 'f', 'user_0000000000003_0000FREEUSER', '{}', 'Pokelicious', NULL, '{"phone": "0449 548 545", "website": "http://www.pokelicious.com.au/"}', 'Everything prepared with high quality, rich taste and made fresh on order. Healthy, delicious and made very special, to steal all your hearts. Our experienced staff ensure to give you the best and make your every order with us, the memorable moment. A simple poke bowl consists of a base, a topping, and a sauce. At Pokelicious, we begin with the simple poke bowl and expands it to a greater dimension. You make each selection: from tuna to chicken, atop a base of rice, fresh greens, or chips, in a housemade sauce – from a light citrus ponzu to a savory and spicy mayo.', NULL, '{"name": "Pokelicious", "type": "restaurant", "latitude": -12.46427017, "longitude": 130.8427238}', NULL, NULL, NULL, '2025-01-22 03:06:16.86813+00', '2025-01-22 03:06:16.86813+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_jlQ0vq5oRs6F5qaMkRinicId', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Swimming Pool', NULL, '{}', 'Take a refreshing dip in our swimming pool, available exclusively to hotel guests. Relax on poolside loungers or enjoy a leisurely swim in a serene and inviting setting.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmerSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375098423_Swimming_Pool_4.png}', '2025-01-24 00:52:49.737+00', '2025-01-24 00:52:49.737+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('9cee3b3181604b5e9ceba0c9fb875002', 't', 'none', 'f', 'user_0000000000003_0000FREEUSER', '{}', 'Four Birds Cafe', NULL, '{"email": "fourbirdscafe@gmail.com", "phone": "0451 821 807", "facebook": "https://www.facebook.com/fourbirdsdarwin"}', 'Open for breakfast, lunch and dinner. A little cafe at the Star VIllage Arcade. Grab a smoothie, poke bowl, all day breakfast a wrap or just a coffe.', NULL, '{"name": "Four Birds Cafe", "type": "restaurant", "latitude": -12.463936669273428, "longitude": 130.8431668}', NULL, NULL, NULL, '2025-01-22 03:06:16.846208+00', '2025-01-22 03:06:16.846208+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('819141b1346740e2b4a7875a66d1b758', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Pokelicious', 'Healthy happiness in a bowl. Poke bowls, smoothies & juices', NULL, '<p>Everything prepared with high quality, rich taste and made fresh on order. Healthy, delicious and made very special, to steal all your hearts. Our experienced staff ensure to give you the best and make your every order with us, the memorable moment.</p><p> </p><p>A simple poke bowl consists of a base, a topping, and a sauce. At Pokelicious, we begin with the simple poke bowl and expands it to a greater dimension. You make each selection: from tuna to chicken, atop a base of rice, fresh greens, or chips, in a house made sauce – from a light citrus ponzu to a savory and spicy mayo. </p><p><br /></p><p>No matter the combination created, each ingredient is highlighted and every bowl is balanced.</p>', NULL, '{"name": "Pokelicious", "type": "restaurant", "latitude": -12.4643185, "longitude": 130.8427168}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738689944_poke%2001.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738699786_poke%2001.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738716855_poke%2002.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738731818_poke+03.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738737872_poke+04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738740733_poke%2005.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738746155_poke%2007.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738748473_poke%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738753673_poke+06.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734738758476_poke%2009.png}', '2025-01-22 03:06:16.819138+00', '2025-02-10 04:19:43.568+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('b88d975d8f2a47d0a7a397eff98ae804', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Simply Foods', 'Vegan & Vegetarian salads, juices and snacks', NULL, 'Welcome to Simply Foods. A fantastic spot for lunch right in the heart of Darwin! We have a wide range of foods, come and try our vegetarian salad range, our homemade wraps and sandwiches or our scrumptious veggie and vegan snacks and fresh juices and smoothies', NULL, '{"name": "Simply Foods", "type": "restaurant", "latitude": -12.4640127, "longitude": 130.8430015}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734739944058_simply%2002.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734739956224_simply%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734739961603_simply+05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734739965992_simply%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734739970530_simply%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734739976002_simply%2009.jpg}', '2025-01-22 03:06:16.890137+00', '2025-01-22 03:06:16.890137+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('334eb999e3ec4189ab4034049ff0c3a0', 't', 'none', 'f', 'user_0000000000003_0000FREEUSER', '{}', 'Alfonsino’s', NULL, '{"email": "admin@alfonsinos.com", "phone": "08 89421586", "website": "http://www.alfonsinos.com/"}', 'Alfonsino’s is bringing a little piece of Italy to Darwin.Following a tradition from the 17th century, of the people of Napoli, our menu features authentic Italian cuisine prepared the traditional way. Using the finest quality ingredients, every component of the dish is made by hand and from scratch. Alfonsino’s is specialising in authentic wood fired pizza napoletana, hand made pasta, as well as traditional antipasti and desserts all whipped up in an easygoing location with an extensive patio.', NULL, '{"name": "Alfonsino’s", "type": "restaurant", "latitude": -12.46285239, "longitude": 130.839464}', NULL, NULL, NULL, '2025-01-22 03:06:16.98024+00', '2025-01-22 03:06:16.98024+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('a88f023cd7334b1aa170d1c6237af866', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'The Tap on Mitchell', 'Iconic Darwin pub, with all day food and drinks ', NULL, 'Located on Crocosaurus Cove off Mitchell St, Alfresco venue, All day dining including breakfast &amp; coffee, Cocktails, Live Music, Unique Outdoor Atmosphere - All Day Dining.<p>&nbsp;</p>The Tap is an iconic Darwin pub, with all day food covering breakfast, lunch and dinner, great bar, friendly staff and of course, its massive signature tree.<p>&nbsp;</p>The Tap has a variety of table and seating choices and the kitchen is consistent, so you know what you order is good and in traditional pub style, you order at bar and it’s brought to you. Grab a pub meal with vegetarian and gluten free dishes/options so there is something for everyone.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742052544_thetap.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742056413_thetap.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742085575_thetap%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742089978_thetap%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742095412_thetap%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742104951_thetap%2004.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742114222_thetap%2005.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734742114544_thetap%2007.jpg}', '2025-01-22 03:06:17.001242+00', '2025-01-22 03:06:17.001242+00');
