INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e58444393ce64b45b4ff0892cb119f03', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Alfonsino''s', 'Bringing a little piece of Italy to Darwin.', NULL, 'Alfonsino’s is bringing a little piece of Italy to Darwin.Following a tradition from the 17th century, of the people of Napoli, our menu features authentic Italian cuisine prepared the traditional way. Using the finest quality ingredients, every component of the dish is made by hand and from scratch. Alfonsino’s is specialising in authentic wood fired pizza napoletana, hand made pasta, as well as traditional antipasti and desserts all whipped up in an easygoing location with an extensive patio.', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740853517_cropped-Al-Fonsinos_Logo-web-3-8.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740869066_cropped-Al-Fonsinos_Logo-web-3-8.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740877205_alphonsos%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740887802_alphonsos%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740889508_alphonsos+05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740892083_alphonsos%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740893908_alphonsos%2009.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740899337_alphonsos%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740906265_alphonsos+07.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740915546_alphonsos%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740930443_alphonsos+04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734741075489_Alfonsino%27s%2001.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734740945605_alphonsos+010.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734741080230_Alfonsino%27s%2002%20.png}', '2025-01-22 03:06:17.043223+00', '2025-01-22 03:06:17.043223+00');
