INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('bf23cafb09734503bb48744519047556', 't', 'none', 'f', 'user_0000000000003_0000FREEUSER', '{}', 'Makan Stop', NULL, '{"email": "kopistopdarwin@gmail.com", "phone": "0437 315 804", "facebook": "https://www.facebook.com/makanstopdarwin", "instagram": "https://www.instagram.com/makanstopdarwin"}', 'Authentic Singaporean hawker delights.', NULL, '{"name": "Makan Stop", "type": "restaurant", "latitude": -12.46220437, "longitude": 130.8407376}', NULL, NULL, NULL, '2025-01-22 03:06:17.126219+00', '2025-01-22 03:06:17.126219+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('231042fe804f42fca5d01f282597b575', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Hanuman Restaurant', 'Asian flavours by Chef Jimmy Shu.', '{"phone": "(8) 89413500", "website": "http://www.hanuman.com.au/"}', '<p>Hanuman represents a lifelong commitment to creating exceptional Asian Cuisine by renowned chef Jimmy Shu. Beginning his journey in Colombo, Sri Lanka, and becoming one of Australia’s most respected experts in Asian flavours, Jimmy Shu has assembled teams of traditionally-trained chefs who combine their cooking secrets with his contemporary take on Asian Cuisine. Hanuman Darwin is the flagship of the Hanuman family, and has been a favourite with locals and visitors since 1992. The restaurant has both indoor and covered outdoor dining options to suit the tropical seasons.</p>', NULL, '{"name": "Hanuman Restaurant", "type": "restaurant", "latitude": -12.46033486, "longitude": 130.8368971}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733625317_hanuman%2003.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733629530_hanuman%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733634165_hanuman%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733638491_hanuman%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733644370_hanuman+05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733655774_hanuman+06.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733660301_Hanumans-11.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733665335_Hanumans-43.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733666192_hanuman%2007.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733673082_Hanumans-60.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734733674729_Hanumans-62.jpg}', '2025-01-22 03:06:17.064183+00', '2025-02-10 03:58:37.887+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('d56c0fca82954733b0594fbf60b6eb71', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Nirvana Restaurant Darwin', 'S.E. Asian fusion, cocktails & live music', '{"phone": "08 89812025", "website": "https://www.nirvanadarwin.com.au/", "facebook": "https://www.facebook.com/nirvanarestaurant"}', '<p>Welcome to Nirvana Restaurant, where we take you on a culinary journey to the exotic lands of Thailand and South East Asia. Since 1995, we have been serving up amazing Thai, Malay and Indian dishes to the locals of Darwin and our pre-cyclone Tracy building has been a part of Darwin''s restaurant history since the 1960s. Nirvana Restaurant is a multi-room venue that features a cocktail bar, intimate booths for couples, a private function room, and an al fresco deck area. if you''re feeling adventurous, our creative cocktails will help to tame the spice of our delicious cuisine. Speaking of taming the spice, our live music and whisky focused bar next door at Smoke &amp; Oak is sure to make your night a memorable one.</p>', NULL, '{"name": "Nirvana Restaurant Darwin", "type": "restaurant", "latitude": -12.456328, "longitude": 130.835423}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734476376_nirvana%2005.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734485459_nirvana%2005.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734494399_nirvana%2003.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734507519_nirvana%2002.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734504847_nirvana%2001.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734499715_nirvana%2008.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734513696_nirvana%2004.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734521695_nirvana+07.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734596816_nirvana%20020.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734734602346_nirvana%20021.jpg}', '2025-01-22 03:06:17.147243+00', '2025-02-10 03:59:36.28+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('aa7e1f685fc542d78affea4b34fd342c', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Crustaceans on the Wharf', 'Harbor front terrace for seafood & char-grilled steak', '{"phone": "08 89818658", "website": "http://www.crustaceans.net.au/"}', '<p>Relaxed restaurant with a sprawling harbor front terrace, for fish, oysters &amp; char-grilled steak. Vegetarian and Kids menu available Outdoor waterside dining. Opening hours vary depending on the season. Bookings recommended.</p>', NULL, '{"name": "Crustaceans on the Wharf", "type": "restaurant", "latitude": -12.4710193, "longitude": 130.8481399}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754581298_crustaceans%2002.JPG', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754566188_crustaceans-logo-small.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754573823_birthday.JPG,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754594090_seafood_platter_deluxe_for_two.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754578444_crustaceans%2001.JPG,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754586853_DSC_6655.JPG,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754590370_natural_wa_lobster.jpg}', '2025-01-22 03:06:17.288285+00', '2025-02-10 04:21:39.209+00');
