INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_0SBtg0WcTzGSMZUyFOrzLdC6', 'f', 'sidebar', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{content_1BhZypViukC7Ldu0Z7VdtWrE,content_quiKdw9VhKD8pJvvyRCmPQgl,content_c6BffAwOy4fmZhRTpjp2p8CS}', 'Getting to Captains Cove', 'The many ways to visit Paynesville', '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738207570089_captcove%20travel.jpg', '{""}', '2025-01-24 00:52:49.785+00', '2025-02-06 04:38:27.722+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_5uVskaLdqIvr2C3dm90TK5iQ', 'f', 'sidebar', 'f', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{content_EP6d4JzeNRmA4DvEBdD9CZmd,content_pZJc7Qr8A2pah717sLmKMQQM}', 'Amenities', NULL, '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCitySolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736818249234_health-club.jpg', '{""}', '2025-01-24 00:52:49.792+00', '2025-02-04 08:54:40.635+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_5hQwa7rxD9GYKkIDnMF7UQrT', 't', 'none', 'f', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Kids'' Safety', NULL, '{}', '<p>Like any beach, lake or waterway we need to watch our kids at all times around the water. Some apartments have lawn at the front where it is easier to keep an eye on the kids playing. Apartments 15, 16, 20, 21, 23, 24, 25, 26 have lawned areas at the side or front of the apartment.</p><p>There are stairs in the apartment. If you are concerned about little ones climbing, you can bring your own stair gate.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabySolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738642653487_capt%20cove%20front.png}', '2025-01-24 00:52:49.777+00', '2025-02-04 08:26:55.217+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_m9WIdQbMkrMw0nlGXCOgWjyH', 'f', 'sidebar', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{content_ZJ7LZtXzotRJPHaek1wJ4Ili,content_Oir06Pv6wz3XCqTWGyLPacHx,content_9oifqmNaMmRARpnXpO3b5Z4A,content_fdY1FMM9zvuQahHRLw67TNCA,content_6h35EQvYdMPEe1npa41cdLJQ,content_9zDvSr9SPuYaUr9RWt51zryt,content_mCZTxVryCvVLJ2lLcOl02sh0,content_87F1dBQ3fYhj6ZzIWdeNNzPW}', 'General Information', NULL, '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaElementor.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738210294588_Captains%20Cove%20Waterfront%2001%20.png', '{""}', '2025-01-24 00:52:49.795+00', '2025-02-06 04:40:22.887+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_quiKdw9VhKD8pJvvyRCmPQgl', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Public Transport VLine', 'Travel by train', '{}', '<p><strong>By train to Paynesville:</strong></p><p>Travellers can opt for public transportation, with VLine train services travelling several times per day from Melbourne to Bairnsdale.</p><p><br /></p><p>We are very fortunate that the Paynesville Bus service connects with the VLine train service and delivers our guests to Captains Cove; just ask the driver when you get on the bus!</p><p><br /></p><p>Similarly, you can call Paynesville Bus Services and ask them to collect you from Captains Cove when you depart.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaTrainSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738206736182_vline.jpg}', '2025-01-24 00:52:49.76+00', '2025-02-06 07:04:34.052+00');
