INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_8pFAuQYIxtv1PBK9mOObLrSj', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Check-in/Check-out', NULL, '{}', 'Our check-in process is quick and efficient, ensuring you settle into your room with ease. Check-out is equally seamless, with staff available to assist you at any time. Flexible options are available upon request.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCalendarCheck.svg', NULL, '{}', '2025-01-28 05:28:58.148+00', '2025-01-28 05:28:58.148+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_7QNXFd2P1sszwUwI2DdcL0B1', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Wi-Fi', NULL, '{}', 'Our hotel provides seamless Wi-Fi connectivity throughout the premises. Whether you are in your room, at the restaurant, or in the lobby, you can stay connected to what matters most. Enjoy fast and reliable internet for work, streaming, or browsing at your convenience.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaWifiSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736374246014_Wi-Fi_2.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736374251653_Wi-Fi_2.png}', '2025-01-28 05:28:58.152+00', '2025-01-28 05:28:58.152+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_7GO7dQSvYgqocOUtYveEwANt', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Swimming Pool', NULL, '{}', 'Take a refreshing dip in our swimming pool, available exclusively to hotel guests. Relax on poolside loungers or enjoy a leisurely swim in a serene and inviting setting.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmerSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375098423_Swimming_Pool_4.png}', '2025-01-28 05:28:58.155+00', '2025-01-28 05:28:58.155+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_wAOftPGSRAZLF4RscVfp8MIY', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Spa Services', NULL, '{}', 'Indulge in relaxation at our spa, offering a range of rejuvenating treatments, including massages, facials, and body therapies. Reservations are recommended for a truly personalized experience.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwatchbookSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736819494597_Massage_Grand_Velas_Riviera_Nayarit_Mexico-1024x682.jpg}', '2025-01-28 05:28:58.158+00', '2025-01-28 05:28:58.158+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_olzYxVJQQDKW0W38H7ErQQ7q', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Hotel Policies', NULL, '{}', 'Our policies are designed to ensure a pleasant stay for all guests. Please familiarize yourself with our guidelines on cancellations, pets, and smoking, which are crafted to maintain a safe and comfortable environment.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaFolderPlusSolid.svg', NULL, '{}', '2025-01-28 05:28:58.161+00', '2025-01-28 05:28:58.161+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_rBybI90oUgRhq0AhL4EDCCEC', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'About the Hotel', NULL, '{}', 'Welcome to our hotel! We are dedicated to providing a comfortable and memorable stay for all our guests. From luxurious accommodations to exceptional service, we strive to exceed your expectations at every turn.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaChartPieSolid.svg', NULL, '{""}', '2025-01-28 05:28:58.164+00', '2025-01-28 05:28:58.164+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_KYOc9aQDAFdkmnJXWOVgCE0O', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Address & Directions', NULL, '{}', 'Located conveniently in the heart of the city, our hotel is easily accessible by car, public transport, or shuttle services. Detailed directions are available on our website, or you can contact the front desk for personalized guidance.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCampgroundSolid.svg', NULL, '{}', '2025-01-28 05:28:58.171+00', '2025-01-28 05:28:58.171+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_kvOWIwCyrhvNNshq7XQHPpCH', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Welcome', NULL, '{}', 'Dear Guest,\n\nWe are delighted to have you with us at [Hotel Name]. Whether you''re here for business or leisure, our team is dedicated to making your stay both comfortable and memorable.\n\nThis Digital Compendium is designed to be your guide throughout your stay. Here, you''ll find all the essential information you need about our hotel, services, and facilities, as well as tips for exploring the local area.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/ThumbsUp.svg', NULL, '{}', '2025-01-28 05:28:58.174+00', '2025-01-28 05:28:58.174+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_UAsfqjxPNaFzERDORm27PTfo', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Parking Information', NULL, '{}', 'Ample parking is available for all guests, with options for valet or self-parking. Spaces are secure and easily accessible, providing peace of mind for those traveling by car.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, '{}', '2025-01-28 05:28:58.181+00', '2025-01-28 05:28:58.181+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_4xNY8NN5qK881AZy3Vc9ah3G', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Public Transport Options', NULL, '{}', 'Our location offers excellent access to public transportation, with nearby bus stops and train stations connecting you to major attractions and business centers. Speak to our concierge for route recommendations.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaShuttleVanSolid.svg', NULL, '{}', '2025-01-28 05:28:58.184+00', '2025-01-28 05:28:58.184+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_48UKLocXhfEE8s1hTIAp73Lu', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Restaurants', NULL, '{}', 'Delight in our on-site restaurants, where a variety of cuisines are prepared by world-class chefs. Whether you prefer a casual meal or a fine dining experience, our menus cater to all tastes and dietary preferences.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieBiteSolid.svg', NULL, '{}', '2025-01-28 05:28:58.19+00', '2025-01-28 05:28:58.19+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_G8Rt46ILG0zqaeaDESCVZuIX', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Room Service', NULL, '{}', 'Enjoy the convenience of room service, offering a wide selection of meals and beverages delivered directly to your door. Available 24/7, it''s perfect for a late-night snack or a relaxing breakfast in bed.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieSolid.svg', NULL, '{}', '2025-01-28 05:28:58.193+00', '2025-01-28 05:28:58.193+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_YoAmqjbhzDIjrfg0Z8rQNxRR', 't', 'none', 't', 'user_oLbrO2gXMELdBEg6ZTRKimSNM7K', '{}', 'Kids''Activities', NULL, '{}', 'Keep the little ones entertained with our selection of Kids'' activities, from supervised play areas to fun workshops. Our family-friendly environment ensures a memorable stay for guests of all ages.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabySolid.svg', NULL, '{}', '2025-01-28 05:28:58.195+00', '2025-01-28 05:28:58.195+00');
