INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_3LvbDCZFMl5OsHkXLIrLvjEu', 'f', 'sidebar', 't', 'user_0000000000003_0000FREEUSER', '{content_UFnXFIurtQNGxNKpgGrprhrO,content_OLxFtUpr3Taagl8O960z62Fy}', 'Dining', NULL, '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736374994622_Dining_4.png', '{""}', '2025-02-10 05:57:37.85+00', '2025-02-10 05:57:37.85+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_abb32b84072d44f186411ee3', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'O Le Pupu Pu’e National Park Coastal Walk', NULL, '{}', '<p>Duration: 1-Hour Return Difficulty: Easy Trade Samoa’s renowned beaches for the striking coastal cliffs of Upolu on the Coastal Walk. Located within the O Le Pupu-Pu‘e National Park, this four-hour return trail meanders through lush pandanus forest before revealing dramatic lava cliffs. Along the way, you’ll encounter crashing waves, seabirds dotting the horizon, and several natural sea arches that add to the scenery’s allure. Closed-toe shoes are recommended for safety, though the mostly flat trail is accessible to walkers of varying fitness levels. While it’s easy to navigate the path independently, guided tours with Samoan Island Adventures or Manoa Tours offer deeper insights into the area’s natural beauty and cultural significance.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229049232_376431-infinity-pool-and-coastal-clips-at-samoana-beach-bungalows-web-1280px.jpg', NULL, '2025-02-10 05:50:10.086392+00', '2025-02-10 23:10:50.851+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_hZJpz9B0XGbR0O3hwshnL9Y0', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Wi-Fi', NULL, '{}', '<p>Our hotel provides seamless high speed internet connectivity throughout the premises. You can stay connected to what matters most. </p><p><br /></p><p>Enjoy fast and reliable internet for work, streaming, or browsing at your convenience.</p><p><br /></p><p>All rooms offer smart TVs. Streaming apps like Netflix, Stan, Disney and Kayo are accessible. </p><p><br /></p><p>Please note you will need to use your own account so don’t forget your login details.</p><p><br /></p><p><strong>Please remember to logout of your services when you depart.</strong></p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaWifiSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738201771446_captcove%20019.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738201818371_captcove%20019.png}', '2025-01-24 00:52:49.734+00', '2025-02-06 07:02:27.524+00');
