INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_OAfJ54pOvLDSry7vJHwiwW0o', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Welcome', NULL, '{}', 'Dear Guest,\n\nWe are delighted to have you with us at [Hotel Name]. Whether you''re here for business or leisure, our team is dedicated to making your stay both comfortable and memorable.\n\nThis Digital Compendium is designed to be your guide throughout your stay. Here, you''ll find all the essential information you need about our hotel, services, and facilities, as well as tips for exploring the local area.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/ThumbsUp.svg', NULL, '{}', '2025-02-11 03:27:22.109+00', '2025-02-11 03:27:22.109+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_gOQ5swCXbDCIjbPoZLLF9jNX', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Parking Information', NULL, '{}', 'Ample parking is available for all guests, with options for valet or self-parking. Spaces are secure and easily accessible, providing peace of mind for those traveling by car.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, '{}', '2025-02-11 03:27:22.112+00', '2025-02-11 03:27:22.112+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ICaOW66yzMZIYfN5mZjcex5F', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Public Transport Options', NULL, '{}', 'Our location offers excellent access to public transportation, with nearby bus stops and train stations connecting you to major attractions and business centers. Speak to our concierge for route recommendations.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaShuttleVanSolid.svg', NULL, '{}', '2025-02-11 03:27:22.114+00', '2025-02-11 03:27:22.114+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_q00csaATkG8XmdnKa0YVzgZb', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Shuttle Bus', NULL, '{}', 'We offer convenient shuttle services to and from the airport, as well as popular local destinations. Schedules and pick-up points are designed to align with your itinerary, ensuring hassle-free transport throughout your stay.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', NULL, '{}', '2025-02-11 03:27:22.117+00', '2025-02-11 03:27:22.117+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_8pYMxGWJSuvVLbEIJLMUW5HI', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Restaurants', NULL, '{}', 'Delight in our on-site restaurants, where a variety of cuisines are prepared by world-class chefs. Whether you prefer a casual meal or a fine dining experience, our menus cater to all tastes and dietary preferences.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieBiteSolid.svg', NULL, '{}', '2025-02-11 03:27:22.12+00', '2025-02-11 03:27:22.12+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_DejkTZqg6966NiwHQwu3E5YU', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Room Service', NULL, '{}', 'Enjoy the convenience of room service, offering a wide selection of meals and beverages delivered directly to your door. Available 24/7, it''s perfect for a late-night snack or a relaxing breakfast in bed.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieSolid.svg', NULL, '{}', '2025-02-11 03:27:22.123+00', '2025-02-11 03:27:22.123+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_sUj4uxDMZeQILuRpFON6tpgk', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Kids''Activities', NULL, '{}', 'Keep the little ones entertained with our selection of Kids'' activities, from supervised play areas to fun workshops. Our family-friendly environment ensures a memorable stay for guests of all ages.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabySolid.svg', NULL, '{}', '2025-02-11 03:27:22.126+00', '2025-02-11 03:27:22.126+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ZJ7LZtXzotRJPHaek1wJ4Ili', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'About Us', 'Captains Cove holds a special place in the hearts of many.\n', '{}', '<p>Welcome to Captains Cove Waterfront Apartments, where hospitality meets a legacy of 15 years of excellence. Over the years, we’ve witnessed countless memorable moments, from children growing up to the arrival of grandchildren, and the celebration of marriages.</p><p><br /></p><p>Captains Cove holds a special place in the hearts of many. It’s not just a place to stay; it’s a sanctuary where cherished memories are created and cherished.</p><p><br /></p><p>Dedicated to Service. Where Memories Are Made and Treasured.</p><p><br /></p><p>Our dedicated team shares a profound sense of pride in what we do. We strive for continual improvement to ensure that our accommodations remain fresh, comfortable, and contemporary.</p><p><br /></p><p>When you book with Captains Cove Waterfront Apartments you can rest assured you will be looked after.</p><p><br /></p><p>We offer our guests contactless check-in, which means you can check in anytime.</p><p><br /></p><p>We like to offer our guests an early check in where possible, which is why we SMS your apartment access code as soon as your apartment is ready for you.</p><p><br /></p><p><strong>Our Reception is open 7 days a week, and while it is not always attended, we are always available by phone or at our sister property, Mariners Cove Resort.</strong></p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaInfoSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738198700704_captCove%20017.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738205597869_captCove%20017.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738205609721_captCove%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738819260252_Tamara-Cook-manager-of-Captains-Cove.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738205629886_captCove%20014.png}', '2025-01-24 00:52:49.747+00', '2025-02-06 07:11:40.579+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_cd9c4778626b42e8b07b4275', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Ma Tree Walk Duration', NULL, '{}', '<p>Ma Tree Walk Duration: 15 Minutes One Way Difficulty: Easy Named by the paramount chief of A‘opo (a village on Savai‘i), the Ma Tree derives its name, meaning “shame,” possibly due to its distinctive features compared to other rainforest species. These include its unique silver-brown patches under the leaves and its tendency to grow in solitary patches. Most striking, however, are the giant buttress roots spreading meters around its base. This family-friendly walk is a short 780-metre (853-yard) stroll from the well-maintained car park and information boards in O Le Pupu-Pu‘e National Park, making it an accessible and enriching nature experience for visitors of all ages</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229342565_376540-canopy-walk-falealupo-16-web-1280px.jpg', NULL, '2025-02-10 05:50:10.235342+00', '2025-02-10 23:15:44.669+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ce34ad96838041ab8b2fab97', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Togitogiga Waterfall', NULL, '{}', '<p>Togitogiga Waterfall via Ma Tree Duration: 45 Minutes One Way Difficulty: Moderate. There are two ways to reach Togitogiga Waterfall: the easy route, by parking at the O Le Pupu Pu’e National Park Visitor Centre, or the longer, more adventurous path. After completing the Ma Tree Walk (see above), head east along a rough 1.35km (0.8 mi) trail through the rainforest to the Visitor Centre. This trail is less maintained than the Ma Tree Walk, so it’s best suited for fit walkers who can pay close attention to the path. From the Visitor Centre, it’s just a 5-minute walk to Togitogiga Waterfall, a refreshing spot for a swim. Keep in mind, however, that the waterfall may be dry during the dry season. Afterward, you can either retrace your steps or loop back via the main road.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229403560_376277-togitogiga-waterfall-in-forest-in-samoa-web-1280px.jpg', NULL, '2025-02-10 05:50:10.309329+00', '2025-02-10 23:16:45.876+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_702aa6d23be84c4f81d1651d', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Robert Louis Stevenson Tomb Trail', NULL, '{}', '<p>Robert Louis Stevenson Tomb Trail on Mt Vaea Duration: 30-45 Minutes or 50-60 Minutes One Way Difficulty: Challenging. Accessible via the Vailima Botanical Garden or the nearby Robert Louis Stevenson Museum, the Robert Louis Stevenson Tomb Trail takes you to the resting place of the famous Scottish author on Mt Vaea. Along the way, you’ll pass through enchanting rainforest and enjoy breathtaking views of Apia. There are two routes to the summit: a 30-minute, steeper, and rougher trail, or a 50- minute, more gradual path that zigzags its way to the top and passes a magnificent banyan tree. Either route, good walking shoes are recommended for a comfortable and enjoyable hike.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229833293_376196-robert-louis-stevenson-museum-web-1280px.jpg', NULL, '2025-02-10 05:50:10.528244+00', '2025-02-10 23:23:54.764+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_794f61a90e194aea8690d7ff', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Mt Matavanu Duration', NULL, '{}', '<p>Mt Matavanu Duration: 2-3 Hours Return Difficulty: Moderate. For those seeking a less strenuous volcanic climb on Savai’i, try Mt Matavanu. Located on the island’s north coast, this volcano was responsible for the 1905–1911 eruptions that sent lava flowing 13km (8 mi) along the coast. To explore Mt Matavanu, you can either join a guided hike from the village of Safotu or pay an entry fee and follow the marked trail on your own. The 4WD track to the summit takes about 20-25 minutes by car or 2-3 hours on foot, offering chances to spot flying foxes and enjoy spectacular views of Savai’i’s western villages along the way.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229511239_374336-view-across-bay-2-web-1280px.jpg', NULL, '2025-02-10 05:50:10.383466+00', '2025-02-10 23:18:32.782+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_PstBraXsFQoXHSp7vNrQH7QL', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Fitness Center', NULL, '{}', 'Maintain your workout routine at our fully equipped fitness center, featuring modern machines and free weights. Open daily, the facility is designed for your convenience and comfort.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaRunningSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375130362_Fitness_Center_2.png}', '2025-02-11 03:27:22.129+00', '2025-02-11 03:27:22.129+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_CZTuLtxuTRt8uz5fsfVIPzd4', 'f', 'sidebar', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{content_q00csaATkG8XmdnKa0YVzgZb,content_gOQ5swCXbDCIjbPoZLLF9jNX,content_ICaOW66yzMZIYfN5mZjcex5F}', 'Transportation', NULL, '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736818194015_03_limousine_transfer.jpg', '{""}', '2025-02-11 03:27:22.135+00', '2025-02-11 03:27:22.135+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_1BhZypViukC7Ldu0Z7VdtWrE', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'By Car or By Boat', 'Travelling Outside the Box\n', '{}', '<p>Paynesville has the seaside village charm because we are off the beaten track (well, if you call the Princes Hwy the ‘beaten track’!). </p><p><br /></p><p>From Bairnsdale, East Gippsland’s major town, you will drive 20 minutes along the Mitchell River before you arrive at Paynesville, which is nestled along the scenic Gippsland Lakes.</p><p><br /></p><p><strong>By Car to Paynesville:</strong></p><p>Melbourne CBD: 294km (3.5 hrs)</p><p>Canberra: 466km (5 hrs)Sydney: 747 km (8 hrs)</p><p><br /></p><p>The<strong> </strong>Sydney to Melbourne coastal touring route takes you through laid-back seaside towns, National Parks teeming with wildlife, sandy beaches and fresh seafood. We highly recommend this trip at least once!</p><p><br /></p><p><strong>By boat to Paynesville:</strong></p><p>For those seeking a more leisurely journey, traveling to Paynesville by boat is an enchanting option. The town boasts a marina and ample mooring facilities, making it accessible by private boat or hired vessel. </p><p><br /></p><p>Cruising across the tranquil waters of the Gippsland Lakes provides a unique perspective of the region’s breathtaking landscapes, with opportunities to spot native wildlife and enjoy waterfront dining experiences upon arrival in Paynesville.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', '', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738206404598_captcove%20travel.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738206268591_captCove%20014.png}', '2025-01-24 00:52:49.764+00', '2025-02-06 07:03:48.037+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_6h35EQvYdMPEe1npa41cdLJQ', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Resort House Rules', 'Our policies are designed to ensure a pleasant stay.', '{}', '<p><strong>Please familiarize yourself with our house rules.</strong></p><p><br /></p><p><strong>Smoking:</strong> For the comfort of all guests, all smoking is to be done on the lower outside balcony. Smoking is prohibited inside the apartment. While you are able to smoke on the deck of your apartment, we do ask that you are mindful of your neighbors. Guests who have smoked inside their apartment will be charged a fine.</p><p><br /></p><p><strong>Pets:</strong> Pets are prohibited in all units with the exception of assistance dogs. If you are bringing an assistance dog, please advise Guest Services prior to your arrival.</p><p><br /></p><p><strong>Noise:</strong> Captains Cove is located in a peaceful location. As a courtesy to other guests please ensure that noise levels are kept to a minimum and that you respect our strict ‘no noise’ policy from 10pm.</p><p><br /></p><p><strong>Guests: </strong>Guests<strong> </strong>and invitees of the guests are expected to behave in a manner conducive to the safety, comfort and convenience of other guests within the property.</p><p><br /></p><p>A breach of the House Rules may result in the summary eviction of the offender at the discretion of the Manager.</p><p><br /></p><p><strong>A breach of House Rules includes:</strong></p><p>•\tNoisy, offensive and/or unruly behavior. There is a no noise policy from 10pm every night.</p><p>•\tDamage to or destruction of property</p><p>•\tImproper or unseemly conduct</p><p>• Any act or omission which, in the opinion of the Manager adversely affects or brings discredit upon Captains Cove, the Manager, owner or the guests</p><p><br /></p><p>Reception is available 7 days a week to address any concerns or questions during your stay. If our Reception is closed, you can visit our sister property, Mariners Cove, where the Reception is open 7 days a week and offers extensive travel information.</p><p><br /></p><p><strong>You can reach us 24/7 at 03 5156 7223. </strong></p><p>For after-hours assistance, we have on-site managers available to help.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaClipboardCheckSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738203628907_captCove%20015.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738203615989_captCove%20014.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738203639499_captCove%2008.jpg}', '2025-01-24 00:52:49.744+00', '2025-02-06 07:27:54.42+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_c20355c29cae4822b3ed5590', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Manono Island Walk Duration', NULL, '{}', '<p>Manono Island Walk Duration: 1h30mins Loop Difficulty: Challenging (+ 1h30mins Return to Mt Tulimanuiva) A 15-hour return walk to Mt Tulimanuiva offers a unique way to explore Manono Island, which is just a 20-minute boat ride from Upolu’s west coast. With no cars on the island, the walking trail is the perfect way to navigate between the villages and experience the island’s charm. While the main trail takes around 1.5 hours, be sure to allow extra time to chat with the friendly locals, visit the Grave of 99 Stones, swim at Apai Beach, and take a detour up Mt Tulimanuiva. The climb to the summit, where an ancient star mound awaits, adds an additional 1.5 to 2 hours to your journey.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230120902_376563-ferry-10-web-1280px.jpg', NULL, '2025-02-10 05:50:10.679409+00', '2025-02-10 23:28:42.546+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_e52b146009864ff4a47a7b70', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Vaisala Bay Loop Walk Duration', NULL, '{}', '<p>Vaisala Bay Loop Walk Duration: 20 Minutes Loop Difficulty: Moderate. The Vaisala Bay Loop Walk on Savai’i offers a peaceful and easy stroll along a concrete walkway, winding through the clifftop and coastal forest. Starting and ending at the Vaisala Hotel, the hotel maintains the trail and offers the option to enjoy a meal at their restaurant once you’ve worked up an appetite. If you’re only interested in the walk, be sure to check at reception for any applicable entry fee.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230346776_374378-looking-at-bins-of-koko-beans-1-web-1280px.jpg', NULL, '2025-02-10 05:50:10.904234+00', '2025-02-10 23:32:29.031+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_pZJc7Qr8A2pah717sLmKMQQM', 't', 'none', 'f', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Extra ', '', '{}', '', NULL, '{}', NULL, NULL, NULL, '2025-02-03 01:03:24.785+00', '2025-02-04 10:15:14.2+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_AFG3S8J9HyyYePMkYiZ7dl3x', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Apartments', ' Welcome to Captains Cove Waterfront Apartments.', '{}', '<p>Our absolute waterfront apartments offer a special retreat, thoughtfully and stylishly designed across 15 townhouses. On the ground floor, you’ll find living, kitchen, and deck areas overlooking the water, while upstairs, the master bedroom boasts a king bed, private balcony with stunning water views.</p><p>Immerse yourself in the beauty of East Gippsland from your home-away-from home at Captains Cove.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwatchbookSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738640596928_CaptCoveapt.jpg}', '2025-01-24 00:52:49.741+00', '2025-02-04 03:43:26.596+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_Cz7k5XOdSuy4Y6cls1l7xbGr', 'f', 'overlay', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'abc', '', '{}', NULL, NULL, NULL, NULL, NULL, NULL, '2025-02-04 03:45:07.224+00', '2025-02-04 03:45:07.224+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_9oifqmNaMmRARpnXpO3b5Z4A', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Check-in/Check-out', NULL, '{}', '<p>Our check-in process is quick and efficient, ensuring you settle into your room with ease. </p><p><br /></p><p>Check-out is equally seamless, with staff available to assist you at any time. Flexible options are available upon request.</p><p><br /></p><p>Our Reception operates 7 days per week from our Mariners Cove office located at 2 Victoria Street, Paynesville - Opposite the ferry on the Esplanade.</p><p><br /></p><p>Our check in process is contactless and you will receive an SMS on the day of arrival when your apartment is ready for check in. You will also receive a code that unlocks the key box located at the door of your apartment.</p><p><br /></p><p>While we are not always at our Captains Cove Reception, we are always available by phone (03 5156 7223)</p><p><br /></p><p>Contactless check in means that you can check in at any time of the day or night.</p><p><br /></p><p><strong>Check-In:</strong> From 2:00PM<strong> </strong></p><p><strong>Check-Out</strong>: By 10:00AM</p><p><br /></p><p>If you require an early check-in or late check-out, please contact Guest Services to discuss.</p><p><br /></p><p><strong>Key Return: </strong>Please return your key by 10am to Reception or the key return box to the right of Reception.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Trolley.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738659900692_captCove%2013.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738210691510_captCove%2013.jpg}', '2025-01-24 00:52:49.73+00', '2025-02-06 07:14:13.183+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_45bee0e52c3541838aa46247', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'LOCAL MARKETS', NULL, '{}', '<p>Fugalei Fresh Produce Market (Maketi Fou) Open daily and offering a diverse range of fantastic regional produce. Make sure you try a cool refreshing Niu (coconut milk). Located on Fugalei Street, it’s recommended to visit the market during daylight hours.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230405101_375365-talking-to-local-at-market-3-web-1280px.jpg', NULL, '2025-02-10 05:50:10.977361+00', '2025-02-10 23:33:26.971+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ec660821a65243f19f50c27d', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Savalalo Flea Market', NULL, '{}', '<p>Open Monday to Saturday, the flea market is a great place to buy a souvenir to bring back home with you. The intricately made handicrafts found here are colourful and reflective of the Samoan culture with its unique emblems. The market is located at Savalalo.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230487476_374845-woman-at-market-stall-2-web-1280px.jpg', NULL, '2025-02-10 05:50:11.050489+00', '2025-02-10 23:34:49.548+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ed84fa1f730c4f5492144205', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Salelologa Market', NULL, '{}', '<p>Salelologa Market Located by The Wharf in Salelologa, Savai’i, this market sells a range of local produce and traditional souvenirs at cheaper prices than you’ll find on Upolu Find the perfect keepsake to commemorate your time in Samoa. The market is open Monday to Saturday from 7am.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230597206_374461-couple-try-traditional-cuisine-2-web-1280px.jpg', NULL, '2025-02-10 05:50:11.193354+00', '2025-02-10 23:36:41.329+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ca9e4c1c90d847c6a7f6a8bf', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'A SAMOAN WEDDING', NULL, '{}', '<p>Samoa has become a world renowned wedding destination and it’s no surprise with its picture perfect location. Getting married in Samoa is easy and hassle free and couples can tie the knot surrounded by a romantic tropical paradise and stunning azure blue waters. According to Fa’a Samoa (the Samoan way) marriage is a beautiful and sacred union to be respected and honoured. Traditionally, Samoan weddings are a grand celebration where the bride wears a Pale (head-dress) and the groom wears an Ula (floral necklace). Whether you choose a large or small ceremony, in a church or on a beach, at sunrise or sunset, Samoa has a range of stunning ceremony locations and reception options to make your special day a memorable event. There are many suitable resorts offering the convenience of wedding and honeymoon packages. To marry in Samoa, couples are required to fill out an application for a marriage license at least 10 days prior (but no more than 3 months in advance) to your wedding day. You will also need to be in Samoa a few days prior to your wedding.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230794352_376833-cultural-village-7-web-1280px.jpg', NULL, '2025-02-10 05:50:11.346421+00', '2025-02-10 23:39:56.345+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_786ebb23995240119e2b8453', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'FIAFIA NIGHTS', NULL, '{}', '<p>Many restaurants and hotels have Fiafia nights, showcasing Samoan dance performances and songs along with delicious food.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230905182_376137-traditional-fiafia-cultural-dance-show-web-1280px.jpg', NULL, '2025-02-10 05:50:11.418345+00', '2025-02-10 23:41:47.292+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_yjdXuU3LLhsr59TJgg8uP54t', 'f', 'sidebar', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{content_8pYMxGWJSuvVLbEIJLMUW5HI,content_DejkTZqg6966NiwHQwu3E5YU}', 'Dining', NULL, '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736374994622_Dining_4.png', '{""}', '2025-02-11 03:27:22.139+00', '2025-02-11 03:27:22.139+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_dm24ZmTeMGyk3bPaCyBqw6kx', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Dining In', NULL, '{}', '<p>Experience the epitome of relaxation and tranquillity at Captains Cove Waterfront Apartments. Our thoughtfully designed accommodations boast stunning water views, inviting you to immerse yourself in the natural beauty of East Gippsland.</p><p><br /></p><p>Our waterfront apartments epitomize comfort and style. Featuring fully appointed kitchens, private balconies and your own BBQ.</p><p><br /></p><p><strong>At Captains Cove, we prioritise two things:</strong> your comfort and environmental sustainability. Our commitment to quality is backed by our accreditation as a Victorian Tourism industry Council (VTIC) star-rated and sustainable tourism business (view certificate).</p><p><br /></p><p>Our guests deserve the best, and we strive to deliver it in a sustainable way. Each room provides access to One Fairtrade tea, coffee, and hot chocolate, ensuring high-quality products while supporting fair compensation for farmers.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738642052278_captCove%20012a.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738819488772_captCove%20dine%20in%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738819521420_dining%20in.jpg}', '2025-01-24 00:52:49.769+00', '2025-02-06 07:07:06.034+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_iPXHkDcw9pzPTf8b6C1twyzu', 'f', 'overlay', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Swimming Pool', '', '{}', NULL, NULL, NULL, NULL, NULL, NULL, '2025-02-04 08:25:00.599+00', '2025-02-04 08:25:00.599+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_kWLztTZOJCJyqANlQHT2Uc2t', 'f', 'overlay', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Kids Safety', '', '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabyCarriageSolid.svg', NULL, NULL, '2025-02-04 08:25:46.23+00', '2025-02-04 08:25:46.23+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_3c1cbbc4049a434aac239bdc', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'SAMOAN UMU', NULL, '{}', '<p>Across the Pacific, Polynesians and Melanesians have a connection with cooking food on or around hot rocks, in the ground or under leaves. They all have variation and each place has its own distinct flavour when the cooking is done. Umu is the Samoan style and is done on hot rocks. The rocks are placed on the ground and confined with some pieces of wood, then timber is placed on the rocks and set alight (“fiafia”). The fire burns for some time and the rocks become hot and traditional foods such as taro, breadfruit, taamu and luau (the leaves of the taro) are sliced and placed onto the umu, then covered to maintain heat and cook the food. Umu can be experienced at a large number of the venues in Samoa, in particular Savai’i is extremely proud of its association with this type of cooking</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230960925_375133-umu-food-ready-to-serve-1-web-1280px.jpg', NULL, '2025-02-10 05:50:11.494409+00', '2025-02-10 23:42:42.743+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ViIu543pVMYOYkUQghovNXCr', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Swimming Pool', '', '{}', '<p>Take a refreshing dip in our swimming pool, available exclusively to hotel guests. Relax on poolside loungers or enjoy a leisurely swim in a serene and inviting setting.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmingPoolSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738657663985_captCove%2021.png}', '2025-02-04 08:27:51.671+00', '2025-02-04 08:28:09.203+00');
