INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_qDdI2h59Eyyue2bXz0NrdvXT', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'swim', '', '{}', '', NULL, '{}', NULL, NULL, NULL, '2025-02-04 08:34:15.233+00', '2025-02-04 08:34:15.233+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_kGlN1TX0h1ObDUB3CGCKPL4s', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Dining Out', NULL, '{}', '<p><strong>Restaurants &amp; Cafés</strong></p><p>East Gippsland is renowned for its exceptional local food and drink, featuring fresh seafood, delicious meats, artisanal cheeses, and fine wines. With a range of charming restaurants and cafes, you’re sure to find something to satisfy your cravings. Here are some of our top picks:</p><p><br /></p><p><strong>Sardine Restaurant &amp; Cantina</strong></p><p>Paynesville’s Chef’s hatted restaurant offers a gourmet dining experience with a focus on local seafood and seasonal produce.</p><p><br /></p><p><strong>Lindenow Long Paddock</strong></p><p>A 25-minute drive from Paynesville, this destination is well worth the trip for its innovative menu and welcoming atmosphere.</p><p><br /></p><p><strong>Northern Ground Deli &amp; Wine Bar</strong></p><p>Located in Bairnsdale, this deli and wine bar serves up a delightful selection of local cheeses, meats, and wines.</p><p><br /></p><p><strong>Soda Fish Restaurant</strong></p><p>Situated in Lakes Entrance, this restaurant is known for its fresh seafood dishes and stunning waterfront views.</p><p><br /></p><p><strong>Pier 70 Bar &amp; Restaurant</strong></p><p>Enjoy delicious food and a laid-back vibe at this popular Paynesville eatery.</p><p><br /></p><p><strong>East Handy Store</strong></p><p>This Bairnsdale gem offers a range of homemade treats and local produce.</p><p>Wineries &amp; Breweries</p><p><br /></p><p><strong>Lightfoot &amp; Sons Winery &amp; Cellar Door</strong></p><p>Visit this award-winning winery to sample their exquisite selection of wines, paired with panoramic vineyard views.</p><p><br /></p><p><strong>Nicholson River Winery &amp; Cellar Door</strong></p><p>Discover handcrafted wines and friendly service at this charming winery.</p><p><br /></p><p><strong>Nicholson General Store</strong></p><p>Famous for their homemade pies, this store is a must-visit for food lovers.</p><p><br /></p><p><strong>Bruthen Bullant Brewery</strong></p><p>Enjoy craft beers and hearty meals at this popular Bruthen brewery.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738641757891_A-stunning-meal-at-Sardine-Eatery-1024x683.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738819637559_Sardine_2019-22.jpg}', '2025-01-24 00:52:49.774+00', '2025-02-06 07:07:48.652+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_mCZTxVryCvVLJ2lLcOl02sh0', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Kids Safety', '', '{}', '<p>Like any beach, lake or waterway we need to watch our kids at all times around the water. Some apartments have lawn at the front where it is easier to keep an eye on the kids playing. </p><p><br /></p><p>Apartments 15, 16, 20, 21, 23, 24, 25, 26 have lawned areas at the side or front of the apartment.</p><p><br /></p><p>There are stairs in the apartments so if you are concerned about little ones climbing, you can bring your own stair gate.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabySolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738657599430_capt%20cove%20front.png}', '2025-02-04 08:26:10.026+00', '2025-02-06 07:29:44.899+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_c6BffAwOy4fmZhRTpjp2p8CS', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Parking Information', 'Private Jetty and Parking Spots', '{}', '<p><strong>Car, trailer &amp; boat parking is free.</strong></p><p>Each apartment has it''s own covered carport located at the rear of the apartment.</p><p><br /></p><p>Boat trailer parking is available opposite apartments 24-26.</p><p>Guests are welcome to use the hose to wash down your boat.</p><p><br /></p><p>Additional cars can be parked adjacent to the pool or on the lawn area opposite Apartments 24-26.</p><p><br /></p><p>Each exclusive apartment has its own private jetty in Gippslands'' most protected waterfront, mooring for holiday and boating enthusiasts.</p><p><br /></p><p><strong>Electric Car Charger:</strong> A charger is located in the Raymond Street carpark, just 20m from the Resort.</p><p><br /></p><p>There is an outside power point on the BBQ so cars can be charged from the apartment. You will need to bring your own 15 meter power chord.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816521837_capt%20cove%20parking.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738207393424_captcove%20jetty.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738207296755_Accessible-Apartment-Exterior-View.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738815644300_captcovesign02.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738207099586_captCove%2026.png}', '2025-01-24 00:52:49.757+00', '2025-02-06 07:05:39.843+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_BIBRvkaldKchHPTBMbHooECd', 'f', 'overlay', 'f', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'sub category 1', '', '{}', NULL, NULL, NULL, NULL, NULL, NULL, '2025-02-06 02:40:20.731+00', '2025-02-06 02:40:36.624+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_EP6d4JzeNRmA4DvEBdD9CZmd', 't', 'none', 'f', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Apartment Amenities', NULL, '{}', '<p><strong>Apartment Amenities</strong></p><p>Master king bedroom on the second storey, offering a TV and private balcony with canal views</p><p>Second bedroom on the second storey, offering queen or twin beds (configuration options upon request)</p><p>Third bedroom on the ground floor, offering queen or twin beds</p><p>Fully self-contained kitchen (dishwasher, full oven, microwave, One Fairtrade tea, coffee and hot chocolate, and Nespresso coffee machine)</p><p>Dining and lounge area with 55in smart TV</p><p>Bathroom on ground floor and second storey, with quality Biology amenities</p><p>Laundry with washing machine, dryer, clothes rack and ironing facilities</p><p>Outdoor area with deck, BBQ, outdoor setting and jetty</p><p>High speed internet</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmingPoolSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375130362_Fitness_Center_2.png}', '2025-01-24 00:52:49.782+00', '2025-02-04 10:21:53.846+00');
