INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ASKWc1HKtN9g6obhrUNwW11S', 'f', 'overlay', 'f', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'sub category 2', '', '{}', NULL, NULL, NULL, NULL, NULL, NULL, '2025-02-06 02:40:27.256+00', '2025-02-06 02:40:37.775+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e768c6f3be4243d89df96c551a9bdb44', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Makan Stop', 'Authentic Singaporean & Malaysian hawker delights.', NULL, '<p>Authentic Singaporean hawker delights. Voted Top 10 in the Darwin International Laksa Festival. Kopi Stop Laksa - voted 2023 People’s Choice Laksa! Makan Stop Penang Laksa is a daily affair serving up 7days a week from as early as 7am because who doesn’t love a laksa for breakfast? Our laksa paste and laksa sambal are both completely house made from our secret recipe. Available at both Kopi Stop &amp; Makan Stop. Come try Authentic Singaporean and Malaysian hawker delights.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731100730_makan%2003.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731107533_makan%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731118220_makan%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731129315_makan%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731202478_makan%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731867935_makan%2005.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731871587_makan%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731877672_makan%2007.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734731914756_makan%2008.jpg}', '2025-01-22 03:06:17.16823+00', '2025-02-10 03:58:19.79+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_aM929hakySkGfJ75WsGHEgbk', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Spa Services', NULL, '{}', 'Indulge in relaxation at our spa, offering a range of rejuvenating treatments, including massages, facials, and body therapies. Reservations are recommended for a truly personalized experience.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwatchbookSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736819494597_Massage_Grand_Velas_Riviera_Nayarit_Mexico-1024x682.jpg}', '2025-02-10 05:57:37.808+00', '2025-02-10 05:57:37.808+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_Kq2did9e3LU6XdvDnfGDK38Z', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Hotel Policies', NULL, '{}', 'Our policies are designed to ensure a pleasant stay for all guests. Please familiarize yourself with our guidelines on cancellations, pets, and smoking, which are crafted to maintain a safe and comfortable environment.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaFolderPlusSolid.svg', NULL, '{}', '2025-02-10 05:57:37.812+00', '2025-02-10 05:57:37.812+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_Q3QpBHQG8yOl3q10NKdvOp4K', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'About the Hotel', NULL, '{}', 'Welcome to our hotel! We are dedicated to providing a comfortable and memorable stay for all our guests. From luxurious accommodations to exceptional service, we strive to exceed your expectations at every turn.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaChartPieSolid.svg', NULL, '{""}', '2025-02-10 05:57:37.815+00', '2025-02-10 05:57:37.815+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_se9SAWEAdPLcjuR1pzzIhVSE', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Address & Directions', NULL, '{}', 'Located conveniently in the heart of the city, our hotel is easily accessible by car, public transport, or shuttle services. Detailed directions are available on our website, or you can contact the front desk for personalized guidance.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCampgroundSolid.svg', NULL, '{}', '2025-02-10 05:57:37.818+00', '2025-02-10 05:57:37.818+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_vx39OEuATIulIoYiLeppQo85', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Welcome', NULL, '{}', 'Dear Guest,\n\nWe are delighted to have you with us at [Hotel Name]. Whether you''re here for business or leisure, our team is dedicated to making your stay both comfortable and memorable.\n\nThis Digital Compendium is designed to be your guide throughout your stay. Here, you''ll find all the essential information you need about our hotel, services, and facilities, as well as tips for exploring the local area.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/ThumbsUp.svg', NULL, '{}', '2025-02-10 05:57:37.821+00', '2025-02-10 05:57:37.821+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_87F1dBQ3fYhj6ZzIWdeNNzPW', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Cancellations', '', '{}', '<p><strong>Our cancellation policy</strong></p><p>Flexible reservations may be cancelled or amended up to 7 days prior to the day of arrival date without any charges.</p><p><br /></p><p>Reservations cancelled or amended after 7 days, prior to arrival, will incur a fee of one nights'' accommodation.</p><p><br /></p><p>Bookings made via third parties must be cancelled directly with the relevant booking agent.</p><p><br /></p><p>Bookings made across peak periods such as Christmas, Easter and long weekends have a 14-day cancellation policy.</p><p><br /></p><p>View our complete Terms and Conditions at our website.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Bag.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738815540087_capt%20cove%20jetty.png}', '2025-02-06 03:26:33.909+00', '2025-02-06 07:32:28.174+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_GRGPJ71WXhdqtwHC05slwl5V', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Accessable Apartment', '', '{}', '<p><strong>Accessible Apartment</strong></p><p>Book 1, 2 or 3 Bedrooms (Max. 6 Guests)</p><p><br /></p><p>Apartment 9, is designed with three bedrooms and two bathrooms, offering ample space and comfort for all guests. While the apartment is not built to “accessible” standards, we have retrospectively fitted it to meet the needs of guests with accessible requirements.</p><p><br /></p><p>It is the only apartment with ground floor access overlooking the water, boasting a large deck leading out from the bedroom for scenic views.</p><p><br /></p><p>Master queen bedroom on the ground floor, offering a TV and private balcony with canal views.</p><p><br /></p><p>Second bedroom on the second storey, offering a queen bed, TV and private balcony with canal views.</p><p><br /></p><p>Third bedroom on the ground floor, offering twin beds.</p><p><br /></p><p>Fully self-contained kitchen with a dishwasher, full oven, microwave, One Fairtrade tea, coffee and hot chocolate, and Nespresso coffee machine</p><p><br /></p><p>Dining and lounge area with 55in smart TV</p><p><br /></p><p>Bathroom on ground floor (fitted with handrails, a shower seat, and a larger walk-through shower) and second storey, with quality Biology amenities.</p><p>A toilet frame is available on request.</p><p><br /></p><p>Laundry with washing machine, dryer, clothes rack and ironing facilities.</p><p><br /></p><p>Outdoor area with deck, BBQ, outdoor setting and jetty</p><p><br /></p><p>High speed internet</p><p><br /></p><p>We recommend contacting our reservations team directly to request the accessible apartment.</p><p><br /></p><p>There is a small lip at the entrance door of the apartment. </p><p>Wheelchair access to the boardwalk is next to apartment 9.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Home.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811447167_Accessible-Apartment-Exterior-View.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811450813_Accessible-Apartment-Dining-and-Lounge-Area02.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811561040_Accessible-Apartment-Bathroom.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811578112_Accessible-Apartment-Laundry-scaled.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811584341_Accessible-Apartment-Master-Queen-Bedroom.jpg}', '2025-02-06 02:47:29.083+00', '2025-02-06 07:00:16.219+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_VT3eFwjcPdEIH4npP1Lg93Ku', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Parking Information', NULL, '{}', 'Ample parking is available for all guests, with options for valet or self-parking. Spaces are secure and easily accessible, providing peace of mind for those traveling by car.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, '{}', '2025-02-10 05:57:37.824+00', '2025-02-10 05:57:37.824+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_abb4bff2c90d4e9f88d0e01d', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'SURFING', NULL, '{}', '<p>Samoa is also popular among surfers seeking excellent conditions without the usual overcrowding. Swells can sit anywhere between 2 and 15 foot on a good day. The south beaches on Upolu and Savai’i have consistent surf year round, while the northern shores are ideal during December to February. Most surfing locations consist of reef breaks so be sure to orientate yourself to the local conditions to ensure your safety. It’s also worth donning booties on your surf adventures to avoid the sharp coral – you’ll thank them at the end of day! For beginners, consult with a local surfing guide to find out the safest locations and best techniques to tackle the waves. Surfers need to pay a fee each time they surf in Samoa with the money then invested back into regional schools.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739227494092_375742-local-children-with-surfboards-web-1280px.jpg', NULL, '2025-02-10 05:50:09.101331+00', '2025-02-10 22:44:57.036+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_VN4G9VdwF6Pv07x03E0Tlk5y', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Public Transport Options', NULL, '{}', 'Our location offers excellent access to public transportation, with nearby bus stops and train stations connecting you to major attractions and business centers. Speak to our concierge for route recommendations.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaShuttleVanSolid.svg', NULL, '{}', '2025-02-10 05:57:37.827+00', '2025-02-10 05:57:37.827+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ea1c750da8e7413bbb0ef74e', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'SWIMMING HOLES', NULL, '{}', '<p>A visit to Samoa wouldn’t be complete without seeing the famous To Sua Ocean Trench. Surrounded by lush tropical vegetation, this attraction formed by an old lava eruption is one of the most idyllic swimming holes you’ll ever encounter. Just mind your step on the long ladder on your way down. To Sua is open Monday to Saturday 8.30am-5pm and Sunday 12.30pm-5pm. The Piula Cave Pool is also worth checking out. Curious swimmers can explore the two connecting underwater caves, otherwise you can simply enjoy the refreshing qualities of this lovely rockpool. The pool is open Monday to Saturday 8am-4pm.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739227559802_376385-a-rockpool-on-the-coast-of-matareva-upolu-web-1280px.jpg', NULL, '2025-02-10 05:50:09.17733+00', '2025-02-10 22:46:01.692+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_bCONfPkbC5OBYqThKvp9xlpT', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Apartment Amenities', '', '{}', '<p><strong>Apartment Amenities</strong></p><p>Master king bedroom on the second story, offering a TV and private balcony with canal views.</p><p><br /></p><p>Second bedroom on the second storey, offering queen or twin beds. (configuration options upon request)</p><p><br /></p><p>Third bedroom on the ground floor, offering queen or twin beds.</p><p><br /></p><p>Fully self-contained kitchen including a dishwasher, full oven, microwave, One Fairtrade tea, coffee and hot chocolate, and Nespresso coffee machine.</p><p><br /></p><p>Dining and lounge area with 55in smart TV</p><p><br /></p><p>Bathroom on ground floor and second storey, with quality Biology amenities.</p><p><br /></p><p>Laundry with washing machine, dryer, clothes rack and ironing facilities.</p><p><br /></p><p>Outdoor area with deck, BBQ, outdoor setting and jetty.</p><p><br /></p><p>High speed internet</p><p><br /></p><p><strong>Extra Bed:</strong> A fold out bed is available at $30 per night; this includes doona and towel etc. Note that the additional bed is only available when all 3 bedrooms are booked.</p><p><br /></p><p><strong>Pool Towels:</strong> We provide 4 complimentary pool towels in your apartment. If you require additional towels you can request this prior to or after check in.</p><p><br /></p><p><strong>Baby Items:</strong> Travel cots, including a sheet set and blankets, ($15 per day) and highchairs ($10 per day) are available on request from Guest Services. <strong>Pre-booking is highly recommended.</strong></p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Hairdryer.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811275204_biology%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811279937_biology%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738811399447_fairtrade%20coffees.jpg}', '2025-02-06 02:47:23.282+00', '2025-02-06 06:56:53.173+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_bWW5ulsVHpy9S3Zn0vbjEGtl', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Resort Facilities', 'Relax and unwind with leisure at your fingertips.\n', '{}', '<p>Set amongst peaceful gardens, our resort boardwalk meanders along the waterfront with each apartment offering a balcony off the master bedroom, a deck leading out from the living area with BBQ and outdoor dining overlooking your private jetty. From the jetty you can fish, swim or tie up a boat.</p><p><br /></p><p><strong>Our resort facilities include:</strong></p><p>Indoor heated pool</p><p>Tennis court</p><p>Basketball ring</p><p>Fishing &amp; cleaning area</p><p>Boat wash area</p><p>Private jetties</p><p>Wi-fi throughout resort</p><p>Trailer parking</p><p>Space for additional parking.</p><p><br /></p><p><strong>Sports Equipment Hire:</strong> Kayaks, hobies and stand-up paddle boards (including life jackets, which are required to be worn by law), are available to hire from Paynesville Paddle Pedal Play (0472 907 707)</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaDribbble.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816349432_capt%20cove%20kayak.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738200122701_captCove%2021.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738200436846_captCove%2028.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738814324089_capt%20cove%20tennis.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738200588003_captCove%2017.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738200456862_captCove%2026.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738815824599_captcove%20bikes.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738200812527_captCove%2018.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816359440_capt%20cove%20kayak.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816364518_capt%20cove%20bike%20hire.png}', '2025-01-24 00:52:49.754+00', '2025-02-12 03:38:38.017+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_hBCtUnZFEsbvNIa3Wa56dVBH', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Apartment Servicing', '', '{}', '<p>Apartments are cleaned and serviced on the 7th day (or at a time arranged with Reception) for all stays over 7 days.</p><p><br /></p><p>Rooms are not serviced on weekends or Public Holidays.</p><p><br /></p><p>As our apartments are fully self-contained we do not provide breakfast services.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Trolley.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738813906100_captcove%20services%2001a.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816442335_capt%20cove%20staff01.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738815792995_captcove%20services.png}', '2025-02-06 02:47:35.537+00', '2025-02-06 07:01:14.9+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_9zDvSr9SPuYaUr9RWt51zryt', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Parking', '', '{}', '<p><strong>Car, trailer &amp; boat parking is free</strong>.</p><p><br /></p><p>Each apartment has it''s own covered carport located at the rear of the apartment.</p><p><br /></p><p>Boat trailer parking is available opposite apartments 24-26. </p><p>Guests are welcome to use the hose to wash down your boat.</p><p><br /></p><p>Additional cars can be parked adjacent to the pool or on the lawn area opposite Apartments 24-26.</p><p><br /></p><p>Each exclusive apartment has its own private jetty in Gippslands'' most protected waterfront, mooring for holiday and boating enthusiasts.</p><p><br /></p><p><strong>Electric Car Charger:</strong> A charger is located in the Raymond Street carpark, just 20m from the Resort.</p><p><br /></p><p>There is an outside power point on the BBQ so cars can be charged from the apartment. You will need to bring your own 15 meter power chord.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816742927_Accessible-Apartment-Exterior-View.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738816771001_captCove%2026.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738819976202_capt%20cove%20parking.png}', '2025-02-06 04:38:20.504+00', '2025-02-06 07:29:05.11+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_fdY1FMM9zvuQahHRLw67TNCA', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Apartments', 'Welcome to Captains Cove Waterfront Apartments', '{}', '<p><strong>Captains Cove Waterfront Apartments</strong></p><p>Our absolute waterfront apartments offer a special retreat, thoughtfully and stylishly designed across 15 townhouses. On the ground floor, you’ll find living, kitchen, and deck areas overlooking the water, while upstairs, the master bedroom boasts a king bed, private balcony with stunning water views.</p><p><br /></p><p>While all of our apartments are 3 bedroom/2 bathroom, the furnishings do vary slightly, as they are owned by individuals.</p><p><br /></p><p><strong>Configurations are:</strong></p><p>Apartments 9, 10, 11, 15, 16, 17, 18, 20, 23, 24 and 26 offer:</p><p>1 King, 1 Queen, and 1 Twin room.</p><p><br /></p><p>Apartment 19 features:</p><p>1 King and 2 Queen rooms</p><p>.</p><p>Apartments 21, 22 and 25 include:</p><p>1 King and 2 Twin rooms.</p><p><br /></p><p><strong>Accessible apartment is available at Captains Cove Waterfront Apartments. </strong></p><p>Apartment 9 is specifically designed to accommodate guests with mobility needs, featuring a ground floor bedroom with waterfront views, a spacious deck, and a larger bathroom equipped with handrails and a shower seat. Additionally, amenities such as a toilet frame are available upon request.</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Home.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738817845455_capt%20cove%20boat.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738640781617_CaptCoveapt.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738818072847_capt%20cove%20bedroom%2002.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658386943_captCove%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658391335_captCove%20004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658396374_captCove%2005.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658401295_captCove%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658405436_captCove%2007.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738817894185_capt%20cove%20interior%2001.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658416791_captCove%2009.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658436574_captCove%20011.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738658466560_captCove%20010.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738815735501_Balcony-view-across-the-canals-Captains-Cove-Waterfront-Apartments.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738817003340_capt%20cove%20outdoor.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738817183814_captCove%2023.png}', '2025-02-04 03:45:23.28+00', '2025-02-06 07:35:22.776+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_Oir06Pv6wz3XCqTWGyLPacHx', 't', 'none', 't', 'user_fz7yqyAzY38oHyae5RCw1vtANgf', '{}', 'Address & Directions', 'It''s Holiday Time!\nThe many ways to visit Paynesville.', '{}', '<p>From Bairnsdale, East Gippsland’s major town, you will drive 20 minutes along the Mitchell River before you arrive at Paynesville.</p><p><br /></p><p><strong>Our Address: </strong>19 Mitchell St, Paynesville 3880, Victoria</p><p><br /></p><p><strong>By Car to Paynesville:</strong></p><p>Melbourne CBD: 294km (3.5 hrs)</p><p>Canberra: 466km (5 hrs)Sydney: 747 km (8 hrs)</p><p><br /></p><p>The Sydney to Melbourne coastal touring route takes you through laid back seaside towns, National Parks teeming with wildlife, sandy beaches and fresh seafood.</p><p><br /></p><p>We highly recommend this trip at least once!</p><p><br /></p><p><strong>By train to Paynesville:</strong></p><p>Travellers can opt for public transportation, with VLine train services travelling several times per day from Melbourne to Bairnsdale.</p><p><br /></p><p>We are very fortunate that the Paynesville Bus service connects with the VLine train service and delivers our guests to Captains Cove; just ask the driver when you get on the bus!</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaMapMarkedAltSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738819944544_capt%20cove%20top.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738202887601_Screenshot%202025-01-30%20at%2013-06-03%20Captains%20Cove%20Waterfront%20Pretty%20as%20a%20picture%20%23seeyouatthecove%20%23visiteastgippsland%20%23lovegippsland%20Instagram.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_CggFZmQYS9UL6fqbvyVrdpymuGg/1738203201573_Screenshot%202025-01-30%20at%2013-06-11%20Captains%20Cove%20Waterfront%20Look%20what%20we%20found%21%20Matching%20Austin%20Healeys%20at%20the%20Cove%20blending%20in%20nicely%20with%20our%20branding%20too.%20Road%20trip%20to%20Dargo-%20perfect%20day%20for%20it....%20Instagram.png}', '2025-01-24 00:52:49.75+00', '2025-02-06 07:38:55.567+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('4b0fe5e484ea498e8d5fb9b1fce95a8d', 'f', 'sidebar', 't', 'user_0000000000003_0000FREEUSER', '{17b77714a900480bbddaa01140fd8cd2,40e199c1e2e64bc59e19f72e7133ce5e,d7c04e6a84b244a49d5a3b503f149578,88e54c284352445fbeeaece821b638b3,bfabe625930e4d5eaf337419476ec701,8f0852dc5add4b05a77409dac4d2408b,1ee8e211407c442c8a61ae77a3664729}', 'Things to do', NULL, '{}', ' ', NULL, NULL, NULL, NULL, NULL, '2025-01-22 03:06:14.728202+00', '2025-02-10 03:04:13.948+00');
