INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('f8536c89752c452a9e43b8d2eebc38a4', 'f', 'overlay', 't', 'user_0000000000003_0000FREEUSER', '{e8f9aa4ea4db4a4eaddbbc613213624d,e768c6f3be4243d89df96c551a9bdb44,542c960f4f924d5b9fc1a9c1dd1ae41f,2c76ebaf3e7c4f339a6cc8e43cc2fccc,bf23cafb09734503bb48744519047556,231042fe804f42fca5d01f282597b575,d56c0fca82954733b0594fbf60b6eb71}', 'South East Asian / Asian', NULL, '{}', ' ', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', NULL, NULL, '2025-01-22 03:06:15.02919+00', '2025-02-10 03:58:08.235+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('42ef670ba3514577af0445e1e5ea8545', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Ella by Minoli', 'Modern Sri Lankan Flavours', NULL, '<p>Modern Sri Lankan Flavours. Ella by Minoli is the result of decades of obsession with food, flavour, and great hospitality. At Ella, it’s not just about the food – it’s an experience. When you walk through the doors, you become family… so step into our home, activate all your senses and get ready for a journey through the flavours of Sri Lanka through the eyes of Minoli.</p>', NULL, '{"name": "Ella by Minoli", "type": "restaurant", "latitude": -12.4645071, "longitude": 130.8421957}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735474936_ella%2007.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735482683_ella%2007.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735489288_ella%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735493364_ella%2009.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735508011_ella%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735502763_ella%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735513002_ella%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735517056_ella%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735522724_ella%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735527653_ella%2005.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734735533929_ella%20010.jpg}', '2025-01-22 03:06:16.933148+00', '2025-02-10 04:09:36.976+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('3ac58b1237184f0794abe424fe7e9ff4', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Taj Curry', 'Artfully crafted Nepalese and Indian Cuisine', '{"phone": "1300 452 107", "website": "https://www.tajcurrydarwin.com.au/gallery"}', '<p>Step into our intimate sunlit space and immerse yourself in a warm and inviting atmosphere. Bathed in natural light, the space exudes a tranquil charm, creating a cosy and relaxed ambiance for your dining pleasure. Whether it’s a romantic evening or a gathering of close friends, our sunlit space sets the perfect stage for cherished moments and meaningful connections. Experience an evening of flavour and festivity at Taj Curry - Nepalese and Indian Cuisine!</p><p> </p><p>Whether it''s an intimate gathering or a grand celebration, we have the perfect venue to accommodate your needs. Choose between our cosy Himalayan Hall for up to 30 guests or our spacious Taj Hall for up to 130 guests. Reserve your spot today and let us spice up your event.</p>', NULL, '{"name": "Taj Curry", "type": "restaurant", "latitude": -12.3795258, "longitude": 130.8489012}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736209300_TAJ%2001.jpeg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736218848_TAJ%2001.jpeg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736237275_TAJ+02.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736246372_TAJ%2003.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736256149_TAJ%2004.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736259706_TAJ%2005.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734736263933_TAJ%2006.png}', '2025-01-22 03:06:16.911189+00', '2025-02-10 04:14:28.469+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('0394245010804c7e96eba9b08668818f', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Four Birds Cafe', 'A hidden gem just off Smith St in the Star Village arcade.', NULL, '<p>A hidden gem just off Smith St in the Star Village arcade. Have breakfast or brunch under dappled shade in the open and cozy courtyard. Open for breakfast, lunch and dinner. Grab a smoothie, poke bowl, all day breakfast a wrap or just a coffee. Vegetarian friendly, vegan &amp; gluten free options. Open all day Mon - Friday</p>', NULL, '{"name": "Four Birds Cafe", "type": "restaurant", "latitude": -12.464065, "longitude": 130.8431731}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737046048_4BIRDS%2001.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737055841_4BIRDS%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737061204_4BIRDS%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737068910_4BIRDS%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737073917_4BIRDS%2005.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737076908_4BIRDS%2006.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737079307_4BIRDS%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737080289_4BIRDS%2007.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734737085944_4BIRDS+08.jpg}', '2025-01-22 03:06:16.775216+00', '2025-02-10 04:15:21.357+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('4c1c201c624f4809ba19bc41d4956ec2', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Oyster Bar Darwin', 'Darwin''s finest & freshest oysters', '{"phone": "08 89812242", "website": "http://www.oysterbar.com.au/"}', '<p>Darwin''s finest, freshest oysters.The Oyster Bar is ideally located at Darwin City Waterfront Precinct. There’s no better place to take advantage of Darwin’s climate and lifestyle. Call to make a reservation.</p>', NULL, '{"name": "Oyster Bar Darwin", "type": "restaurant", "latitude": -12.4682472, "longitude": 130.8464806}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753810059_oyster-darwin.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753816777_oyster-darwin.png,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754157392_oyster%2006jpg.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753960796_oyster+07.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753950457_oyster%2004.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753935389_oyster%2001.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753945847_oyster%2003.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734753964208_oyster%2008.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754098969_oyster%2002.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734754036192_oyster%2009.jpg}', '2025-01-22 03:06:17.246297+00', '2025-02-10 04:20:55.748+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_uAjcGgUx99fFlmRYQNpltE0r', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Shuttle Bus', NULL, '{}', 'We offer convenient shuttle services to and from the airport, as well as popular local destinations. Schedules and pick-up points are designed to align with your itinerary, ensuring hassle-free transport throughout your stay.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', NULL, '{}', '2025-02-10 05:57:37.831+00', '2025-02-10 05:57:37.831+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_UFnXFIurtQNGxNKpgGrprhrO', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Restaurants', NULL, '{}', 'Delight in our on-site restaurants, where a variety of cuisines are prepared by world-class chefs. Whether you prefer a casual meal or a fine dining experience, our menus cater to all tastes and dietary preferences.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieBiteSolid.svg', NULL, '{}', '2025-02-10 05:57:37.834+00', '2025-02-10 05:57:37.834+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_OLxFtUpr3Taagl8O960z62Fy', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Room Service', NULL, '{}', 'Enjoy the convenience of room service, offering a wide selection of meals and beverages delivered directly to your door. Available 24/7, it''s perfect for a late-night snack or a relaxing breakfast in bed.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieSolid.svg', NULL, '{}', '2025-02-10 05:57:37.837+00', '2025-02-10 05:57:37.837+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('fb2ea9b044ed41ddaa75ea5036584af0', 'f', 'sidebar', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Services & Facilities', 'Hilton Hotel Managed Point', '{}', '', 'HotelManagedEndpoint', NULL, NULL, NULL, NULL, '2025-01-22 03:06:16.691216+00', '2025-02-10 04:25:22.208+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ieGLF3V68v4uiBw5kp9Xx5Mg', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Kids''Activities', NULL, '{}', 'Keep the little ones entertained with our selection of Kids'' activities, from supervised play areas to fun workshops. Our family-friendly environment ensures a memorable stay for guests of all ages.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabySolid.svg', NULL, '{}', '2025-02-10 05:57:37.84+00', '2025-02-10 05:57:37.84+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_ZQfeYw7BPeMaUy0vwEzmlLuE', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Fitness Center', NULL, '{}', 'Maintain your workout routine at our fully equipped fitness center, featuring modern machines and free weights. Open daily, the facility is designed for your convenience and comfort.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaRunningSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375130362_Fitness_Center_2.png}', '2025-02-10 05:57:37.843+00', '2025-02-10 05:57:37.843+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_4jz7v4O5gSkGmdFxgrgDC3mh', 'f', 'sidebar', 't', 'user_0000000000003_0000FREEUSER', '{content_uAjcGgUx99fFlmRYQNpltE0r,content_VT3eFwjcPdEIH4npP1Lg93Ku,content_VN4G9VdwF6Pv07x03E0Tlk5y}', 'Transportation', NULL, '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736818194015_03_limousine_transfer.jpg', '{""}', '2025-02-10 05:57:37.847+00', '2025-02-10 05:57:37.847+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_28c9a777f05c4a839a53037f', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'BEACHES', NULL, '{}', '<p>Travel to the south eastern region of Upolu to spend a languid day relaxing at Lolomanu Beach.</p><p><br /></p><p>Lined with vibrant beach fales, this beautiful sandy stretch offers idyllic ocean views and is perfect for taking a dip or snorkelling over rainbow coloured marine life.</p><p><br /></p><p>Refreshments are available at some of the fales here. Beach fales for your own personal use will cost you approximately WST$30.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739227239822_376886-vavau-beach-13.jpg', NULL, '2025-02-10 05:50:09.027294+00', '2025-02-10 22:40:42.679+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_441cf5f97da040af9b47c711', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'WESTERN REGION OF UPOLU', NULL, '{}', '<p>Pack a picnic lunch or allow time to stop in and have lunch at Return to Paradise Resort. The resort’s Cabana Café is open daily and offers a great range of tapas and wood-fired pizzas for lunch. After lunch, don’t miss visiting the Giant Clam Sanctuary at Savaia. A truly spectacular attraction, you could easily spend a whole day swimming, kayaking and snorkelling over giant clams. A memory you’ll never forget!</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228046575_376406-the-cathedral-of-immaculate-conception-apia-samoa-web-1280px.jpg', NULL, '2025-02-10 05:50:09.481381+00', '2025-02-10 22:54:08.953+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_5dea4d79df0d454c9cbf3744', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Saleaula Lava Ruins', NULL, '{}', '<p>The Lava ruins are fascinating to visit and the story of the villagers that surrounds the history of the lava ruins shows the resilience and tenacity of these amazing people. The site of the ruins shows an old catholic church and a grave site known as Virgin’s Grave and is a result of an eruption that occurred in 1905 and went on until 1911. The church itself is intriguing because the walls are made from local cement which is produced from crushed coral. The Saleaula Lava Ruins are open Monday to Saturday 9am-5pm and Sunday 1pm-5pm. Entry is WST$10 for adults and WST$5 for children (5-12 years)</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228387079_376194-salaaula-lava-fields-church-savaii-web-1280px.jpg', NULL, '2025-02-10 05:50:09.629476+00', '2025-02-10 22:59:52.516+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_e394372a461846808ec10746', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Falealupo', NULL, '{}', '<p>Visit the tree canopy walk which is not far past the Lava Ruins. The climb looks a bit rickety but definitely safe and there are two levels to explore. Firstly go to the actual bridge which is twelve metres above the ground, then once you reach the other side, you climb the staircase another ten metres to discover the lookout. The entry ticket for Falealupe will also give you entry to Moso’s Footprint and the House of Rock. Moso’s Footprint is an incredible legend about the giant who walked across the globe and left his footprint in the rock. The rock shows a marking which is identical to a left footprint and the right footprint is found in Fiji. The legend goes that Moso’s giant steps would mean that he could walk across the pacific countries just like a person walking across stones in a riverbed. One foot in one country and the other foot in the next</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228464685_374402-stairs-to-canopy-walk-2-web-1280px.jpg', NULL, '2025-02-10 05:50:09.705359+00', '2025-02-10 23:01:07.122+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_0084be9af8654d78bef51278', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'ASAU AREA', NULL, '{}', '<p>Travel onto Asau and its worth doing a cocoa plantation visit. The famous Samoan cocoa is world renowned and even though this uniquely rich cocoa is sold to Whittakers chocolate in New Zealand, it is regularly taken locally, as a cultural drink. The seeds are picked and dried on sheets of iron, then tossed to remove the burnt shell. The black, inside of the seed is crushed and made into a paste which the locals call “Koko Malu”. It is poured into a bowl or a cup and mixed with hot water and sugar. Koko Malu is a staple drink for Samoans and definitely worth a try.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228585155_374516-couple-drinking-coffee-outside-3-web-1280px.jpg', NULL, '2025-02-10 05:50:09.778427+00', '2025-02-10 23:03:06.912+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_710d49644b5d4a3dadac18b2', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'ALOFAAGA BLOWHOLES', NULL, '{}', '<p>The Alofaaga Blowholes are an impressive sight to see. The best time to visit is during high tide, preferably in the morning or early afternoon. The road down to the blowholes is narrow, but safe to drive. Be sure to check at the gate before driving down, just in case there has been a lot of rain, making things boggy and difficult to get through. These blowholes extend for a considerable distance and the strong ocean waters ascend into the sky for up to 40 metres. Although safe to approach, always remember that the water is powerful so be vigilant. There is no consistency as to which holes blow water and the forces are strong.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228796510_376477-alofaaga-blowholes-4-web-1280px.jpg', NULL, '2025-02-10 05:50:09.851482+00', '2025-02-10 23:06:38.242+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('bc74731725744e06bbbfef9e8753cfcc', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Mindil Beach Sunset Market', NULL, '{"phone": "08 89813454", "website": "https://mindil.com.au/", "facebook": "https://www.facebook.com/mindilmarket", "instagram": "https://www.instagram.com/mindilmarket/"}', '<p>Experience Mindil. Mindil Beach Sunset Market is the place to be for events, functions, and a family night out. Hosting over 200 specialty stores and food vendors, it’s a truly unique experience. Mindil Beach Sunset Market has been a Territory icon for over 30 years; providing an extraordinary bi-weekly event that is the multicultural ‘melting pot’ and truly reflective of the Darwin community and lifestyle! Mindil Beach Sunset Markets is an integral part of the local community. Hosting charity-based stalls and free community-led events that entertain, educate and raise funds for the benefit of all Territorians. It remains a place to gather, connect, engage and plays a vital role in nurturing local talent from all walks of life.</p>', NULL, '{"name": "Mindil Beach Sunset Market", "type": "shop", "latitude": -12.4441452, "longitude": 130.8321533}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaStoreSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166732237_sunset%20market1.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166735261_sunset%20market1.jpg}', '2025-01-22 03:06:15.535224+00', '2025-02-10 05:52:21.097+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_WFdROYsUPJwq0CxWwBMEq23X', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Check-in/Check-out', NULL, '{}', 'Our check-in process is quick and efficient, ensuring you settle into your room with ease. Check-out is equally seamless, with staff available to assist you at any time. Flexible options are available upon request.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCalendarCheck.svg', NULL, '{}', '2025-02-10 05:57:37.798+00', '2025-02-10 05:57:37.798+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_V9GXePSyUhZqTFdJdH7IMxVB', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Wi-Fi', NULL, '{}', 'Our hotel provides seamless Wi-Fi connectivity throughout the premises. Whether you are in your room, at the restaurant, or in the lobby, you can stay connected to what matters most. Enjoy fast and reliable internet for work, streaming, or browsing at your convenience.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaWifiSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736374246014_Wi-Fi_2.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736374251653_Wi-Fi_2.png}', '2025-02-10 05:57:37.802+00', '2025-02-10 05:57:37.802+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_jupZpT2TBJnmaaH2eodAPlBn', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Swimming Pool', NULL, '{}', 'Take a refreshing dip in our swimming pool, available exclusively to hotel guests. Relax on poolside loungers or enjoy a leisurely swim in a serene and inviting setting.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmerSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375098423_Swimming_Pool_4.png}', '2025-02-10 05:57:37.805+00', '2025-02-10 05:57:37.805+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_21a4c4b5af684926bf0ee4a2', 'f', 'overlay', 't', 'user_0000000000001_0000000ADMIN', '{content_6ff58d040d10442c995ba916,content_28c9a777f05c4a839a53037f,content_abb4bff2c90d4e9f88d0e01d,content_ea1c750da8e7413bbb0ef74e,content_26dd8f7b92e64c469f26b0e2,content_cd9c4778626b42e8b07b4275,content_794f61a90e194aea8690d7ff,content_47e30794584143d399413ae0}', 'Outdoor & Water Adventures', NULL, '{}', 'Template', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, NULL, '2025-02-10 05:50:11.8614+00', '2025-02-11 00:54:19.278+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_77a6cdbb9dbf470c88a4f3b1', 'f', 'overlay', 't', 'user_0000000000001_0000000ADMIN', '{content_f7bb2392c49d482c98997089,content_ca9e4c1c90d847c6a7f6a8bf,content_786ebb23995240119e2b8453,content_3c1cbbc4049a434aac239bdc,content_45bee0e52c3541838aa46247,content_ec660821a65243f19f50c27d,content_95969739c2fd48fa9b98517b,content_ed84fa1f730c4f5492144205}', 'Cultural & Flavors', NULL, '{}', 'Template', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCalendarAlt.svg', NULL, NULL, '2025-02-10 05:50:11.932221+00', '2025-02-11 00:55:20.263+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_303cf74a60004f02886d991b', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'New Year’s Fireworks', NULL, '{}', '<p>January - New Year’s Fireworks Display. February Motherland Concert. March Samoa Tourism Exchange. April Samoa International Game Fishing Tournament, Samoana Jazz &amp; Arts Festival. JUNE Vailima Marist Samoa Rugby 7s, Independence Celebrations, Samoa International Marathon. JULY Pacific Open Water Championship, Savai’i Experience Warrior Race Triathlon. August Apolima Strait Swim, Tour of Samoa Cycling, Negative Split Tour of Samoa. SEPTEMBER Miss Samoa Pageant Teuila Festival, Food &amp; Wine Festival. OCTOBER White Sunday National Holiday, Palolo Rise (a week after full moon either Oct or Nov). NOVEMBER Perimeter Relay. DECEMBER Christmas on the Waterfront, New Year’s Eve Countdown &amp; Fireworks Display</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739231877311_375025-three-fire-dancers-2-web-1280px.jpg', NULL, '2025-02-10 05:50:11.640754+00', '2025-02-10 23:57:59.581+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_1ef449c413c446c9a1f60227', 'f', 'overlay', 't', 'user_0000000000001_0000000ADMIN', '{content_2a5e2dc42e4844bbb0da5f63,content_0084be9af8654d78bef51278,content_e394372a461846808ec10746,content_5dea4d79df0d454c9cbf3744,content_710d49644b5d4a3dadac18b2,content_caee98259d474e9c9f6fc9c8,content_8f07f37ec3774562a6486748}', 'Discover Savai‘i', NULL, '{}', 'Template', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaVolleyballBallSolid.svg', NULL, NULL, '2025-02-10 05:50:11.78828+00', '2025-02-11 00:54:05.123+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_473220a00ddd454b94a0469b', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'THINGS TO DO ITN UPOLU', NULL, '{}', '<p>The island of Upolu is a tropical haven just waiting to be explored. Here are some local tips to help you get the most out of your stay. Things to do in apia Take a leisurely walk through the nation’s capital to explore the local culture. A wander through the local flea market will unearth a range of local wares, from colourful sarongs to unique carvings and jewellery. Be sure to try a delicious, home-made Samoan doughnut available from one of the food stands. Next, head down to the local food market and pick up some exotic fruit and vegetables (such as Taro). Marvel at the beautiful flower arrangements which could be a perfect gift for a loved one. For lunch, you can’t go past Milani Caffe where Giovanni will make you feel right at home. For a light drink, try a Niu (fresh coconut). In the afternoon, head back to your hotel to relax so you’re ready for an entertaining evening at a local Fiafia Show. Many venues host Fiafia nights so you won’t be short on options. Don’t miss the Cultural Show at the Samoa Tourism Authority to fully immerse yourself in the Samoan culture. Discover the fascinating rituals of local tattooing, dancing, cooking and weaving. Stroll along the strip to marvel at the beautiful ocean views.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739227727332_376895-wolfpac-atv-tour-8.jpg', NULL, '2025-02-10 05:50:09.332477+00', '2025-02-10 22:48:50+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_6ff58d040d10442c995ba916', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'AQUATIC ADVENTURES', NULL, '{}', '<p>Visitors to the beautiful region of Samoa are spoilt for choice when it comes to water sports.</p><p><br /></p><p>The region’s abundant marine life, pristine waters and clear visibility all make Samoa a superb diving and snorkelling destination.</p><p><br /></p><p>The reefs and lagoons surrounding the islands boast over 300 coral varieties and 1,000 fish species. Divers in particular are privy to reef sharks, sting rays, moray eels, gorgonian fans and much more, not to mention spectacular coral reefs.</p><p><br /></p><p>Visitors can also venture across to Savai’i for a majestic experience swimming with giant turtles. For those keen to stay on top of the water, explore the lagoons at your leisure in a kayak.</p><p><br /></p><p>For fishing enthusiasts, the region offers many opportunities for deep sea fishing.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBicycleSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739226653265_376030-waterfall-in-forest-in-samoa-web-1280px.jpg', NULL, '2025-02-10 05:50:08.950384+00', '2025-02-10 22:30:57.09+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_5ea34c2e3210469c985b740c', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'SOUTHERN REGION OF UPOLU', NULL, '{}', '<p>Hire a car and head to the south side of Upolu via Centre Island Road. On the way, make a stopover at the Robert Louis Stevenson Museum and experience the beautifully restored island plantation which the author once called home. Take a stroll through the lush Vailima Botanical Garden and take a dip in the pool once frequented by Stevenson. Another must-see on your way to the south is the awe-inspiring Papapapaitai Waterfall, known as the longest waterfall in Samoa. When you get to the south, head east which will take you through local villages where you’ll encounter friendly locals. Drop into one of the beautiful resorts such as Saletoga Sands or Seabreeze Resort for some delicious refreshments. As you pass Saletoga Sands, keep an eye out for a sign ‘To Sua Trench’ which is a picturesque blowhole perfect for a refreshing swim. For an afternoon snack and drink, try Aga Reef Resort or Litia Sini nestled on the edge of the water, then head out to the famous Lalomanu Beach for a swim. Lalomanu Beach is renowned for its powdery white sand and incredibly clear waters that offer incredible conditions for snorkelling, kayaking or simply relaxing on the sand and soaking up the scenery. When you’ve had enough sun, continue your drive around the east side venturing through the mountains and stopping at Piula Cave Pool.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739227810795_375824-couple-walk-in-upolu-3-web-1280px.jpg', NULL, '2025-02-10 05:50:09.406297+00', '2025-02-10 22:50:13.095+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_fLRp3D0qDGRJx9o7S4sVAwQI', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Swimming Pool', NULL, '{}', 'Take a refreshing dip in our swimming pool, available exclusively to hotel guests. Relax on poolside loungers or enjoy a leisurely swim in a serene and inviting setting.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmerSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375098423_Swimming_Pool_4.png}', '2025-02-11 03:27:22.092+00', '2025-02-11 03:27:22.092+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_DuylgA1wbrMzSDZ6uUBf1lYu', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Spa Services', NULL, '{}', 'Indulge in relaxation at our spa, offering a range of rejuvenating treatments, including massages, facials, and body therapies. Reservations are recommended for a truly personalized experience.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwatchbookSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736819494597_Massage_Grand_Velas_Riviera_Nayarit_Mexico-1024x682.jpg}', '2025-02-11 03:27:22.095+00', '2025-02-11 03:27:22.095+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_26dd8f7b92e64c469f26b0e2', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'GAME FISHING', NULL, '{}', '<p>Samoa is famous worldwide for exciting game fishing. Anglers from all over the world come to this remote location to experience the exhilaration of the sport which is available all year round. The beautiful, clear waters of the South Pacific are abound with millions of fish. The variety of game fishing in Samoa means that fishermen are able to chase massive blue and black marlin, yellowfin tuna, giant trevally, sailfish, spanish mackerl, mahi mahi, dogtooth tuna and broadbill. Game Fishing operator numbers are limited in Samoa and although it is possible to call on the spur of the moment, it is wise to make contact as early as possible. With its reputation as one of the best game fishing countries on the planet, half and full day outings happen every day and visitors are always urged to call ahead to book. Although the best months for catching big yellowfin (often weighing in excess of 100kg) are between December and June, it is not unheard of catching this massive fish at other times of the year. You can find more information on game fishing in Samoa at either the visitor’s centre in Apia or Savai’i, or by contacting Troppo Fishing Adventures www.fishsamoa.com</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739227648320_376096-fishing-boat-in-lagoon-web-1280px.jpg', NULL, '2025-02-10 05:50:09.254477+00', '2025-02-10 22:47:30.704+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_CIybMgjV4ezVdPCPKriNxo5G', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Hotel Policies', NULL, '{}', 'Our policies are designed to ensure a pleasant stay for all guests. Please familiarize yourself with our guidelines on cancellations, pets, and smoking, which are crafted to maintain a safe and comfortable environment.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaFolderPlusSolid.svg', NULL, '{}', '2025-02-11 03:27:22.098+00', '2025-02-11 03:27:22.098+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_2a5e2dc42e4844bbb0da5f63', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'EXPLORING SAVAI’ISIUFAGA BEACH', NULL, '{}', '<p>Siufaga Beach is in the sunshine section of Savai’i and reputed to have some of the most pristine and beautiful water sections found on the planet. Here you will see turtles just off the beach, white sands and crystal clear waters. You will see various sticks poking out of the water along the beach and this is because it is the turtle park area, where turtles are protected and fishing in these waters is strictly prohibited. As with all beaches in Samoa, there is a requirement to pay if you have plans to swim and sit around. You will generally find that you will be approached by a member of the village and the cost is likely to be WST$10 depending on how long you are planning to stay. Grab some lunch at one of the local BBQ stands (they are small huts and usually one person inside with a large pot) for a simple and very local experience. The cost is likely to start from WST$10 for a large plate of food.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228219488_376410-the-ferry-at-salelologa-wharf-savaii-samoa-web-1280px.jpg', NULL, '2025-02-10 05:50:09.555356+00', '2025-02-10 22:57:04.396+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_caee98259d474e9c9f6fc9c8', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'AFU AAU FALLS', NULL, '{}', '<p>Afu Aau falls is reasonably close to the port of Saleloga and definitely worth a stop and quick swim. The falls are amongst the most picturesque on the planet and a look at this place in real life will stay with you for life. The water is aqua in colour and the falls are deep and refreshing. There are good toilet facilities on site and the walking track to the falls is maintained and in very good condition. Parking here is easy and if you don’t have transport, it’s only a short bus ride of WST$3 from the Port.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228873443_376464-afu-a-au-waterfall-8-web-1280px.jpg', NULL, '2025-02-10 05:50:09.92434+00', '2025-02-10 23:07:55.794+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_10c7a0092cca48c0a47f625d', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'PARKS & WALKS', NULL, '{}', '<p>Explore Samoa’s Best Walking and Hiking Trails. Embark on unforgettable adventures through Samoa’s lush rainforests, pristine lakes, intriguing caves, and volcanic landscapes, all set against the stunning backdrop of the Pacific Ocean. Whether you’re enjoying a leisurely stroll along the family-friendly “Ma Tree” walk on Upolu or taking on the challenging multi-day trek to the summit of Mt. Silisili on Savai’i, Samoa offers a diverse range of walking and hiking trails that cater to all fitness levels, time constraints, and interests.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739228937450_376531-canopy-walk-falealupo-4-web-1280px.jpg', NULL, '2025-02-10 05:50:10.006481+00', '2025-02-10 23:08:59.8+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_f699931976e0437dabfd24c9', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Laauoleola Cave', NULL, '{}', '<p>Laauoleola Cave and Nature Walk Duration: 40+ Minutes Return Difficulty: Moderate. This 15-minute forest trail winds through mahogany, ifilele, teak, kava, eucalyptus, and banyan trees, offering a peaceful introduction to Laauoleola Cave. As you near the entrance, the distinctive clicking of swiftlets darting in and out sets the tone for the adventure ahead. Inside, the lava tube stretches up to 5km (3.1 mi) underground. The first section is an easy, flat walk with a few muddy patches, leading to a descent where guides can arrange a ladder for deeper exploration—just let them know in advance. Fully guided in a relaxed style, the tour includes a torch for cave navigation, though bringing your own flashlight is highly recommended for added visibility.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229209992_376609-piula-cave-pools-5-web-1280px.jpg', NULL, '2025-02-10 05:50:10.163521+00', '2025-02-10 23:13:31.799+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_a9a53c5b0b9c4814a0a7646c', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Falease’ela River Walk Duration', NULL, '{}', '<p>Falease’ela River Walk Duration: 4-6 Hours Loop Difficulty: Challenging. More of a canyoning adventure than a traditional walk, the Falease’ela River Walk is an epic journey through a gorge with a series of stunning waterfalls that grow more spectacular with each step. Access this river paradise with Olsen and the local team from Lalotalie ECAT Ventures, who will guide you through the gorge, showcasing waterfalls of increasing grandeur. For the brave, there are thrilling jumping spots—some as high as 20m (66 ft)— that the guides will happily demonstrate, but there’s no pressure to take the leap if you’d prefer to swim and soak in the pristine rainforest scenery, which is protected as a conservation area. Be prepared to get wet - soaked, in fact! Closed-toe shoes you don’t mind getting wet, along with a t-shirt and shorts, are highly recommended for this exciting and refreshing experience.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229581895_376605-mu-pagoa-2-web-1280px.jpg', NULL, '2025-02-10 05:50:10.456351+00', '2025-02-10 23:19:44.017+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_47e30794584143d399413ae0', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Tafua Crater Duration', NULL, '{}', '<p>Tafua Crater Duration: 1 Hour Return Difficulty: Moderate on this 1-hour hike to the Tafua Crater on Savai’i, your guide from Safua Tours will highlight Samoa’s fascinating and rare wildlife, including the elusive manumea (tooth-billed pigeon) and flying foxes. At the summit, you’ll be rewarded with stunning views of the surrounding coastline and villages. Make sure to wear suitable walking shoes and bring binoculars if you have them, as they’ll enhance your experience of the vibrant wildlife and scenic vistas.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739229999153_376410-the-ferry-at-salelologa-wharf-savaii-samoa-web-1280px.jpg', NULL, '2025-02-10 05:50:10.6043+00', '2025-02-10 23:26:41.053+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_c86bd90383ec43dea73400ba', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Lake Lanoto’o Duration', NULL, '{}', '<p>Lake Lanoto’o Duration: 2 Hour Return Difficulty: Challenging Nestled in the Upolu highlands, Lake Lanoto’o, also known as ‘Goldfish Lake,’ is a stunning pea-green crater lake, named for the goldfish that inhabit its waters. The journey to the lake is an adventure best suited for those who are fit and ready to navigate muddy patches and uphill sections along the way. While the trail can be tackled independently, it’s highly recommended to hire a guide from companies like Samoan Island Adventures, Moana Tours, or Rainforest Runaway Ecotours to ensure you don’t lose your way. Be sure to wear long pants and closed-toe footwear for comfort and protection and bring swimwear for a refreshing dip once you reach the lake.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230188651_376037-coast-with-beach-palm-trees-and-ocean-web-1280px.jpg', NULL, '2025-02-10 05:50:10.753429+00', '2025-02-10 23:29:50.782+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_BtXk3qcpL2mjrUzF3UctLb6A', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Address & Directions', NULL, '{}', 'Located conveniently in the heart of the city, our hotel is easily accessible by car, public transport, or shuttle services. Detailed directions are available on our website, or you can contact the front desk for personalized guidance.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCampgroundSolid.svg', NULL, '{}', '2025-02-11 03:27:22.106+00', '2025-02-11 03:27:22.106+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_8f07f37ec3774562a6486748', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Saleaula Lava Field Duration', NULL, '{}', '<p>Saleaula Lava Field Duration: 45 Minutes Return Difficulty: Easy Explore the remnants of the powerful 1905-1911 Mt Matavanu eruption at the fascinating Saleaula Lava Field. A short walk brings you to the field’s most striking feature: the ruins of the LMS Church, with lava flows that have solidified right through its arching entrances. Follow the sign west for about 300m (328 yards) to discover the mysterious ‘Virgin’s Grave,’ where the lava is said to have miraculously spared the grave of a young girl. Beyond the church ruins, you’ll find a scenic wetland viewpoint. For a longer adventure, continue northeast for about 900m (984 yards) over exposed lava flows to reach the impressive lava cliffs.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230285935_374445-exploring-church-ruins-at-saleaula-1-web-1280px.jpg', NULL, '2025-02-10 05:50:10.829589+00', '2025-02-10 23:31:28.33+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_95969739c2fd48fa9b98517b', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Apia Fish Market', NULL, '{}', '<p>This outdoor market boasts a huge array of seafood, from yellow-fin tuna to crabs, crayfish, octopus and masimasi. The market is open from 5.30am to 11am daily but it is recommended to visit in the early morning to get the best choice of produce. The most popular day to visit is on Sunday. Located next to the Old Flea Market on Fugalei Street.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230533194_374804-selecting-fish-at-market-2-web-1280px.jpg', NULL, '2025-02-10 05:50:11.121365+00', '2025-02-10 23:35:34.576+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_f7bb2392c49d482c98997089', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'TEUILA FESTIVA', NULL, '{}', '<p>Samoa’s Teuila Festival is one of the country’s most celebrated events. The Teuila Festival is held annually in Samoa during the first week of September and is South Pacific’s biggest cultural festivals. An exciting variety of events ensures there is something for everyone to enjoy. Activities include traditional dance competitions, Chief’s Fiafia Polynesian spectacular, Ailao Afi/Fire Knife dancing, the Samoan Police brass band and a choral exhibition. Demonstrations of local culture include tattooing, carving and umu (the Samoan ground oven). Part of the festival is the Miss Samoa Pageant, dedicated to supporting opportunites for young Samoan women. The entrants are encouraged to become role models for the younger generation and represent many professionals, skills, interests and become spokeswomen of the Samoan culture.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739230726037_376206-traditional-fiafia-cultural-dance-show-web-1280px.jpg', NULL, '2025-02-10 05:50:11.266423+00', '2025-02-10 23:38:47.888+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_7a310f9f023443758efb2321', 'f', 'overlay', 't', 'user_0000000000001_0000000ADMIN', '{content_473220a00ddd454b94a0469b,content_5ea34c2e3210469c985b740c,content_441cf5f97da040af9b47c711,content_ce34ad96838041ab8b2fab97,content_abb32b84072d44f186411ee3,content_a9a53c5b0b9c4814a0a7646c}', 'Explore Upolu', NULL, '{}', 'Template', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaPagelines.svg', NULL, NULL, '2025-02-10 05:50:11.715443+00', '2025-02-11 00:53:50+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_JbwQ1ZkjEE9A8ejZgF9Z044f', 'f', 'overlay', 't', 'user_0000000000001_0000000ADMIN', '{content_e5d79b13896a404fa98a81ba,content_10c7a0092cca48c0a47f625d,content_f699931976e0437dabfd24c9,content_702aa6d23be84c4f81d1651d,content_e52b146009864ff4a47a7b70,content_303cf74a60004f02886d991b,content_c20355c29cae4822b3ed5590,content_c86bd90383ec43dea73400ba}', 'Travel Tips & Special Events', '', '{}', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBookSolid.svg', NULL, NULL, '2025-02-11 00:55:45.16+00', '2025-02-11 00:55:45.16+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_hEx5f3LblAjmMtwVyszbJ6T6', 't', 'none', 't', 'user_WBgSAZd8fSGcMLZA49NU0cJ9zEr', '{}', 'Check-in/Check-out', NULL, '{}', 'Our check-in process is quick and efficient, ensuring you settle into your room with ease. Check-out is equally seamless, with staff available to assist you at any time. Flexible options are available upon request.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCalendarCheck.svg', NULL, '{}', '2025-02-11 03:27:22.086+00', '2025-02-11 03:27:22.086+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_e5d79b13896a404fa98a81ba', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Travelling the islands of Samoa', NULL, '{}', '<p>Travelling the islands of Samoa is not just easy, it is a lot of fun. Options include rental cars, hire scooters and the famous Samoan buses. A temporary driver’s licence is WST$21 for 30 days and is a must have for international visitors to the country. You can pick this up when you hire your car and you should carry this on you at all times in case you are stopped. Samoan police officer are probably the most friendly police you will find anywhere in the world and if you are stopped at any time, be ready for a chat about your home place and how great the weather is. The speed limit in Apia is 40 km/h and 50 km/h in less populated areas. It is illegal to use your cell phone while driving. Taxis are also readily available but they are not metered and prices are fixed for certain trips. Around town, expect to pay between WST$5 and WST$12. Remember that taxis only accept cash and often do not have change for larger denominations.The centre of town and behind the flea market is the home of the central bus stop. Samoan buses are a sight to see and an experience to enjoy. With bright colours, loads of bling and often loud music these vehicles offer a wonderful and inexpensive way to travel around the island and are as cheap as WST$4 and up to WST$12 from town to the Mulifanua Ferry terminal where you can take the ferry ride to Savai’i. The trip to Savai’i only takes about an hour and is a fantastic experience, but be sure to book in advance or run the risk of having to wait until a space becomes available. Getting in with the locals on one of these buses or even the ferry, is an awesome experience for visitors and gives an insight into the essence of the people of this country. Full buses will often see people sitting on each other’s laps and generally squeezing up and will leave you with memories that will last a lifetime. In Samoa, life is about happiness, family and enjoyment.</p>', NULL, NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739231025224_375458-riding-local-bus-2-web-1280px.jpg', NULL, '2025-02-10 05:50:11.567339+00', '2025-02-12 23:08:02.515+00');
