INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_hkOqZe2XjI3OeWwmXaL7GIo0', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Swimming Pool', NULL, '{}', 'Take a refreshing dip in our swimming pool, available exclusively to hotel guests. Relax on poolside loungers or enjoy a leisurely swim in a serene and inviting setting.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwimmerSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736375098423_Swimming_Pool_4.png}', '2025-02-12 04:08:11.295+00', '2025-02-12 04:08:11.295+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_OxS5NUuJBUGYlgjit6qC8vK9', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Spa Services', NULL, '{}', 'Indulge in relaxation at our spa, offering a range of rejuvenating treatments, including massages, facials, and body therapies. Reservations are recommended for a truly personalized experience.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaSwatchbookSolid.svg', NULL, '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736819494597_Massage_Grand_Velas_Riviera_Nayarit_Mexico-1024x682.jpg}', '2025-02-12 04:08:11.298+00', '2025-02-12 04:08:11.298+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_Hxnu0fM3XMa7ZdcnLGMyHDyC', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Hotel Policies', NULL, '{}', 'Our policies are designed to ensure a pleasant stay for all guests. Please familiarize yourself with our guidelines on cancellations, pets, and smoking, which are crafted to maintain a safe and comfortable environment.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaFolderPlusSolid.svg', NULL, '{}', '2025-02-12 04:08:11.301+00', '2025-02-12 04:08:11.301+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_oBUyhmpxEXe1EExWBiGwMvbm', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'About the Hotel', NULL, '{}', 'Welcome to our hotel! We are dedicated to providing a comfortable and memorable stay for all our guests. From luxurious accommodations to exceptional service, we strive to exceed your expectations at every turn.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaChartPieSolid.svg', NULL, '{""}', '2025-02-12 04:08:11.306+00', '2025-02-12 04:08:11.306+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_hn0GrZ0aO3ksGUcAzuDnspb3', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Address & Directions', NULL, '{}', 'Located conveniently in the heart of the city, our hotel is easily accessible by car, public transport, or shuttle services. Detailed directions are available on our website, or you can contact the front desk for personalized guidance.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCampgroundSolid.svg', NULL, '{}', '2025-02-12 04:08:11.311+00', '2025-02-12 04:08:11.311+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_GJjak1hqu31OV3uLfetcdTlH', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Welcome', NULL, '{}', 'Dear Guest,\n\nWe are delighted to have you with us at [Hotel Name]. Whether you''re here for business or leisure, our team is dedicated to making your stay both comfortable and memorable.\n\nThis Digital Compendium is designed to be your guide throughout your stay. Here, you''ll find all the essential information you need about our hotel, services, and facilities, as well as tips for exploring the local area.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/ThumbsUp.svg', NULL, '{}', '2025-02-12 04:08:11.314+00', '2025-02-12 04:08:11.314+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_YtkgXs2JpPh794G4v4Fk0Zyy', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Parking Information', NULL, '{}', 'Ample parking is available for all guests, with options for valet or self-parking. Spaces are secure and easily accessible, providing peace of mind for those traveling by car.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSideSolid.svg', NULL, '{}', '2025-02-12 04:08:11.316+00', '2025-02-12 04:08:11.316+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_guSPzfyGNxO81vmYbvrmqfKK', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Public Transport Options', NULL, '{}', 'Our location offers excellent access to public transportation, with nearby bus stops and train stations connecting you to major attractions and business centers. Speak to our concierge for route recommendations.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaShuttleVanSolid.svg', NULL, '{}', '2025-02-12 04:08:11.321+00', '2025-02-12 04:08:11.321+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_6ZUuHPh8GEasaTUJ7AutIfMC', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Shuttle Bus', NULL, '{}', 'We offer convenient shuttle services to and from the airport, as well as popular local destinations. Schedules and pick-up points are designed to align with your itinerary, ensuring hassle-free transport throughout your stay.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCarSolid.svg', NULL, '{}', '2025-02-12 04:08:11.323+00', '2025-02-12 04:08:11.323+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_CC8FM3LnrNaDo9Y7yvoL06vS', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Restaurants', NULL, '{}', 'Delight in our on-site restaurants, where a variety of cuisines are prepared by world-class chefs. Whether you prefer a casual meal or a fine dining experience, our menus cater to all tastes and dietary preferences.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieBiteSolid.svg', NULL, '{}', '2025-02-12 04:08:11.326+00', '2025-02-12 04:08:11.326+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_uXhH2gChSe9DLsbSaLR70rtF', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Room Service', NULL, '{}', 'Enjoy the convenience of room service, offering a wide selection of meals and beverages delivered directly to your door. Available 24/7, it''s perfect for a late-night snack or a relaxing breakfast in bed.\n\n', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaCookieSolid.svg', NULL, '{}', '2025-02-12 04:08:11.329+00', '2025-02-12 04:08:11.329+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_sg2MS21ZRnGwwBuV47HUR3au', 't', 'none', 't', 'user_0000000000004_00000000ADV1', '{}', 'Kids''Activities', NULL, '{}', 'Keep the little ones entertained with our selection of Kids'' activities, from supervised play areas to fun workshops. Our family-friendly environment ensures a memorable stay for guests of all ages.', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaBabySolid.svg', NULL, '{}', '2025-02-12 04:08:11.332+00', '2025-02-12 04:08:11.332+00');
