INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_zRDkWOaqKwktRj6GzYfRMd8I', 'f', 'none', 't', 'user_0000000000004_00000000ADV1', '{content_GJjak1hqu31OV3uLfetcdTlH,content_qpuBxW9PfT50w3lrNYKmwk0K,content_lgpBjBTniCZ3YDA2oZq7Knu6,content_r9wcB30zSWCNR1qVCTUGw6L1,content_KAr2aD8K7I8o5zcVlHEfiX4c,content_qCo8kqIweP9a92ls7TvhS84v}', 'Services & Facilities', NULL, '{}', NULL, 'HotelManagedEndpoint', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/S3Id_1734913147060_3FzlEtGzQRZFgNtQ4G5S39HgBXqhloAOe3o0q80RKPEO9/1736740310217_services-facilities.jpg', '{""}', '2025-02-12 04:08:11.349+00', '2025-02-12 04:08:11.349+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_kHzK0rkpMVB1WtrDElQKzFD6', 'f', 'none', 't', 'user_0000000000004_00000000ADV1', '{00000000000000000000000000000004,content_zRDkWOaqKwktRj6GzYfRMd8I}', 'Public-Content Root OF Cal''s Samoa Dreamhaus', 'Public Content Root OF Cal''s Samoa Dreamhaus', '{}', '', '', '""', '', '', '{}', '2025-02-12 04:08:11.356+00', '2025-02-12 04:08:11.356+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('content_C2Sg1jFy7av7hYYHNXW1Po5O', 't', 'none', 't', 'user_0000000000001_0000000ADMIN', '{}', 'Talofa lava, welcome to Samoa.', '', '{}', '<p><strong>Our warm, friendly culture and breathtaking scenery make Samoa the perfect Pacific Island destination for your holiday.</strong></p><p><br /></p><p>Samoa is truly paradise on earth, with its warm temperature, rich culture, breathtaking scenery and easy access.</p><p><br /></p><p>Samoa has an amazingly diverse food scene with plentiful seafood straight from the ocean, freshly harvested fruits and distinctly incredible flavours. To truly immerse yourself in Samoan culture, try one of our many traditional foods. It’s the perfect way to get a taste of local life.</p><p><br /></p><p>Whether you prefer to unwind by the pool, relax with a massage, visit the markets, enjoy watersports, diving, snorkelling, swim in one of the local water holes, hike to a waterfall, go fishing, watch a show, take a day trip or cultural tour, there is something here for everyone.</p><p><br /></p><p>Samoa’s diverse landscapes will take your breath away. Wherever you go in Samoa, it’ll always be picture perfect.</p><p><br /></p><p>#BeautifulSamoa</p>', NULL, '{}', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/LiaLeafSolid.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739407705600_374666-sitting-on-waterfront-2.jpg', '{}', '2025-02-13 00:50:25.53+00', '2025-02-13 00:57:33.878+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('113dc7bc033b4e228dffce0554b3b98e', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Fannie Bay Gaol', NULL, '{"email": "info@magnt.net.au", "phone": "8 8941 3650", "website": "https://www.magnt.net.au/fannie-bay-gaol"}', 'Fannie Bay Gaol is an historic site. The gaol operated as Her Majesty''s Gaol and Labour Prison, for almost 100 years. Her Majesty''s Gaol and Labour Prison was Darwin''s main prison from 20 September 1883 until 1 September 1979. In 1979 prisoners were relocated to the correctional facility located in Berrimah. Now an important historic site, Fannie Bay Gaol attracts thousands of visitors each year. Male and female prisoners were held in separate buildings from 1928. The female prison block included a small garden designed to keep the prisoners busy. An infirmary was added in 1887, which contained gallows used up until the last executions held in the Northern Territory in 1952. A watch tower, "native section" for Aboriginal prisoners, kitchen mess building, remand section and two maximum security wings were added during the 1950s.', NULL, '{"name": "Fannie Bay Gaol", "type": "entertainment", "latitude": -12.425567327293319, "longitude": 130.8362389}', NULL, NULL, NULL, '2025-01-22 03:06:15.113084+00', '2025-01-22 03:06:15.113084+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('9e8f50bf0d5544b0aa88973f6c6ab790', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Museum and Art Gallery of the Northern Territory', NULL, '{"phone": "08 89998264", "website": "http://www.magnt.net.au/"}', 'The Museum and Art Gallery of the Northern Territory (MAGNT) is the Northern Territory’s premier cultural organisation. Our principal facility since 1981 is on Larrakia Land at Bullocky Point in Darwin, home to internationally renowned cultural and scientific collections and research and exhibition programs. MAGNT also operates the historic Fannie Bay Gaol in Darwin, the Museum of Central Australia incorporating the Strehlow Research Centre in Alice Springs, Megafauna Central and the Alcoota Fossil Bed site north east of Alice Springs. MAGNT also manages the historic Lyons Cottage on Darwin’s Esplanade and the Defence of Darwin Experience at East Point in Darwin. MAGNT attracts over 300,000 visitors annually to our sites.', NULL, '{"name": "Museum and Art Gallery of the Northern Territory", "type": "entertainment", "latitude": -12.435992413322541, "longitude": 130.8331344}', NULL, NULL, NULL, '2025-01-22 03:06:15.133148+00', '2025-01-22 03:06:15.133148+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('ee37f01a53ec485abc0ea70098a2c79e', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Burnett House', NULL, '{"email": "admin@ntnationaltrust.org.au", "phone": "0417 828 449", "website": "https://www.nationaltrust.org.au/places/burnett-house/"}', 'This is the only surviving example of B.C.G. Burnett’s Type ‘K’ and was unusual in being of two-storey configuration. A unique feature is the coloured compass inlay in the ground floor concrete slab. Burnett’s original plans and early photographs indicate a rainwater tank at the rear, near the laundry. The house was damaged by Cyclone Tracy in December 1974. From about 1983 the house remained vacant and was boarded up to prevent access from itinerants until it was restored in 1988 for the National Trust. It was officially opened as the headquarters of the Trust by the Administrator, Commodore Eric Johnston, on 18 April 1989. It then became known as Burnett House, after its designer. Darwin Branch of the National Trust NT manages Burnett House guided tours of the house on a Wednesday and surrounding gardens (see opening times below). Note: Guided tours will resume in 2025 dry season. please contact 0889812848, or send an email admin@ntnationaltrust.org.au Devonshire Teas are held regularly on Sunday afternoons in the beautiful Burnett house gardens throughout the dry season (May – September). Bookings can be made at the above email address, Note: please ring to confirm when they will resume for the 2025 season.', NULL, '{"name": "Burnett House", "type": "entertainment", "latitude": -12.450498878363685, "longitude": 130.8295235}', NULL, NULL, NULL, '2025-01-22 03:06:15.175146+00', '2025-01-22 03:06:15.175146+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('6648ca612a4c4e00b209b448cb0b1412', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Crocosaurus Cove', NULL, '{"phone": "08 89817522", "website": "http://www.croccove.com/", "facebook": "https://www.facebook.com/Crocosaurus.Cove", "instagram": "https://www.instagram.com/crocosauruscove/"}', 'Bringing together some of the largest Saltwater Crocodiles in Australia & boasting the World’s largest display of Australian reptiles, Crocosaurus Cove is a must see attraction when visiting Darwin and the Top End. Bring your bathers and Swim with the Crocs, jump on our Fishing for Crocs platform and smile for the camera while holding a baby Saltwater Crocodile. Check out the Barramundi, Archer Fish & Whiprays in our 200,000 litre fresh water aquarium and visit our turtles in our Top End Turtle Billabong. All of this and more awaits you at Darwin’s ultimate urban wildlife experience…right in the heart of Mitchell Street, Darwin City.', NULL, '{"name": "Crocosaurus Cove", "type": "entertainment", "latitude": -12.462064860740671, "longitude": 130.8391395}', NULL, NULL, NULL, '2025-01-22 03:06:15.280084+00', '2025-01-22 03:06:15.280084+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('6f7eea273e13496490c2bb71be04134d', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'George Brown Darwin Botanic Gardens', NULL, '{"phone": "08 89994418", "website": "https://nt.gov.au/parks/find-a-park/george-brown-darwin-botanic-gardens"}', 'The George Brown Darwin Botanic Gardens are two kilometres north of Darwin city. The gardens cover 42 hectares and are noted for their collections of north Australian and other tropical species. The Visitor and Event Centre is located near the Gardens Road main car park. It is air conditioned and a great place to learn about Territory history, plants and seasons. The centre includes: a mini amphitheatre, event space, retail gift shop, interpretive centre to learn about the history of the gardens. You can collect maps and information about self-guided walks at the visitor centre gift shop.', NULL, '{"name": "George Brown Darwin Botanic Gardens", "type": "parks_and_nature", "latitude": -12.444338652762276, "longitude": 130.8364123}', NULL, NULL, NULL, '2025-01-22 03:06:15.45123+00', '2025-01-22 03:06:15.45123+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('922cd0767aee467c97e40c33f865bbec', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Survivors’ Lookout', NULL, '{"website": "https://placesofpride.awm.gov.au/memorials/267512"}', 'Darwin Survivors Lookout, WWII memorial 1939-45 and history of Darwin', NULL, '{"name": "Survivors’ Lookout", "type": "entertainment", "latitude": -12.466891538170268, "longitude": 130.8447255}', NULL, NULL, NULL, '2025-01-22 03:06:15.472172+00', '2025-01-22 03:06:15.472172+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('c1fcabe8951d464ab0dee217a9cf307f', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Parap Village Markets', NULL, '{"phone": "0438 882 373", "website": "https://parapvillage.com.au/"}', '<p>Offering the finest tropical flavours and true Territory atmosphere, the Parap Village Markets run every Saturday 8am – 2pm (rain or shine) all year round. Sample the tantalizing tastes of local and exotic dishes, fruit salads and smoothies and fresh roasted coffee. Browse the diverse range of fresh produce available at market prices and enjoy locally grown vegetables, herbs, Asian greens and exotic fruit the likes you’ve never seen, or select from a range of stunning tropical flowers to warm your home. Catch up with friends to the backdrop of ambient live music then wander through the markets to discover a precious collection of Territory crafts including clothing, jewellery and gems, artworks, beauty products, specialist crafts, plants and cut flowers, massage, tarot and much more. Proudly supporting local made arts and crafts, with the highest percentage of Terrritory products of all the Darwin markets. The Parap Village Market experience – an essential part of your visit to Darwin or local weekend routine.</p>', NULL, '{"name": "Parap Village Markets", "type": "shop", "latitude": -12.430943946932109, "longitude": 130.8446159}', NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166809507_parap.png', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739166814197_parap.png}', '2025-01-22 03:06:15.55521+00', '2025-02-10 05:53:56.525+00');
INSERT INTO public."content" (id, "isLeaf", "layoutStyle", visible, editable, attributes, name, description, contact, "mainText", "searchTags", "geoLocation", "iconImage", "bannerImage", "carouselImages", "createdAt", "updatedAt") VALUES ('e8f9aa4ea4db4a4eaddbbc613213624d', 't', 'none', 't', 'user_0000000000003_0000FREEUSER', '{}', 'Rendezvous Cafe', 'Authentic Malaysian and Thai cuisine.', NULL, '<p><strong>Rendezvous Cafe</strong> is a family owned business run out of the heart of Darwin''s shopping district. It has been apart of Darwin''s dining scene for the past 30+ years. Rendezvous has been serving it''s current fantastic menu of Asian dishes since 2007. It boasts deliciously authentic Malaysian and Thai cuisine prepared to order and is best known to the locals for its amazing Laksa Noodle Soup. Whether you are looking to come in for a relaxed lunch or dinner or just stop by to pick up some tasty take away Rendezvous Cafe is ready to serve.</p>', NULL, NULL, 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/public/spot_icons/Dine.svg', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734730521852_ren01.jpg', '{https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734730528763_ren01.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734730537020_ren04.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734730546944_ren05.jpg,https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/AustinChen/1734730551841_ren06.jpg}', '2025-01-22 03:06:17.188236+00', '2025-02-13 06:06:40.361+00');
