INSERT INTO public.article (id, name, image, description, paragraphs, "createdAt", "updatedAt") VALUES
('article_1734655806324_cqL48gBzRTB3kJxmWyjFP9GDwdtuqNQjGDeZQTSOvH', 'GEOGRAPHE BAY', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734655690822_fadzai-saungweme-RESEQty1uvc-unsplash.jpg', 'The sheltered shores of Geographe Bay', '[{"type": "text", "detail": "<h1>Busselton Heritage Park &amp; Trail</h1>"}, {"type": "text", "detail": "<p class=\"ql-align-justify\"><span class=\"ql-size-large\">The Heritage Park &amp; Trail starts at the corner of Peel Terrace and Causeway Road,Busselton, and features a range of sculptures where the past meets the present. The Heritage Trail also includes the Aboriginal Interpretive Gardens, Ballarat Steam Engine, St Mary’s Anglican Church and Pioneer Cemetery. Pick up a copy of the Busselton Heritage Trail guide book from the Busselton Visitor Centre.</span></p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734655758525_pexels-digitalbuggu-172872.jpg"}, {"type": "text", "detail": "<h1>Busselton Museum</h1>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Located at the Heritage Butter Factory, the Busselton Museum showcases many interesting displays of historical photographs and relics. Open Wednesday to Monday, 10am-4pm. Entry fee applies.</span></p>"}]', '2025-01-22 03:11:30.887213 +00:00', '2025-01-22 03:11:30.887213 +00:00'),
('article_1734918922311_OtjeTzDDGBz6406CPq2fs14nOpkQ2DXuEu5YVjItDP', 'KOKOPO & RABAUL', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734918623328_Screenshot%202024-12-23%20at%2012.50.16%C3%A2%C2%80%C2%AFPM.png', 'The capital of East New Britain is Kokopo', '[{"type": "text", "detail": "<h3>The capital of East New Britain is Kokopo, which lies in proximity to the original capital of Rabaul. Rabaul was famously destroyed in the volcanic eruptions of Tavurvur and Vulcan back in September 1994. Today, both townships provide a perfect base from which to explore the region.</h3>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">East New Britain is a great place to birdwatch as it is home to a number of exotic birds including the renowned hornbill and megapode, among other species. The caves in the region are regarded as world class, so be sure to check out the caves at Pomio which can be accessed by boat or vehicle.</span></p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734918896603_Screenshot%202024-12-23%20at%2012.54.47%C3%A2%C2%80%C2%AFPM.png"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">If diving is your passion, the WWII wrecks that litter the reefs surrounding East New Britain offer diving and snorkelling with excellent visibility year round. Simpson Harbour, the location where 54 Japanese ships were sunk during the war effort, and the Beehives (a small group of craggy islands) both offer great diving. Tavui Point, once an official submarine base, provides fantastic snorkelling over Japanese submarines.</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Sport fishing for marlin and dogtooth tuna is available in the waters around both New Britain and Duke of York Islands. Boats operate from Rabaul, and hotels and guesthouses can also organise trips for you. The beautiful Duke of York Islands are remote but easy to access. The islands are also perfect for canoeing, swimming and snorkelling with accommodation available on some.</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Don’t miss the Baining Fire Dance, which is routinely performed at night and showcases young men wearing distinctive masks dancing energetically in and out of fire. The dance is believed to be a rite of passage for Baining progeny and is</span></p><p><span class=\"ql-size-large\">performed to spirited chanting and drumming.</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Held in July each year, the National Mask Festival pays homage to the sacred masks of the region. While the Warwagira Music Festival doesn’t have quite the same profile as the Mask Festival, it is just as much fun. The Frangipani Festival held in September each year, features sing-sings, a parade and much more. You can’t miss the new Kokopo Show held in September each year.</span></p>"}]', '2025-01-22 03:11:30.908825 +00:00', '2025-01-22 03:11:30.908825 +00:00'),
('article_1734917805389_h9kjIRZE8XGnmkLG7guPwiK0xSkwnuQ89S8qgxbfkU', 'PNG ACTIVITIES', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734917492431_Screenshot%202024-12-23%20at%2012.31.24%C3%A2%C2%80%C2%AFPM.png', 'PNG is flush with amazing dives sites from Port Moresby', '[{"type": "text", "detail": "<h3>DIVING</h3><p>PNG is flush with amazing dives sites, from Port Moresby and Tufi in the south to Madang and the islands in the north. If you’re an avid diver be sure to check out Der Yang wreck at Echuca Patch in Kavieng, the B17 Blackjack at Cape Vogel, Susie’s Bommie off Port Moresby, Milne Bay for manta rays and muck diving, and Kilibob’s Knob in Kimbe Bay for its shark dive.</p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734917771147_Screenshot%202024-12-23%20at%2012.35.57%C3%A2%C2%80%C2%AFPM.png"}, {"type": "text", "detail": "<h3>SURFING</h3><p>For over 15 years, PNG has been capturing the hearts of surf enthusiasts. The most consistent waves are in Vanimo with surf camps also set up at Wewak and Aitape. Bougainville, East New Britain, New Ireland and Manus Island also serve up great surf.</p><p><br></p><h3>FISHING</h3><p>From the rivers to the oceans, PNG offers the ultimate fishing experience. The coastal waters offer abundant bluewater and big game fishing such as marlin, sailfish, yellow fin tuna, giant trevally and dogtooth tuna. Meanwhile, the black bass, reputed to be one of the world’s toughest fighting fish, can be found in the Fly, Sepik and Lower Ramu Rivers.</p>"}, {"type": "text", "detail": "<h3>TREKKING</h3><p>PNG offers many exciting options for the avid hiker, from trekking dense rainforests and rugged peaks, to long-distance coastal walks with ocean views. Try the famous Kokoda Track, Mount Wilhelm – PNG’s highest peak, the Rotokas-Numa Trail or Trans-New Britain Track.</p><p><br></p><h3>BIRDWATCHING</h3><p>Many visitors to PNG are attracted to the region for its birdwatching or ‘birding’ as it’s known among enthusiasts. Considering there are more than 700 species on record, it’s little wonder the activity is so immensely popular. The renowned bird of paradise, among other beautiful species, is what brings serious birders to PNG.</p>"}, {"type": "text", "detail": "<h3>AIRPORT CUSTOMS</h3><p>At Jackson’s International Airport, it’s compulsory for all incoming visitors to fill out a passenger declaration for goods entering the country. The types of items that will need to be declared are: Goods that are prohibited or restricted: firearms; weapons such as flick knives; flora and fauna; agricultural products such as all flora, foods (canned, fresh, smoked), animal byproducts; biological products; and medicines (ensure you have a prescription from your doctor on hand).</p><p><br></p><ul><li>• Goods that exceed K1000 allowance</li><li>• Goods deemed for business or trade purposes</li><li>• Tobacco products that exceed 250gms or over 250 cigarettes</li><li>• Alcoholic beverages exceeding more than 2 litres.</li></ul>"}, {"type": "text", "detail": "<p>For visitors importing goods into PNG, all items must be claimed at customs by completing an import declaration form. In terms of taking goods home, many countries such as Australia, New Zealand, Canada, Fiji and Singapore restrict the importation of much the same items as PNG. It’s advised that all items made from plant material and wood are inspected and treated prior to leaving PNG.</p>"}, {"type": "text", "detail": "<h3>MOBILE COVERAGE &amp; DEALS</h3><p>PNG has three major network service providers - B-mobile Vodafone, Telikom PNG and Digicel with 4G Long Term Evolution (LTC) coverage. For phone sales visit: Digicel Papua New Guinea, Bmobile, Telikom PNG, Fone Haus, Huawei, Brian Bell, Rapidfones, Phone Tech, Cool Stuff, CHM &amp; Sons, Star Office Works, Pacific Tech. and RapidFones. </p><p><br></p><h3>SECURITY</h3><p>In larger cities, be sure to keep your car doors locked and windows up while driving. Don’t leave any valuables in cars. Don’t walk around alone at night.</p>"}]', '2025-01-22 03:11:30.932028 +00:00', '2025-01-22 03:11:30.932028 +00:00'),
('article_1734656243277_TqPAEKePY5Y9aOFZxiFo9pr4mXMKgMr3f1TEfpcVAo', 'WARRNAMBOOL', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734656174853_pexels-just-icelandic-19989453.jpg', 'Located on the shores of beautiful Lady Bay', '[{"type": "text", "detail": "<p>Clean sheltered beaches, manicured parks and gardens, visiting whales, Maremma guardian dogs, notorious shipwrecks, unique volcanoes, contemporary art, exhilarating sports and a thriving city centre are just some of the reasons why thousands of people visit Warrnambool each year to experience this vibrant coastal city.</p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734656236550_pexels-boonkong-boonpeng-442952-1134176.jpg"}, {"type": "text", "detail": "<p>Warrnambool is the ideal location for exploring nature’s finest attractions: spectacular stretches of coastline, beautiful swimming beaches, wildlife reserves, lush rainforests and waterfalls, volcanic lakes and rural landscapes. Warrnambool is well known for the Southern Right Whale Nursery. Once hunted almost to the point of extinction, these gentle creatures now return to the shores off Logans Beach to give birth. They can be seen from a viewing platform annually during the months of May to September.</p>"}]', '2025-01-22 03:11:30.965866 +00:00', '2025-01-22 03:11:30.965866 +00:00'),
('article_1734914396082_YS1p18XeX44g0IdLjp1A5IP5SZlN7jrQV7nEjEP5Am', 'Cullen Bay', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734913932583_Screenshot%202024-12-23%20at%2011.32.04%C3%A2%C2%80%C2%AFAM.png', 'This is a great introduction to Cullen Bay with overview', '[{"type": "text", "detail": "<h1>Cullen Bay</h1>"}, {"type": "text", "detail": "<h2>Cullen Bay is less known for its cuisine, but it is probably one of the best places to go for a meal. It is not as busy in Cullen Bay, so visitors can wander in, look at the menus and ask for a table.</h2>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734914164127_Screenshot%202024-12-23%20at%2011.35.57%C3%A2%C2%80%C2%AFAM.png"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Phat Joint, Yot’s, Ebb and Flow and Damsquino’s are all names synonymous with quality dining. Ebb and Flow offers plant based delicious meals and offers live music, sun lounges and wine on a quiet and relaxing afternoon. Lola’s is also a well known venue, but it can be noisy if you are looking to enjoy a quiet lunch or dinner. The most famous restaurant in Cullen Bay is Seafood on Cullen and is a massive seafood restaurant which has direct sunset views, an outdoor verandah and great quality food. Kids are very welcome here too and can go out and play on the grassed area while parents can see them from the verandah.</span></p>"}]', '2025-01-22 03:11:30.988999 +00:00', '2025-01-22 03:11:30.988999 +00:00'),
('article_1734917109567_wvb0h0nlMnfZR3YRiHHmjtTHdXFknvXg16fNXVpBbZ', 'PORT MORESBY', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734916952630_Screenshot%202024-12-23%20at%2012.22.23%C3%A2%C2%80%C2%AFPM.png', 'Port Moresby is a transient hub that sees visitors come and go.', '[{"type": "text", "detail": "<h2>As the capital of PNG, and the first place visitors see on arrival to the region, Port Moresby is a transient hub that sees visitors come and go.</h2>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734917095813_Screenshot%202024-12-23%20at%2012.24.44%C3%A2%C2%80%C2%AFPM.png"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Prior to colonisation, the region was a trading port for the Motuan people who sustained their existence by sailing to villages in boats to trade ceramics for food and canoe logs.</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Whether you’re here for a day or longer, there’s a range of interesting attractions on offer to satisfy your curiosity. For an outing with the family, try the Port Moresby Nature Park or Port Moresby Adventure Park that lies several kilometres beyond the airport. If you’re a birding enthusiast, you can spot a variety of species along the walks in Varirata National Park.</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">If you’re in Port Moresby around mid-September for PNG’s Independence Day, the city plays host to the Hiri Moale Festival. Get along to immerse yourself in PNG’s diverse and rich culture.</span></p>"}]', '2025-01-22 03:11:31.040981 +00:00', '2025-01-22 03:11:31.040981 +00:00'),
('article_1734915739934_DssFHKQnF0EzO5dQhEQ2MbdgdigV3fjMiLfI1waDtz', 'Crab Claw Island', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734915608886_Screenshot%202024-12-23%20at%2012.00.02%C3%A2%C2%80%C2%AFPM.png', 'Crab Claw Island is a magnificent part of the Northern Territory', '[{"type": "text", "detail": "<h1>Crab Claw Island &amp; Resort</h1>"}, {"type": "text", "detail": "<p class=\"ql-align-justify\"><span class=\"ql-size-large\">Crab Claw Island is a magnificent part of the Northern Territory located on the Cox Peninsula, just 135km southwest of Darwin by road, 15 minutes by air, or two hours by quick boat. Truly unique, it is an island accessible by road except on extreme high tides. It is surrounded by 2500km2 of pristine waterways which include Bynoe Harbour, salt water estuaries and fresh water creeks and rivers.</span></p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734916164118_Screenshot%202024-12-23%20at%2012.09.17%C3%A2%C2%80%C2%AFPM.png"}, {"type": "text", "detail": "<p class=\"ql-align-justify\"><span class=\"ql-size-large\">Crab Claw Island is home to Crab Claw Island Resort. Nestled on the water’s edge, Crab Claw Island Resort is a relaxing escape from the everyday. The complex has elevated cabins overlooking a white sandy beach connected by walkways through the trees and palm gardens, refreshing swimming pools, an open air restaurant and bar with views across the harbour, private boat ramp to access the fabulous fishing, all surrounded by wildlife and pristine natural beauty.</span></p>"}, {"type": "text", "detail": "<p class=\"ql-align-justify\"><span class=\"ql-size-large\">Crab Claw caters for those who love the outdoors. You can go bushwalking around the island, hunt for monster mud crabs, go for a dip in one of the two refreshing pools or when in season watch the turtles lay their eggs on a nearby beach. However, Crab Claw’s main attraction has got to be fishing. The island is a fishing dream. A popular way to spend the day is to fish until dusk, and then eat your catch. With over 30 species of fish in the harbour, including Barramundi and crab, you’re spoilt for choice when baiting dinner.</span></p>"}]', '2025-01-22 03:12:05.966146 +00:00', '2025-01-22 03:12:05.966146 +00:00'),
('article_H7vKu1lkTHpoP2rbTlUY1Qg3', 'Dining Out Lakes Entrance', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739140916849_Screenshot%202025-02-10%20at%209.41.45%C3%A2%C2%80%C2%AFAM.png', 'There are plenty of dining options in Lakes Entrance offering !', '[{"type": "text", "detail": "<h2 class=\"ql-align-center\">Dining Out Lakes Entrance</h2>"}, {"type": "text", "detail": "<h3 class=\"ql-align-center\">There are plenty of dining options in Lakes Entrance offering everything from local seafood to international cuisine to the quintessential fish and chips.</h3>"}, {"type": "text", "detail": "<p>Lakes Entrance has always been a fishing town. From scallops to flathead and a myriad of other seafoods, the town has been at the heart of Victoria’s fishing industry. The town hosts the largest fishing port in the south east of Australia and fishing and tourism are the economic lifeblood of the region. Hundreds of tonnes of seafood is transported throughout Victoria that originates from Lakes Entrance or its nearby waterways.</p>"}, {"type": "text", "detail": "<p>But what used to be shipped off to be eaten by consumers overseas or interstate has spawned a cottage industry in Lakes Entrance in the form of new cafes and restaurants that showcase local produce.</p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739141774586_Screenshot%202025-02-10%20at%209.47.07%C3%A2%C2%80%C2%AFAM.png"}, {"type": "text", "detail": "<p>A ‘foodies paradise’ is how the town is sometimes referred to now. Where else can you feast on shellfish harvested just offshore in the pristine waters of the Southern Ocean, not far from where you are eating them, garnished in garlic and Gipplsand butter?</p>"}, {"type": "text", "detail": "<p>Restaurants cater to all tastes and budgets and enjoying the local produce is a must when in the town. Among the most well-known venues are Albert and Co, a beachside café and restaurant that overlooks Cunninghame Arm and also boasts a cocktail bar. Other places that are firmly on the agenda for a food-lover heading to the town are the Lakes Sports and Community Club, Awesome Fish and Chips or Froggy’s Bistro. The local bowls club and RSL are also known for the dining options. Why not take a short drive out to the Wyanga Park Winery, located just a few kilometres from the town centre, where you can tuck into some fabulous food accompanied by their distinctive wines? It’s nice to know the places others recommend, but the best way to experience what Lakes Entrance has to offer is to explore the region yourself. Walk along The Esplanade and let your nose guide you.</p>"}]', '2025-02-09 22:56:19.784000 +00:00', '2025-02-09 22:56:19.784000 +00:00'),
('article_BScE2Krh3n0ycJVkrzGIcayD', 'The Buchan Caves', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739144646425_Screenshot+2025-02-10+at+10.21.56%C3%A2%C2%80%C2%AFAM.png', 'Nestled in the foothills of the Snowy River Valley!', '[{"type": "text", "detail": "<h2 class=\"ql-align-center\">The Buchan Caves</h2>"}, {"type": "carousel", "detail": ["https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739144748343_Screenshot%202025-02-10%20at%2010.26.28%C3%A2%C2%80%C2%AFAM.png", "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739144754726_Screenshot+2025-02-10+at+10.26.40%C3%A2%C2%80%C2%AFAM.png"]}, {"type": "text", "detail": "<p>Nestled in the foothills of the Snowy River Valley, you will find Buchan Caves Reserve. Be it winter, spring, summer, or autumn, there is always something to see and do here. The reserve is a wonderful winter retreat in a valley sheltered from prevailing winds. The caves maintain a constant temperature of 17 degrees Celsius, making them perfect for visiting on a cold, rainy, or hot summer’s day. In spring, the reserve bursts back to life as the many deciduous trees are adorned with new foliage, and the wildlife becomes more active.</p><p class=\"ql-align-justify\"><br></p>"}, {"type": "text", "detail": "<p>A place not to be missed after heavy rainfall is the Spring Creek Waterfall. Royal and Fairy Caves also take on a whole new dimension after heavy rain, when the rainwater finds its way into the caves, dripping from the ceiling and flowing down the walls. On a hot summer’s day, enjoy a dip in the reserve’s refreshing stream-fed swimming pool, then have a barbecue and relax in the shade of one of the lush trees.</p>"}, {"type": "text", "detail": "<p>During autumn, the reserve is at its most spectacular when the colorful leaves fall from the deciduous trees, creating a vibrant carpet underfoot. Buchan Caves Reserve boasts an impressive system of walking tracks, ranging from short and easy walks to those a bit more challenging. Along the walking tracks, you may sight lyrebirds, kookaburras, echidnas, kangaroos, or Gippsland water dragons. Even if you are not lucky enough to spot a lyrebird, you will most certainly hear their many sounds.</p>"}, {"type": "text", "detail": "<p>Be sure to check out Fairy Cave and Royal Cave while you’re at the reserve. Their stunning limestone formations are a feat of nature, offering a memorable holiday experience. So, for a day packed full of fun, visit Buchan Caves Reserve.</p>"}]', '2025-02-09 23:57:32.371000 +00:00', '2025-02-09 23:57:32.371000 +00:00'),
('article_pP0jauS0gxYhks3aoY6q2lBa', 'Exploring the Waters', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739145544396_Screenshot%202025-02-10%20at%2010.58.56%C3%A2%C2%80%C2%AFAM.png', 'Explore the waters by taking a cruise or try fishing by dropping', '[{"type": "text", "detail": "<h2 class=\"ql-align-center\">Exploring the Waters</h2>"}, {"type": "text", "detail": "<p class=\"ql-align-justify\">Explore the waters by taking a cruise or try fishing by dropping a line at one of the jetties. There''s so much opportunity in the region to spend time on the water and explore the aquatic life up close. Make sure you relax by booking a cruise around the lakes.</p>"}, {"type": "text", "detail": "<p class=\"ql-align-justify\">The Gippsland Lakes region is also renowned for fishing, so it is little wonder tourists try their hand at one of the piers that adjoin the Esplanade or Kalimna Jetty. The Post Office pier is a local favorite and, using prawns or sandworms as bait, it is not uncommon to see people hauling fish in. Fish can be caught at all times of the year in the lakes, but remember that the best time to try your hand at prawning is from November to May. There’s also plenty of fishing along the beaches and rivers in the area.</p>"}, {"type": "carousel", "detail": ["https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739145753434_Screenshot%202025-02-10%20at%2011.02.11%C3%A2%C2%80%C2%AFAM.png", "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739145757608_Screenshot%202025-02-10%20at%2011.02.21%C3%A2%C2%80%C2%AFAM.png"]}, {"type": "text", "detail": "<p class=\"ql-align-justify\">Fishing for bream and boating around the lakes are popular activities in the Twin Rivers district. With the Nicholson and Tambo Rivers running through the region, it’s no wonder visitors are water-bound. To explore the water from an aesthetic point of view, stop in at the Nicholson River Winery, which overlooks the picturesque Nicholson River for a tasting and lunch.</p>"}, {"type": "text", "detail": "<p class=\"ql-align-justify\">Crabbing is a popular pastime, especially at Sandblasting Jetty on Bullock Island. Just make sure you have a current fishing license and only 2 hoop nets are allowed per person. There’s no associated size limit, but only 30 crabs per person are allowed.</p><p class=\"ql-align-justify\">Please be mindful that cooking seafood is often not permitted in accommodation rooms. Ask a staff member whether an outdoor area and utensils are available for use.</p>"}]', '2025-02-09 23:57:47.849000 +00:00', '2025-02-10 00:03:43.344000 +00:00'),
('article_KqcqgcX1TfbP6zalGw5bTrIi', 'EXPLORING APIA', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146531149_Screenshot%202025-02-10%20at%2011.15.21%C3%A2%C2%80%C2%AFAM.png', 'Apia is the capital of Samoa and home to around 37,000 residents', '[{"type": "text", "detail": "<h2 class=\"ql-align-center\">Exploring Apia</h2>"}, {"type": "text", "detail": "<p><strong>Exploring Apia</strong></p><p>Apia, the capital of Samoa, is home to around 37,000 residents and serves as the perfect base from which to explore this stunning island nation. The city offers a unique blend of traditional housing and modern architecture. As a bustling hub, Apia boasts plenty of shopping, fantastic eateries, and a range of entertainment options. Be sure to catch one of the Fiafia cultural events in town for a wonderful night of food, singing, and dancing, which is at the very heart of Samoan culture.</p>"}, {"type": "carousel", "detail": ["https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146846166_Screenshot%202025-02-10%20at%2011.20.08%C3%A2%C2%80%C2%AFAM.png", "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146851034_Screenshot%202025-02-10%20at%2011.20.18%C3%A2%C2%80%C2%AFAM.png", "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146855778_Screenshot%202025-02-10%20at%2011.20.29%C3%A2%C2%80%C2%AFAM.png"]}, {"type": "text", "detail": "<p><strong>Natural and Historical Attractions</strong></p><p>Just outside the town center lies the Palolo Deep Marine Reserve, a popular spot for swimming, snorkeling, and diving. This blue hole showcases some of the remarkable marine life and coral in the region, with shower amenities and snorkeling equipment available for visitors. History buffs should visit the Museum of Samoa to view historical and cultural artifacts housed in a colonial-style building, open Monday to Friday from 9:30 am to 4:00 pm, with free admission.</p><p>Robert Louis Stevenson Museum and Botanical Gardens</p><p>Don’t miss the Robert Louis Stevenson Museum in Vailima, just a couple of minutes from town. Nearby, you can also explore the Vailima Botanical Gardens, which cover 12 hectares of lush tropical flora featuring both indigenous and introduced species. After visiting the gardens, enjoy a dip in a natural water hole or trek up to Robert Louis Stevenson’s tomb at the peak of Mt. Vaea.</p>"}, {"type": "text", "detail": "<p><strong>Robert Louis Stevenson Museum and Botanical Gardens</strong></p><p>Don’t miss the Robert Louis Stevenson Museum in Vailima, just a couple of minutes from town. Nearby, you can also explore the Vailima Botanical Gardens, which cover 12 hectares of lush tropical flora featuring both indigenous and introduced species. After visiting the gardens, enjoy a dip in a natural water hole or trek up to Robert Louis Stevenson’s tomb at the peak of Mt. Vaea.</p>"}, {"type": "text", "detail": "<p><strong>Practical Tips</strong></p><p>If you’re planning to drive to the other side of the island, make sure to refuel in Apia, as most businesses, including service stations, only accept cash. However, car hire services, hotels, and some restaurants do accept credit cards. For more travel and tour information, visit the Samoa Tourism Visitor Information Fale located on Beach Road in the heart of Apia.</p>"}]', '2025-02-10 00:21:47.318000 +00:00', '2025-02-10 00:21:47.318000 +00:00'),
('article_1IaGgKzuds17cteBHkN4hk4K', 'WELCOME TO SAMOA', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146094799_Screenshot%202025-02-10%20at%2011.08.03%C3%A2%C2%80%C2%AFAM.png', 'Samoa is an island nation steeped in beauty and natural attracti', '[{"type": "text", "detail": "<h3>Samoa is an island nation steeped in beauty and natural attractions. It’s the perfect place to explore a unique culture, and relax and unwind from everyday life.</h3>"}, {"type": "text", "detail": "<p>Samoa is comprised of ten islands, with Upolu and Savai’i being the largest in the nation. Apia on Upolu is the capital, and the official languages are Samoan—a Polynesian language—and English, which is spoken in an official capacity. Migratory patterns suggest that the first Samoans traveled from Southeast Asia around 3,000 years ago. Between 950 AD and 1250 AD, Tonga ruled over the province of Samoa until a final battle saw the Samoans overthrow their oppressor. In retreat, the Tongans made a vow only to return in peace and honored their word. Today, the Malietoa Monument at Le Vasa Resort commemorates this final battle and enduring peace between the two nations. The monument is also a great place to watch a beautiful Samoan sunset.</p>"}, {"type": "carousel", "detail": ["https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146357393_Screenshot+2025-02-10+at+11.12.05%C3%A2%C2%80%C2%AFAM.png", "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739146362882_Screenshot+2025-02-10+at+11.12.14%C3%A2%C2%80%C2%AFAM.png"]}, {"type": "text", "detail": "<p>Proud people with an equally proud culture, the only outside influence that has affected Samoan culture occurred with the arrival of missionaries in the 1800s. The missionaries introduced modern religion to the country, and Samoa reformed and embraced Fa’Samoa or “the Samoan way,” which is centered around the Matai (Chiefs), family, and church life.</p>"}, {"type": "text", "detail": "<p>In the 1890s, renowned author Robert Louis Stevenson settled his family in Samoa. When the author died, his death was commemorated extensively, and in Vailima today, you can visit Stevenson’s plantation home, which is now a museum. During World War I, New Zealand became administrators of German Samoa in a military occupation driven by Britain. In 1927, the League of Samoa was founded in response to Samoans wanting independence. Samoa finally gained independence as a nation in 1962.</p>"}, {"type": "text", "detail": "<p>Samoa is a destination that graciously welcomes visitors, where people are met with smiling faces, and food and music are central to the Samoan way of life. The Samoan Siva is an elegant dance that shouldn’t be missed during your visit to the region. Samoa’s laid-back lifestyle is a drawcard for visitors wanting to relax and unwind in a tropical paradise. Rich in natural beauty, Samoa offers pristine beaches, picturesque waterfalls, lush rainforests, and fascinating marine life to explore.</p><p>The word “Samoa” comes from two Polynesian words; “Sa” meaning sacred and “Moa” meaning center. Enjoy your time in this sacred center of the planet.</p>"}]', '2025-02-10 00:12:58.666000 +00:00', '2025-02-12 23:54:45.854000 +00:00'),
('article_GWeWfxIfANldKw7zW7NjKhps', 'GETTING AROUND', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739147280561_Screenshot%202025-02-10%20at%2011.25.20%C3%A2%C2%80%C2%AFAM.png', 'Travelling the islands of Samoa is not just easy, lot of fun.', '[{"type": "text", "detail": "<p><strong>Driving in Samoa</strong></p><p>For international visitors planning to drive, a temporary driver’s license is a necessity. It can be obtained for WST$21 and is valid for 30 days. You can pick up your license when you hire your car and it''s essential to carry it at all times in case you are stopped by the police. Samoan police officers are known for being exceptionally friendly, and if you are stopped, you might find yourself having a pleasant chat about your hometown and the local weather. The speed limit in Apia is 40 km/h, and in less populated areas, it''s 50 km/h. Remember, it is illegal to use your cell phone while driving.</p>"}, {"type": "image", "detail": "https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1739147130559_Screenshot%202025-02-10%20at%2011.25.20%C3%A2%C2%80%C2%AFAM.png"}, {"type": "text", "detail": "<p><strong>Public Transportation</strong></p><p>The heart of Apia''s public transport is located in the center of town, behind the flea market, where you’ll find the central bus stop. Samoan buses are renowned for their bright colors, decorative bling, and often loud music, providing a unique and budget-friendly way to explore the island. Fares are as low as WST$4 and can go up to WST$12 for a trip from town to the Mulifanua Ferry terminal. From there, you can catch a ferry to Savai’i. The ferry trip takes about an hour and offers a fantastic experience, though it’s advisable to book in advance to avoid delays.</p>"}, {"type": "text", "detail": "<p><strong>Local Experience</strong></p><p>Traveling on a Samoan bus or ferry provides a genuine insight into the local lifestyle and is highly recommended for visitors. Buses can be quite full, leading to an intimate setting where people might end up sitting on each other’s laps, creating memorable and joyous interactions. In Samoa, life is centered around happiness, family, and enjoyment, which is vividly reflected in these communal travel experiences.</p>"}, {"type": "text", "detail": "<p><strong>Taxi Services</strong></p><p>Taxis are readily available throughout Apia but note that they are not metered. Fares are fixed for certain trips, ranging from WST$5 to WST$12. It''s important to have cash on hand as taxis do not accept other forms of payment and may not have change for larger bills.</p>"}, {"type": "text", "detail": "<h2 class=\"ql-align-center\"><span class=\"ql-font-serif\">Getting Around</span></h2>"}]', '2025-02-10 00:27:31.504000 +00:00', '2025-02-13 00:45:52.910000 +00:00'),
('article_1734915485192_fwxlcY1aav2CHzz1XQt0sa1QWiJbyCnfycOC4xciY5', 'Territory Wildlife Park', 'https://pladdypusv2.s3.ap-southeast-2.amazonaws.com/JBG_superadmin/1734915083573_Screenshot%202024-12-23%20at%2011.51.08%C3%A2%C2%80%C2%AFAM.png', 'Your ultimate Darwin wildlife experience !', '[{"type": "text", "detail": "<h1>Territory Wildlife Park</h1>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">The Park showcases the natural wonders of the “Top End” where you’ll see the animals and natural habitats of this place we call home. You’ll be amazed by the picturesque beauty of Park, and appreciate that you can see the “Top End” in a few hours rather than a few days!</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">Here the wildlife exhibits are integrated within the natural environment, so you’ll see pelicans, freshwater crocodiles, fish and turtles happily cruising around a natural ‘Billabong’. You’ll meet hand-raised friendly wallabies in the ‘Woodland Walk’, and see a variety of water birds at ‘Goose Lagoon’. In the air conditioned aquarium you’ll take a journey from the small rock pools of the Arnhem Land Escarpment, down through streams and tributaries, into the larger rivers of the</span></p><p><span class=\"ql-size-large\">“Top End”, and then out to the coral reefs. A tunnel exhibit allows you to ‘walk under a river’ where freshwater whiprays, barramundi and a host of other fish swim over your head. You’ll also meet ‘Graham’ the 4 metre crocodile, resident at the Park for over 25 years.</span></p>"}, {"type": "text", "detail": "<p><span class=\"ql-size-large\">If birds are your fancy, a walk through the Monsoon Forest aviaries will not disappoint. 12 walk-through aviaries are beautifully landscaped to show detail and diversity. Highlights include the brightly coloured Gouldian finches. A large dome aviary filled with hundreds of birds concludes the sequence as visitors walk a spiral down to the ground through the tree tops on an elevated boardwalk.</span></p>"}]', '2025-01-22 03:11:31.018131 +00:00', '2025-02-13 01:09:31.289000 +00:00');
